import ctypes
import sys

#避免多开
def is_program_running():
    # 创建互斥体
    mutex_name = "Global\\MonitorClientMutex"
    h_mutex = ctypes.windll.kernel32.CreateMutexW(None, False, mutex_name)
    # 检查互斥体是否已经存在
    if ctypes.windll.kernel32.GetLastError() == 183:  # ERROR_ALREADY_EXISTS
        print("程序已经在运行.")
        return True
    return False

if is_program_running():
    ctypes.windll.user32.MessageBoxTimeoutW(
        None, "程序已经运行.....请留意屏幕右下角任务栏系统托盘图标.", "警告", 0x40 | 0x1, 0, 4000
    )
    print("程序已经运行.....请留意屏幕右下角任务栏系统托盘图标.")
    # time.sleep(5)
    # showinfo('notice', '程序启动中...')
    sys.exit(0)

class ToolTip:
    def __init__(self, widget, text):
        self.widget = widget
        self.text = text
        self.tipwindow = None
        self.id = None
        self.x = self.y = 0
        self.widget.bind('<Enter>', self.showtip)
        self.widget.bind('<Leave>', self.hidetip)

    def showtip(self, event=None):
        x, y, _, _ = self.widget.bbox("insert")
        x += self.widget.winfo_rootx() + 25
        y += self.widget.winfo_rooty() + 20
        # 创建 tooltip 窗口
        self.tipwindow = tw = tk.Toplevel(self.widget)
        tw.wm_overrideredirect(1)  # 去除窗口边框
        tw.wm_geometry("+%d+%d" % (x, y))
        label = tk.Label(tw, text=self.text, background="#ffffe0", relief='solid', borderwidth=1)
        label.pack(ipadx=1)

    def hidetip(self, event=None):
        tw = self.tipwindow
        self.tipwindow = None
        if tw:
            tw.destroy()


#qr-code  #import qrcode  #from PIL import Image  #生成二维码图片
def make_qr(str,save):
    qr=qrcode.QRCode(
        version=4,    #生成二维码尺寸的大小 1-40  1:21*21（21+(n-1)*4）
        error_correction=qrcode.constants.ERROR_CORRECT_M,
        #L:7% M:15% Q:25% H:30%
        box_size=10,     #每个格子的像素大小
        border=2,   #边框的格子宽度大小
    )
    qr.add_data(str)
    qr.make(fit=True)
    img=qr.make_image()
    img.save(save)

#生成带logo的二维码图片
def make_logo_qr(str,logo,save):
    #参数配置
    qr=qrcode.QRCode(
        version=4,
        error_correction=qrcode.constants.ERROR_CORRECT_Q,
        box_size=8,
        border=2
    )
    #添加转换内容
    qr.add_data(str)
    qr.make(fit=True)
    #生成二维码
    img=qr.make_image()
    img=img.convert("RGBA")
    #添加logo
    if logo and os.path.exists(logo):
        icon=Image.open(logo)
        #获取二维码图片的大小
        img_w,img_h=img.size
        factor=4
        size_w=int(img_w/factor)
        size_h=int(img_h/factor)
        #logo图片的大小不能超过二维码图片的1/4
        icon_w,icon_h=icon.size
        if icon_w>size_w:
            icon_w=size_w
        if icon_h>size_h:
            icon_h=size_h
        icon=icon.resize((icon_w,icon_h),Image.ANTIALIAS)
        #详见：http://pillow.readthedocs.org/handbook/tutorial.html      #计算logo在二维码图中的位置
        w=int((img_w-icon_w)/2)
        h=int((img_h-icon_h)/2)
        icon=icon.convert("RGBA")
        img.paste(icon,(w,h),icon)
        #详见：http://pillow.readthedocs.org/reference/Image.html#PIL.Image.Image.paste
    #保存处理后图片
    img.save(save)

