    #getword
    urlgetword = "https://aip.baidubce.com/rest/2.0/ocr/v1/doc_convert/get_request_result?access_token=" + token
    payload = {'task_id':mytask}
    headers = {
        'Content-Type': 'application/x-www-form-urlencoded',
        'Accept': 'application/json'
    }
    time.sleep(7)
    responsew = requests.request("POST", urlgetword, headers=headers, data=payload)
