    def allinsamrsheet():
        import copy
        from tkinter import filedialog, messagebox
        import openpyxl
        from openpyxl.formula.translate import Translator
        from openpyxl.utils import get_column_letter
        directory = filedialog.askdirectory() + '/'
        # txtoftgtget.delete(0, 'end')
        # txtoftgtget.insert(0, directory)

        allxls = []
        for r, d, filenames in os.walk(directory):
            for file in filenames:
                if file.endswith('.xlsx'):
                    allxls.append(os.path.join(r, file))

        messagebox.showinfo('提示', '把要合并的表复制到指定文件夹，5秒后-输出合并到指定文件夹里final_excel.xlsx.')
        time.sleep(5)

        end_xls = directory + "final_excel.xlsx"

        max_sheets = 0
        file_info_list = []

        for filepath in allxls:
            try:
                wb = openpyxl.load_workbook(filepath)
                sheet_count = len(wb.sheetnames)
                max_sheets = max(max_sheets, sheet_count)
                file_info_list.append((filepath, wb))
            except Exception as e:
                print(f"打开文件错误 {filepath}: {e}")

        endwb = openpyxl.Workbook()
        if 'Sheet' in endwb.sheetnames:
            del endwb['Sheet']

        for sheet_idx in range(max_sheets):
            target_ws = endwb.create_sheet(f'Sheet{sheet_idx + 1}')
            current_row = 1

            for filepath, wb in file_info_list:
                if sheet_idx < len(wb.sheetnames):
                    source_ws = wb[wb.sheetnames[sheet_idx]]
                    start_row = current_row

                    # 复制列宽
                    for col_letter, col_dim in source_ws.column_dimensions.items():
                        if col_dim.width and col_dim.width > 0:
                            target_ws.column_dimensions[col_letter].width = col_dim.width

                    # 复制行高
                    for row_num, row_dim in source_ws.row_dimensions.items():
                        if row_dim.height and row_dim.height > 0:
                            target_ws.row_dimensions[start_row + row_num - 1].height = row_dim.height

                    # 复制单元格数据、公式和样式
                    for row in source_ws.iter_rows():
                        for cell in row:
                            target_cell = target_ws.cell(row=current_row, column=cell.column)

                            if cell.value is not None:
                                if isinstance(cell.value, str) and cell.value.startswith('='):
                                    try:
                                        # 使用翻译器让公式的行列引用对应变化
                                        origin_coord = cell.coordinate
                                        target_coord = target_cell.coordinate
                                        new_formula = Translator(cell.value, origin=origin_coord).translate_formula(
                                            target_coord)
                                        target_cell.value = new_formula
                                    except Exception:
                                        target_cell.value = cell.value
                                else:
                                    target_cell.value = cell.value

                            # 复制字体、边框、填充色等样式
                            if cell.has_style:
                                target_cell.font = copy.copy(cell.font)
                                target_cell.border = copy.copy(cell.border)
                                target_cell.fill = copy.copy(cell.fill)
                                target_cell.number_format = copy.copy(cell.number_format)
                                target_cell.protection = copy.copy(cell.protection)
                                target_cell.alignment = copy.copy(cell.alignment)

                        current_row += 1

                    # 复制合并单元格并计算偏移量
                    for merged_range in source_ws.merged_cells.ranges:
                        new_min_row = merged_range.min_row + start_row - 1
                        new_max_row = merged_range.max_row + start_row - 1
                        new_range = f"{get_column_letter(merged_range.min_col)}{new_min_row}:{get_column_letter(merged_range.max_col)}{new_max_row}"
                        target_ws.merge_cells(new_range)

        endwb.save(end_xls)

        for filepath, wb in file_info_list:
            wb.close()

        messagebox.showinfo('提示', '输出合并结果到指定文件夹里final_excel.xlsx-完成.')
        os.startfile(end_xls)


    def allzhuanzhi():
        import openpyxl
        from openpyxl.utils import get_column_letter
        from copy import copy
        from tkinter.messagebox import showinfo
        from tkinter.filedialog import askdirectory
        showinfo('提示', '首先选择批量表文件xlsx来源.然后等待转置，最后输出到同目录.')
        pilzhuanzhiwhere = askdirectory() + '/'
        txtoftgtget.delete(0, 'end')
        txtoftgtget.insert(0, pilzhuanzhiwhere)
        dirname = pilzhuanzhiwhere
        dirnameout = pilzhuanzhiwhere
        filenames = os.listdir(dirname)

        def zhuanzhione(filename, output_filename):
            # 使用 data_only=True 读取公式的缓存计算结果，从而只保留数值
            wb = openpyxl.load_workbook(filename, data_only=True)
            ws = wb.active  # 默认处理第一个sheet

            new_wb = openpyxl.Workbook()
            new_ws = new_wb.active

            max_row = ws.max_row
            max_col = ws.max_column

            # 遍历并转置单元格内容及样式
            for r in range(1, max_row + 1):
                for c in range(1, max_col + 1):
                    cell = ws.cell(row=r, column=c)
                    new_cell = new_ws.cell(row=c, column=r, value=cell.value)

                    # 保留格式和颜色
                    if cell.has_style:
                        new_cell.font = copy(cell.font)
                        new_cell.border = copy(cell.border)
                        new_cell.fill = copy(cell.fill)
                        new_cell.number_format = cell.number_format
                        new_cell.protection = copy(cell.protection)
                        new_cell.alignment = copy(cell.alignment)

            # 处理合并单元格的转置
            for merged_range in ws.merged_cells.ranges:
                new_min_row = merged_range.min_col
                new_min_col = merged_range.min_row
                new_max_row = merged_range.max_col
                new_max_col = merged_range.max_row
                new_ws.merge_cells(start_row=new_min_row, start_column=new_min_col,
                                   end_row=new_max_row, end_column=new_max_col)

            # 转置列宽和行高，使用近似公式保持视觉比例
            for c in range(1, max_col + 1):
                col_letter = get_column_letter(c)
                if col_letter in ws.column_dimensions:
                    width = ws.column_dimensions[col_letter].width
                    if width:
                        new_ws.row_dimensions[c].height = width * 1.2

            for r in range(1, max_row + 1):
                if r in ws.row_dimensions:
                    height = ws.row_dimensions[r].height
                    if height:
                        new_ws.column_dimensions[get_column_letter(r)].width = height * 0.125

            # 保存新文件并关闭工作簿释放资源
            new_wb.save(output_filename)
            wb.close()

        for filename in filenames:
            if filename.endswith('xlsx') or filename.endswith('XLSX'):
                base, ext = filename.split('.')
                new_name = '转置后-' + base + '.' + ext
                full_filename = os.path.join(dirname, filename)
                output_filename = os.path.join(dirnameout, new_name)
                zhuanzhione(full_filename, output_filename)
                print(full_filename)

        showinfo('提示', '所有表文件转置完成。')

    def getmycellsdata():
        from pandas.core.frame import DataFrame
        # 获取用户选择的目录路径
        pathtogetcellofFile = askdirectory() + '/'
        txtoftgtget.delete(0, 'end')
        txtoftgtget.insert(0, pathtogetcellofFile)
        allfile3 = []
        def getallfile(path):
            try:
                allfilelist = os.listdir(path)
            except Exception as e:
                print(f"无法访问路径: {path}, 错误信息: {e}")
                return
            for file in allfilelist:
                filepath = os.path.join(path, file)
                if os.path.isdir(filepath):
                    getallfile(filepath)  # 递归遍历子目录
                else:
                    allfile3.append(filepath)
        # 开始收集所有文件
        path2 = pathtogetcellofFile
        getallfile(path2)
        print("所有文件：", allfile3)

        def get_range_data(filename, sheetname, range_start, range_end):
            """
            读取指定Excel文件中的某个sheet内某段区域的数据。
            返回二维列表。
            """
            try:
                wb = openpyxl.load_workbook(filename, data_only=True)
                ws = wb[sheetname]

                data = []
                for row in ws[range_start:range_end]:
                    data_row = [cell.value for cell in row]
                    data.append(data_row)
                wb.close()
                return data
            except Exception as e:
                print(f"读取失败: {filename} - {str(e)}")
                return []
        # 获取输入控件的内容
        sheetname = var4tgtgetsheet.get()
        cell01 = var2tgtgetcell.get().strip()  # 左上角单元格 如 A1
        cell02 = var3tgtgetcell.get().strip()  # 右下角单元格 如 B3
        results = []
        for item3 in allfile3:
            if item3.endswith('.xlsx') and not item3.startswith('~$'):  # 忽略临时打开的文件
                try:
                    range_data = get_range_data(item3, sheetname, cell01, cell02)
                    if range_data:
                        # 展平成一行记录
                        flat_row = [item for sublist in range_data for item in sublist]
                        flat_row.append(item3)  # 添加文件名
                        flat_row.append(sheetname)  # 添加sheet名称
                        results.append(flat_row)
                except Exception as e:
                    print(f"处理文件时发生错误: {item3} - {str(e)}")
        if not results:
            showinfo("提示", "未找到有效数据或发生错误。")
            return
        # 构造列标题：按区域生成列名（如 A1_B3）
        max_cols = len(results[0]) - 2  # 不包括 filename 和 sheetname 列
        col_names = [f"{cell01}_to_{cell02}_{i + 1}" for i in range(max_cols)]
        col_names += ['filename', 'sheetname']
        df = pd.DataFrame(results, columns=col_names)
        output_file = '抽取单元格输出文件1.xlsx'
        df.to_excel(output_file, index=False)
        showinfo('提示', '指定目录和子目录里所有表指定单元提取完成。')
        os.startfile(output_file)

