    def colorcount():
        # from openpyxl import load_workbook
        excel_file = askopenfilename(title='选一个xlsx表文件', defaultextension='.xlsx')
        excelfrontname = excel_file.split('.')[-2]
        wb = openpyxl.load_workbook(excel_file, data_only=True)
        cell06 = var6colorcode.get()
        # global cell07
        cell07 = var7colorcodesname.get()

        zdycolor = str(cell06) if cell06 else ''  # 确保是字符串
        zdycolornum = 0
        # Create new workbook for output
        from openpyxl.styles import PatternFill
        from openpyxl import Workbook
        output_wb = Workbook()

        output_wb.remove(output_wb.active)

        for sheet_name in wb.sheetnames:
            original_sheet = wb[sheet_name]
            # Create new sheet in output workbook
            output_sheet = output_wb.create_sheet(title=sheet_name)
            # Process each row in the current sheet
            for i in range(1, original_sheet.max_row + 1):
                row_data = []
                zdycolornum = 0  # Reset counter for each row
                for j in range(1, original_sheet.max_column + 1):
                    try:
                        cell_obj = original_sheet.cell(i, j)
                        cell_fill = cell_obj.fill
                        # 检查是否有填充颜色
                        if hasattr(cell_fill, 'fgColor') and hasattr(cell_fill.fgColor, 'rgb'):
                            cell_color = cell_fill.fgColor.rgb
                        else:
                            cell_color = None
                        # 处理颜色值为空的情况
                        if cell_color is None or cell_color == '00000000' or cell_color == '00FFFFFF':
                            cell_color = 'FFFFFF'  # Default to white
                        elif not isinstance(cell_color, str):
                            cell_color = str(cell_color)
                        thislineis = '第%s行_%s格 %s' % (i, j, cell_color)
                        print(thislineis, end=' ')
                        # 安全的颜色匹配检查
                        if zdycolor and zdycolor.upper().replace('#', '') in cell_color.upper().replace('#', ''):
                            zdycolornum += 1
                        row_data.append(thislineis)
                    except Exception as e:     # 如果获取颜色时出错，使用默认值
                        cell_color = 'FFFFFF'
                        thislineis = '第%s行_%s格 %s' % (i, j, cell_color)
                        print(thislineis, end=' ')
                        row_data.append(thislineis)
                        print(f"获取颜色时出错: {e}")
                # Add count information
                count_info = '选色个数 %s' % zdycolornum
                row_data.append(count_info)
                # Write the row data to output sheet
                for col_idx, value in enumerate(row_data, start=1):
                    output_sheet.cell(row=i, column=col_idx, value=str(value))
                    # If it's the last column (count column), apply the specified color
                    if col_idx == len(row_data):  # This is the last column
                        fill = PatternFill(start_color=zdycolor.replace('#', ''),
                                           end_color=zdycolor.replace('#', ''),
                                           fill_type="solid")
                        output_sheet.cell(row=i, column=col_idx).fill = fill
                print('选色个数是%s' % zdycolornum)

        outfilenamecolor = '%s_颜色统计表.xlsx' % excelfrontname
        output_wb.save(outfilenamecolor)
        time.sleep(2)
        os.startfile('%s_颜色统计表.xlsx' % excelfrontname)

