    def cut_excel_file(file_path, rows_per_file_body):
        import copy
        import re
        # 提取文件名（不含扩展名）作为子目录名
        dir_name = os.path.splitext(os.path.basename(file_path))[0]
        target_dir = os.path.join(os.path.dirname(file_path), dir_name)
        os.makedirs(target_dir, exist_ok=True)
        # 使用openpyxl读取原始文件以保持格式和公式
        wb = openpyxl.load_workbook(file_path, keep_vba=True, keep_links=True, data_only=False)
        ws = wb.active
        # 获取原始工作表的总行数（不包括标题行）
        total_rows = ws.max_row
        # 如果只有标题行，则直接复制整个文件
        if total_rows <= 1:
            file_name = f"part_1.xlsx"
            target_file_path = os.path.join(target_dir, file_name)
            wb.save(target_file_path)
            return
        # 计算需要分割成多少个文件
        header_row_count = 1  # 假设第一行为标题行
        data_rows_count = total_rows - header_row_count
        num_files = (data_rows_count + rows_per_file_body - 1) // rows_per_file_body  # 向上取整

        # 保存所有图片信息
        all_images = []
        for img in ws._images:
            all_images.append(img)

        for i in range(num_files):
            start_row = header_row_count + 1 + i * rows_per_file_body
            end_row = min(header_row_count + (i + 1) * rows_per_file_body, total_rows)
            # 创建新的工作簿
            new_wb = openpyxl.Workbook()
            new_ws = new_wb.active
            # 复制列宽
            for col in ws.column_dimensions:
                new_ws.column_dimensions[col].width = ws.column_dimensions[col].width
            # 复制行高
            for row in ws.row_dimensions:
                if row >= start_row and row <= end_row:
                    new_row_index = row - start_row + 2  # 调整到新工作表中的行号（标题行+数据行）
                    new_ws.row_dimensions[new_row_index].height = ws.row_dimensions[row].height
            # 复制标题行
            for col_idx in range(1, ws.max_column + 1):
                cell = ws.cell(row=header_row_count, column=col_idx)
                new_ws.cell(row=1, column=col_idx).value = cell.value
                # 复制单元格样式
                if cell.has_style:
                    new_ws.cell(row=1, column=col_idx).font = copy.copy(cell.font)
                    new_ws.cell(row=1, column=col_idx).border = copy.copy(cell.border)
                    new_ws.cell(row=1, column=col_idx).fill = copy.copy(cell.fill)
                    new_ws.cell(row=1, column=col_idx).number_format = cell.number_format
                    new_ws.cell(row=1, column=col_idx).protection = copy.copy(cell.protection)
                    new_ws.cell(row=1, column=col_idx).alignment = copy.copy(cell.alignment)
            # 复制数据行
            current_row_in_new_sheet = 2
            for row_idx in range(start_row, end_row + 1):
                for col_idx in range(1, ws.max_column + 1):
                    cell = ws.cell(row=row_idx, column=col_idx)
                    new_cell = new_ws.cell(row=current_row_in_new_sheet, column=col_idx)
                    # 复制值（如果是公式则保留公式并调整引用）
                    if cell.data_type == 'f':  # 公式
                        original_formula = str(cell.value)
                        adjusted_formula = adjust_formula_references(original_formula, start_row,
                                                                     current_row_in_new_sheet)
                        new_cell.value = adjusted_formula
                        new_cell.data_type = 'f'
                    else:
                        new_cell.value = cell.value
                    # 复制单元格样式
                    if cell.has_style:
                        new_cell.font = copy.copy(cell.font)
                        new_cell.border = copy.copy(cell.border)
                        new_cell.fill = copy.copy(cell.fill)
                        new_cell.number_format = cell.number_format
                        new_cell.protection = copy.copy(cell.protection)
                        new_cell.alignment = copy.copy(cell.alignment)
                current_row_in_new_sheet += 1
            # 复制相关的图片
            for img in all_images:
                # 根据不同的锚点类型处理图片位置
                if hasattr(img, 'anchor'):
                    anchor = img.anchor
                    # 检查图片锚点类型并提取行列信息
                    if hasattr(anchor, '_from'):
                        # TwoCellAnchor 类型
                        from_col = anchor._from.col
                        from_row = anchor._from.row
                        to_col = anchor._to.col
                        to_row = anchor._to.row
                        # 检查图片是否在当前分块范围内
                        if (start_row <= from_row <= end_row) or (start_row <= to_row <= end_row):
                            # 计算在新表中的相对位置
                            new_from_row = from_row - start_row + 2  # +2 因为标题行占一行，且行号从1开始
                            new_to_row = to_row - start_row + 2
                            # 确保调整后的行号有效
                            new_from_row = max(1, new_from_row)
                            new_to_row = max(1, new_to_row)
                            # 创建新图片对象
                            new_img = copy.deepcopy(img)
                            # 更新图片锚点位置
                            new_img.anchor._from.row = new_from_row
                            new_img.anchor._to.row = new_to_row
                            new_ws.add_image(new_img)
                    elif hasattr(anchor, 'col') and hasattr(anchor, 'row'):
                        # OneCellAnchor 类型
                        img_col = anchor.col
                        img_row = anchor.row
                        # 检查图片是否在当前分块范围内
                        if start_row <= img_row <= end_row:
                            # 计算在新表中的相对位置
                            new_img_row = img_row - start_row + 2  # +2 因为标题行占一行，且行号从1开始
                            # 确保调整后的行号有效
                            new_img_row = max(1, new_img_row)
                            # 创建新图片对象
                            new_img = copy.deepcopy(img)
                            # 更新图片锚点位置
                            new_img.anchor.col = img_col
                            new_img.anchor.row = new_img_row
                            new_ws.add_image(new_img)
            # 保存新文件
            file_name = f"part_{i + 1}.xlsx"
            target_file_path = os.path.join(target_dir, file_name)
            new_wb.save(target_file_path)
        # 关闭原始工作簿
        wb.close()

    def adjust_formula_references(formula, original_start_row, new_row_offset):
        """
        调整公式中的单元格引用，使其适应新的行位置
        """
        import re
        # 匹配单元格引用的正则表达式 (如 A1, B2, $A$1, A$1, $A1 等)
        cell_ref_pattern = r'(\$?[A-Z]+\$?\d+)'
        def replace_reference(match):
            ref = match.group(1)
            # 分离列和行部分
            col_part = ''
            row_part = ''
            # 提取列部分（字母）
            for char in ref:
                if char.isalpha() or char == '$':
                    col_part += char
                else:
                    break
            # 提取行部分（数字）
            row_part = ref[len(col_part):]
            # 检查是否有绝对引用标记
            has_dollar_before_col = '$' in col_part and not col_part.endswith('$')
            has_dollar_before_row = '$' in row_part
            # 如果是绝对引用，则不调整
            if has_dollar_before_col and has_dollar_before_row:
                return ref
            # 如果只有列是绝对引用，则不调整行
            if has_dollar_before_col and not has_dollar_before_row:
                return ref
            # 如果只有行是绝对引用，则不调整
            if has_dollar_before_row:
                return ref
            # 转换行号
            original_row = int(row_part)
            # 只有当原始行在数据范围内时才进行调整
            if original_row >= original_start_row:
                # 计算相对于起始行的偏移量
                relative_row = original_row - original_start_row + 2  # +2 因为新表中数据从第2行开始
                new_row = relative_row
                return col_part + str(new_row)
            return ref
        # 替换公式中的所有单元格引用
        adjusted_formula = re.sub(cell_ref_pattern, replace_reference, formula)
        return adjusted_formula

    def select_file_and_cut():
        # 弹出文件选择对话框
        file_path = askopenfilename(filetypes=[("Excel files", "*.xlsx *.xls")])
