    def manyxlsxs_manysheets2afile_inmanysheets(srcdir=None, outpath=None, quiet=False):
        """多文件多子表合到单件多子表(工作簿) —— OOXML(zip)级保真合并。

        不用 openpyxl他破坏结构.
        外部链接、定义名会全部丢掉），而是把每个 xlsx 当 zip：
          * 子表 XML、drawings、charts、media 图片、comments、tables、printerSettings
            等部件按原文搬运（只做必要的下标改写），边框/字体/填充/局部边框/行高列宽/
            合并单元格/条件格式规则本身一个字节都不重排；
          * styles.xml 做并集：fonts/fills/borders/cellStyleXfs/cellXfs/dxfs/命名样式
            按“重映射后的原文”去重合并，再把每个单元格的 s= 和 cfRule 的 dxfId= 改成新下标；
          * sharedStrings.xml 拼接，t="s" 单元格的 <v> 加偏移，富文本 <r> 原样保留；
          * WPS 嵌入式单元格图片 cellimages.xml 合并，DISPIMG 的 ID 原样带走（撞 ID 才改名）；
          * externalLinks 合并，公式里的 [n] 下标按新顺序改写，外链缓存原样保留；
          * 子表名规则：名字互不相同就都用原名（不在前面加文件名）；名字相同、内容也
            完全相同的只保留一份（不重复搬）；名字相同但内容确实不同的才改成
            “文件名_表名”，并把该文件公式里对旧表名的引用一起改掉（去重、改名全写日志）；
          * 数据连接 / Power Pivot 数据模型整套跟第一个真带它的文件走（模型是二进制整体，
            并不了），它引用的表格名先占住不被改名；挂在工作簿上的 customXml、批注作者、
            切片器等关系也一并搬过来。
        落盘前做结构自检 + 下标越界检查，落盘后回读校验，不合格就不留坏文件。
        """
        import os, re, zipfile, posixpath, hashlib
        from xml.etree import ElementTree as _ET
        from tkinter.filedialog import askdirectory, asksaveasfilename
        from tkinter.messagebox import showinfo

        T_NS = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships/'
        WPS_CELLIMAGE = 'http://www.wps.cn/officeDocument/2020/cellImage'
        REL_DECL = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\r\n'
        REL_ROOT = '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
        # 一个 XML 开/闭标签（属性值里的 > 不会误判）
        _XF_TAG_RE = re.compile(r'<(/?)([A-Za-z_][\w.:-]*)((?:"[^"]*"|[^>"])*)>')
        # 公式里的表名引用：'表 名'! 或 表名!
        _XF_SHEETREF_RE = re.compile(r"'((?:[^']|'')*)'!|([A-Za-z_\u0080-\uffff][\w.\u0080-\uffff]*)!")

        # ---------------- 低层工具 ----------------
        def _xf_attr(tag, name):
            m = re.search(r'(?:^|\s)' + re.escape(name) + r'\s*=\s*"([^"]*)"', tag)
            return m.group(1) if m else None

        def _xf_setattr(raw, name, val):
            """改属性值；val=None 表示删掉这个属性。只动第一次出现（即开标签里的那个）。"""
            m = re.search(r'(?:^|\s)' + re.escape(name) + r'\s*=\s*"[^"]*"', raw)
            if not m:
                if val is None:
                    return raw
                m2 = re.match(r'<[A-Za-z_][\w.:-]*', raw)
                return raw[:m2.end()] + ' %s="%s"' % (name, val) + raw[m2.end():]
            seg = raw[m.start():m.end()]
            if val is None:
                return raw[:m.start()] + raw[m.end():]
            return raw[:m.start()] + re.sub(r'"[^"]*"', '"%s"' % val, seg, count=1) + raw[m.end():]

        def _xf_unesc(s):
            if s is None or '&' not in s:
                return s
            s = re.sub(r'&#([0-9]+);', lambda m: chr(int(m.group(1))), s)
            s = re.sub(r'&#[xX]([0-9a-fA-F]+);', lambda m: chr(int(m.group(1), 16)), s)
            for a, b in (('&lt;', '<'), ('&gt;', '>'), ('&quot;', '"'), ('&apos;', "'")):
                s = s.replace(a, b)
            return s.replace('&amp;', '&')

        def _xf_esc_text(s):
            return s.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;')

        def _xf_esc_attr(s):
            return _xf_esc_text(s).replace('"', '&quot;')

        def _xf_read_pkg(path):
            z = zipfile.ZipFile(path)
            try:
                parts, infos, order = {}, {}, []
                for info in z.infolist():
                    if info.is_dir():
                        continue
                    nm = info.filename.replace('\\', '/')
                    parts[nm] = z.read(info)
                    infos[nm] = info
                    order.append(nm)
            finally:
                z.close()
            return parts, infos, order

        def _xf_rels_name(part):
            d, _, b = part.rpartition('/')
            return (d + '/_rels/' if d else '_rels/') + b + '.rels'

        def _xf_owner_of(rels_name):
            d, _, b = rels_name.rpartition('/')
            if b.endswith('.rels'):
                b = b[:-5]
            if d.endswith('/_rels'):
                d = d[:-6]
            elif d == '_rels':
                d = ''
            return (d + '/' + b) if d else b

        def _xf_rels(parts, part):
            rn = _xf_rels_name(part)
            if rn not in parts:
                return []
            txt = parts[rn].decode('utf-8', 'replace')
            out = []
            for m in re.finditer(r'<Relationship\b[^>]*>', txt):
                tag = m.group(0)
                out.append({'id': _xf_attr(tag, 'Id'), 'type': _xf_attr(tag, 'Type') or '',
                            'target': _xf_attr(tag, 'Target'), 'mode': _xf_attr(tag, 'TargetMode'),
                            'raw': tag})
            return out

        def _xf_resolve(part, target):
            if not target:
                return None
            if target.startswith('/'):
                return posixpath.normpath(target[1:])
            d = part.rpartition('/')[0]
            return posixpath.normpath((d + '/' if d else '') + target)

        def _xf_root(txt):
            i = 0
            if txt.lstrip().startswith('<?'):
                i = txt.index('?>', txt.index('<?')) + 2
            m = re.compile(r'<[A-Za-z_][\w.:-]*(?:"[^"]*"|[^>"])*>').search(txt, i)
            if not m:
                return '', '', '', 0, len(txt)
            root = m.group(0)
            if root.endswith('/>'):
                return txt[:m.start()], root, '', m.end(), m.end()
            name = re.match(r'<([A-Za-z_][\w.:-]*)', root).group(1)
            last = None
            for cm in re.finditer(r'</' + re.escape(name) + r'\s*>', txt):
                last = cm
            if not last:
                return txt[:m.start()], root, '', m.end(), len(txt)
            return txt[:m.start()], root, last.group(0), m.end(), last.start()

        def _xf_children_in(txt, a, b):
            """txt[a:b] 里顶层子元素的原文列表（原样切块，不解析、不重排、不改一个字节）。
            自闭合子元素（<numFmt .../> 这种）也算一个，别漏。"""
            res, depth, st = [], 0, -1
            for m in _XF_TAG_RE.finditer(txt, a, b):
                tag = m.group(0)
                if m.group(1):  # 闭标签
                    depth -= 1
                    if depth == 0 and st >= 0:
                        res.append(txt[st:m.end()])
                        st = -1
                elif tag.endswith('/>'):  # 自闭合
                    if depth == 0:
                        res.append(txt[m.start():m.end()])
                else:  # 开标签
                    if depth == 0:
                        st = m.start()
                    depth += 1
            return res

        def _xf_children(txt):
            _, _, _, a, b = _xf_root(txt)
            return _xf_children_in(txt, a, b)

        def _xf_union_ns(root_tag, others):
            """把其它源文件同类部件根标签上的命名空间声明补进来，
            免得搬过来的子元素用了这边没声明的前缀（合并后就是非法 XML）。"""
            if not root_tag:
                return root_tag
            have = set(x.strip() for x in re.findall(r'(?:^|\s)(xmlns(?::[\w.\-]+)?)\s*=', root_tag))
            add = []
            for o in others:
                if not o:
                    continue
                for m in re.finditer(r'(?:^|\s)(xmlns(?::[\w.\-]+)?)\s*=\s*"([^"]*)"', o):
                    if m.group(1) not in have:
                        have.add(m.group(1))
                        add.append(' %s="%s"' % (m.group(1), m.group(2)))
            if not add:
                return root_tag
            if root_tag.rstrip().endswith('/>'):
                return root_tag.rstrip()[:-2].rstrip() + ''.join(add) + '/>'
            return root_tag.rstrip()[:-1].rstrip() + ''.join(add) + '>'

        def _xf_coll(txt, tag):
            """取 <tag ...> 的顶层子元素原文列表。"""
            m = re.search(r'<%s\b[^>]*?>' % tag, txt)
            if not m:
                return [], None
            if m.group(0).endswith('/>'):
                return [], m.group(0)
            e = txt.find('</%s>' % tag, m.end())
            if e < 0:
                return [], m.group(0)
            return _xf_children_in(txt, m.end(), e), m.group(0)

        def _xf_closure(parts, roots):
            keep, stack = set(), [r for r in roots if r]
            while stack:
                p = stack.pop()
                if p in keep:
                    continue
                keep.add(p)
                rn = _xf_rels_name(p)
                if rn in parts:
                    keep.add(rn)
                    for rel in _xf_rels(parts, p):
                        if rel['mode'] != 'External':
                            t = _xf_resolve(p, rel['target'])
                            if t and t not in keep:
                                stack.append(t)
            return {k for k in keep if k in parts}

        # ---------------- 公式改写 ----------------
        def _xf_fix_formula(body, ext_map=None, name_map=None, id_map=None):
            """公式文本（XML 原文）里只改三样：外链下标 [n]、被改名的表名、DISPIMG 图片 ID。
            字符串字面量里的内容一律不动。"""
            if not body:
                return body
            raw = _xf_unesc(body)
            changed = False
            if id_map:
                for old, new in id_map.items():
                    if old in raw:
                        raw = raw.replace(old, new)
                        changed = True
            if not (ext_map or name_map):
                return _xf_esc_text(raw) if changed else body
            out, i, n = [], 0, len(raw)
            while i < n:
                ch = raw[i]
                if ch == '"':  # 字符串字面量整段跳过
                    j = raw.find('"', i + 1)
                    j = n - 1 if j < 0 else j
                    out.append(raw[i:j + 1])
                    i = j + 1
                    continue
                if ext_map and ch == '[':
                    m = re.match(r'\[(\d+)\]', raw[i:])
                    if m:
                        old = int(m.group(1))
                        new = ext_map.get(old, old)
                        out.append('[%d]' % new)
                        i += m.end()
                        changed = changed or new != old
                        continue
                if name_map and (ch == "'" or ch.isalpha() or ch == '_' or ord(ch) > 127):
                    if not (i and raw[i - 1] == ']'):  # [1]表名! 是外部工作簿的表，不动
                        m = _XF_SHEETREF_RE.match(raw, i)
                        if m:
                            old = m.group(1).replace("''", "'") if m.group(1) is not None else m.group(2)
                            if old in name_map:
                                out.append("'%s'!" % name_map[old].replace("'", "''"))
                                i = m.end()
                                changed = True
                                continue
                out.append(ch)
                i += 1
            return _xf_esc_text(''.join(out)) if changed else body

        def _xf_remap_attr(tag, attr, mp, span):
            v = _xf_attr(tag, attr)
            if v is None or not v.isdigit() or not mp:
                return None
            nv = mp.get(int(v))
            if nv is None or nv == int(v):
                return None
            m2 = re.search(r'((?:^|\s)' + re.escape(attr) + r'\s*=\s*")\d+(")', tag)
            if not m2:
                return None
            return (span[0], span[1], tag[:m2.start(1)] + m2.group(1) + str(nv) + m2.group(2) + tag[m2.end():])

        def _xf_rewrite_sheet(txt, mp):
            """子表 XML 定点改写：只动 s= / dxfId= / t="s" 的 <v> / 公式文本 / tabSelected / vm=。"""
            xf_map, dxf_map = mp.get('xf') or {}, mp.get('dxf') or {}
            sst_map = mp.get('sst') or {}
            ext_map, name_map, id_map = mp.get('ext'), mp.get('name'), mp.get('img')
            strip_tab, strip_vm = mp.get('tab'), mp.get('vm')
            if not (xf_map or dxf_map or sst_map or ext_map or name_map or id_map or strip_tab or strip_vm):
                return txt
            edits, cur_s = [], False
            for m in _XF_TAG_RE.finditer(txt):
                tag, name = m.group(0), m.group(2)
                if m.group(1):
                    continue
                selfclose = tag.endswith('/>')
                if name == 'c':
                    cur_s = (_xf_attr(tag, 't') == 's')
                    nt = tag
                    e = _xf_remap_attr(nt, 's', xf_map, (0, 0))
                    if e:
                        nt = e[2]
                    if strip_vm and ' vm="' in nt:
                        nt = re.sub(r'\svm="\d+"', '', nt)
                    if nt != tag:
                        edits.append((m.start(), m.end(), nt))
                elif name == 'row':
                    e = _xf_remap_attr(tag, 's', xf_map, (0, 0))
                    if e:
                        edits.append((m.start(), m.end(), e[2]))
                elif name == 'cfRule':
                    e = _xf_remap_attr(tag, 'dxfId', dxf_map, (0, 0))
                    if e:
                        edits.append((m.start(), m.end(), e[2]))
                elif name == 'sheetView' and strip_tab and 'tabSelected' in tag:
                    edits.append((m.start(), m.end(), re.sub(r'\stabSelected="[^"]*"', '', tag)))
                elif name in ('f', 'formula', 'formula1', 'formula2') and not selfclose:
                    c = txt.find('</%s>' % name, m.end())
                    if c > 0:
                        body = txt[m.end():c]
                        nb = _xf_fix_formula(body, ext_map, name_map, id_map)
                        if nb != body:
                            edits.append((m.end(), c, nb))
                elif name == 'v' and not selfclose and cur_s and sst_map:
                    c = txt.find('</v>', m.end())
                    if c > 0:
                        b = txt[m.end():c]
                        if b.isdigit():
                            nv = sst_map.get(int(b))
                            if nv is not None and nv != int(b):
                                edits.append((m.end(), c, str(nv)))
            if not edits:
                return txt
            edits.sort(key=lambda e: e[0], reverse=True)
            for a, b, nt in edits:
                txt = txt[:a] + nt + txt[b:]
            return txt

        # ---------------- styles.xml 并集 ----------------
        def _xf_merge_styles(datas, warns):
            texts = [d.decode('utf-8', 'replace') if d else '' for d in datas]
            ns, ignorable = {}, []
            for t in texts:
                if not t:
                    continue
                m = re.search(r'<styleSheet\b[^>]*?>', t)
                if not m:
                    continue
                for am in re.finditer(r'(?:^|\s)(xmlns(?::[\w.\-]+)?)\s*=\s*"([^"]*)"', m.group(0)):
                    ns.setdefault(am.group(1), am.group(2))
                ig = _xf_attr(m.group(0), 'mc:Ignorable')
                if ig:
                    for p in ig.split():
                        if p not in ignorable:
                            ignorable.append(p)
            ns.setdefault('xmlns', 'http://schemas.openxmlformats.org/spreadsheetml/2006/main')

            def fix_xf(raw, nf, fm, sx):
                for a, mp in (('numFmtId', nf), ('fontId', fm[0]), ('fillId', fm[1]), ('borderId', fm[2])):
                    v = _xf_attr(raw, a)
                    if v is not None and v.isdigit():
                        nv = mp.get(int(v))
                        if nv is not None and nv != int(v):
                            raw = _xf_setattr(raw, a, str(nv))
                if sx is not None:
                    v = _xf_attr(raw, 'xfId')
                    if v is not None and v.isdigit():
                        nv = sx.get(int(v))
                        raw = _xf_setattr(raw, 'xfId', str(nv) if nv is not None else None)
                return raw

            numfmts = {}
            union = {'fonts': [], 'fills': [], 'borders': [], 'cellStyleXfs': [], 'cellXfs': [], 'dxfs': []}
            seen = dict((k, {}) for k in union)
            cellstyles, tablestyles, ts_attrs = {}, {}, {}
            colors_blk = ext_blk = ''
            maps = []
            for t in texts:
                mp = {'xf': {}, 'dxf': {}, 'nf': {}}
                maps.append(mp)
                if not t:
                    continue
                for raw in _xf_coll(t, 'numFmts')[0]:
                    fid, code = _xf_attr(raw, 'numFmtId'), _xf_attr(raw, 'formatCode')
                    if fid is None or not fid.isdigit():
                        continue
                    fid = int(fid)
                    if fid not in numfmts:
                        numfmts[fid] = code
                        mp['nf'][fid] = fid
                    elif numfmts[fid] == code:
                        mp['nf'][fid] = fid
                    else:
                        nid = max(list(numfmts) + [163]) + 1
                        while nid in numfmts:
                            nid += 1
                        numfmts[nid] = code
                        mp['nf'][fid] = nid
                        warns.append('两个文件的自定义数字格式都占用 numFmtId=%d，后者已改用 %d' % (fid, nid))
                fmap = []
                for coll in ('fonts', 'fills', 'borders'):
                    d = {}
                    for i, raw in enumerate(_xf_coll(t, coll)[0]):
                        if raw not in seen[coll]:
                            seen[coll][raw] = len(union[coll])
                            union[coll].append(raw)
                        d[i] = seen[coll][raw]
                    fmap.append(d)
                sx = {}
                for i, raw in enumerate(_xf_coll(t, 'cellStyleXfs')[0]):
                    nr = fix_xf(raw, mp['nf'], fmap, None)
                    if nr not in seen['cellStyleXfs']:
                        seen['cellStyleXfs'][nr] = len(union['cellStyleXfs'])
                        union['cellStyleXfs'].append(nr)
                    sx[i] = seen['cellStyleXfs'][nr]
                for i, raw in enumerate(_xf_coll(t, 'cellXfs')[0]):
                    nr = fix_xf(raw, mp['nf'], fmap, sx)
                    if nr not in seen['cellXfs']:
                        seen['cellXfs'][nr] = len(union['cellXfs'])
                        union['cellXfs'].append(nr)
                    mp['xf'][i] = seen['cellXfs'][nr]
                for i, raw in enumerate(_xf_coll(t, 'dxfs')[0]):
                    if raw not in seen['dxfs']:
                        seen['dxfs'][raw] = len(union['dxfs'])
                        union['dxfs'].append(raw)
                    mp['dxf'][i] = seen['dxfs'][raw]
                for raw in _xf_coll(t, 'cellStyles')[0]:
                    nm = _xf_attr(raw, 'name')
                    if nm is None or nm in cellstyles:
                        continue
                    v = _xf_attr(raw, 'xfId')
                    if v is not None and v.isdigit():
                        nv = sx.get(int(v))
                        raw = _xf_setattr(raw, 'xfId', str(nv) if nv is not None else None)
                    cellstyles[nm] = raw
                kids, opentag = _xf_coll(t, 'tableStyles')
                if opentag:
                    for a in ('defaultTableStyle', 'defaultPivotStyle'):
                        v = _xf_attr(opentag, a)
                        if v and a not in ts_attrs:
                            ts_attrs[a] = v
                for raw in kids:
                    nm = _xf_attr(raw, 'name')
                    if nm and nm not in tablestyles:
                        tablestyles[nm] = raw
                if not colors_blk:
                    m = re.search(r'<colors\b[^>]*?>.*?</colors>', t, re.S)
                    if m:
                        colors_blk = m.group(0)
                if not ext_blk:
                    i1, i2 = t.rfind('<extLst>'), t.rfind('</extLst>')
                    if 0 <= i1 < i2 and not t[i2 + 9:].strip():
                        ext_blk = t[i1:i2 + 9]
            if not union['cellXfs']:
                union['fonts'] = [
                    '<font><sz val="11"/><color theme="1"/><name val="Calibri"/><family val="2"/><scheme val="minor"/></font>']
                union['fills'] = ['<fill><patternFill patternType="none"/></fill>',
                                  '<fill><patternFill patternType="gray125"/></fill>']
                union['borders'] = ['<border><left/><right/><top/><bottom/><diagonal/></border>']
                union['cellStyleXfs'] = ['<xf numFmtId="0" fontId="0" fillId="0" borderId="0"/>']
                union['cellXfs'] = ['<xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/>']
                for mp in maps:
                    mp['xf'] = {}
            head = '<styleSheet' + ''.join(' %s="%s"' % (k, v) for k, v in ns.items())
            if ignorable:
                head += ' mc:Ignorable="%s"' % ' '.join(ignorable)
            head += '>'
            body = []
            if numfmts:
                body.append('<numFmts count="%d">%s</numFmts>' % (
                    len(numfmts),
                    ''.join('<numFmt numFmtId="%d" formatCode="%s"/>' % (i, numfmts[i]) for i in sorted(numfmts))))
            for coll in ('fonts', 'fills', 'borders', 'cellStyleXfs', 'cellXfs', 'dxfs'):
                body.append('<%s count="%d">%s</%s>' % (coll, len(union[coll]), ''.join(union[coll]), coll))
            if cellstyles:
                body.append('<cellStyles count="%d">%s</cellStyles>' % (len(cellstyles), ''.join(cellstyles.values())))
            body.append('<tableStyles count="%d"%s>%s</tableStyles>' % (
                len(tablestyles),
                ''.join(
                    ' %s="%s"' % (a, ts_attrs[a]) for a in ('defaultTableStyle', 'defaultPivotStyle') if a in ts_attrs),
                ''.join(tablestyles.values())))
            if colors_blk:
                body.append(colors_blk)
            if ext_blk:
                body.append(ext_blk)
            return (head + ''.join(body) + '</styleSheet>').encode('utf-8'), maps

        # ---------------- 结构自检 ----------------
        def _xf_validate(parts):
            errs = []
            for nm in ('[Content_Types].xml', '_rels/.rels', 'xl/workbook.xml'):
                if nm not in parts:
                    errs.append('缺部件 %s' % nm)
            if errs:
                return errs
            for nm, data in parts.items():
                if nm.endswith('.xml') or nm.endswith('.rels'):
                    try:
                        _ET.fromstring(data)
                    except Exception as e:
                        snip = ''
                        pos = getattr(e, 'position', None)
                        if pos:
                            lines = data.decode('utf-8', 'replace').split('\n')
                            ln, col = pos[0], pos[1]
                            if 0 < ln <= len(lines):
                                s = lines[ln - 1]
                                snip = '\n      出错处附近：…%s…' % s[max(0, col - 90):col + 90]
                        errs.append('%s 不是合法 XML：%s%s' % (nm, e, snip))
            ct = parts['[Content_Types].xml'].decode('utf-8', 'replace')
            defs, ovs = set(), set()
            for m in re.finditer(r'<(Default|Override)\b[^>]*>', ct):
                if m.group(1) == 'Default':
                    e = _xf_attr(m.group(0), 'Extension')
                    if e:
                        defs.add(e.lower())
                else:
                    pn = _xf_attr(m.group(0), 'PartName')
                    if pn:
                        ovs.add(pn.lstrip('/'))
            for pn in ovs:
                if pn not in parts:
                    errs.append('内容类型 Override 指向不存在的部件 /%s' % pn)
            for nm in parts:
                if nm == '[Content_Types].xml':
                    continue
                ext = nm.rpartition('.')[2].lower()
                if nm not in ovs and ext not in defs:
                    errs.append('部件 %s 没有内容类型' % nm)
            for nm in list(parts):
                if not nm.endswith('.rels'):
                    continue
                owner = _xf_owner_of(nm)
                if owner and owner not in parts:
                    errs.append('%s 是孤儿关系文件' % nm)
                for rel in _xf_rels(parts, owner):
                    if rel['mode'] == 'External' or not rel['target']:
                        continue
                    t = _xf_resolve(owner, rel['target'])
                    if t not in parts:
                        errs.append('%s 的关系 %s 指向缺失部件 %s' % (nm, rel['id'], t))
            wb = parts['xl/workbook.xml'].decode('utf-8', 'replace')
            rid2rel = dict((r['id'], r) for r in _xf_rels(parts, 'xl/workbook.xml'))
            sm = re.search(r'<sheets>(.*?)</sheets>', wb, re.S)
            tags = re.findall(r'<sheet\b[^>]*?/>', sm.group(1)) if sm else []
            names = set()
            for tag in tags:
                rid = _xf_attr(tag, 'r:id')
                nm = _xf_unesc(_xf_attr(tag, 'name') or '')
                if rid not in rid2rel:
                    errs.append('工作表「%s」的 r:id=%s 没有对应关系' % (nm, rid))
                if nm.lower() in names:
                    errs.append('子表名重复：%s' % nm)
                names.add(nm.lower())
                if len(nm) > 31:
                    errs.append('子表名超过 31 字符：%s' % nm)
            used_rids = set(_xf_attr(t, 'r:id') for t in tags)
            for rel in rid2rel.values():
                if rel['type'] in (T_NS + 'worksheet', T_NS + 'chartsheet', T_NS + 'dialogsheet'):
                    if rel['id'] not in used_rids:
                        errs.append('关系 %s(%s) 没被任何 <sheet> 引用' % (rel['id'], rel['target']))
            ids = [int(_xf_attr(t, 'sheetId')) for t in tags if (_xf_attr(t, 'sheetId') or '').isdigit()]
            if len(set(ids)) != len(ids):
                errs.append('sheetId 有重复')
            for dnm in re.finditer(r'<definedName\b[^>]*?localSheetId="(\d+)"', wb):
                if int(dnm.group(1)) >= len(tags):
                    errs.append('definedName 的 localSheetId=%s 超出子表数 %d' % (dnm.group(1), len(tags)))
            # 样式/共享字符串下标不能越界
            st = parts.get('xl/styles.xml', b'').decode('utf-8', 'replace')
            nxf = len(_xf_coll(st, 'cellXfs')[0])
            ndxf = len(_xf_coll(st, 'dxfs')[0])
            sst = parts.get('xl/sharedStrings.xml', b'').decode('utf-8', 'replace')
            nsi = len(_xf_children(sst)) if sst else 0
            for nm, data in parts.items():
                if not nm.startswith('xl/worksheets/') or not nm.endswith('.xml'):
                    continue
                t = data.decode('utf-8', 'replace')
                for m in re.finditer(r'<(?:c|row)\b[^>]*?\ss="(\d+)"', t):
                    if int(m.group(1)) >= nxf:
                        errs.append('%s 的 s=%s 越界（cellXfs 只有 %d 项）' % (nm, m.group(1), nxf))
                        break
                for m in re.finditer(r'<cfRule\b[^>]*?dxfId="(\d+)"', t):
                    if int(m.group(1)) >= ndxf:
                        errs.append('%s 的 dxfId=%s 越界（dxfs 只有 %d 项）' % (nm, m.group(1), ndxf))
                        break
                cur = False
                for m in _XF_TAG_RE.finditer(t):
                    if m.group(1):
                        continue
                    if m.group(2) == 'c':
                        cur = (_xf_attr(m.group(0), 't') == 's')
                    elif m.group(2) == 'v' and cur and not m.group(0).endswith('/>'):
                        c = t.find('</v>', m.end())
                        b = t[m.end():c] if c > 0 else ''
                        if b.isdigit() and int(b) >= nsi:
                            errs.append('%s 的共享字符串下标 %s 越界（只有 %d 条）' % (nm, b, nsi))
                            break
            return errs

        def _xf_write_pkg(out_path, parts, order, compress):
            tmp = out_path + '.tmp~'
            zf = zipfile.ZipFile(tmp, 'w', zipfile.ZIP_DEFLATED)
            try:
                wrote = set()
                for nm in list(order) + [x for x in sorted(parts) if x not in order]:
                    if nm not in parts or nm in wrote:
                        continue
                    zi = zipfile.ZipInfo(nm, date_time=(1980, 1, 1, 0, 0, 0))
                    zi.compress_type = compress.get(nm, zipfile.ZIP_DEFLATED)
                    zf.writestr(zi, parts[nm])
                    wrote.add(nm)
            finally:
                zf.close()
            os.replace(tmp, out_path)

        def _xf_fix_app(txt, names):
            label = 'Worksheets'
            m = re.search(r'<vt:lpstr>([^<]*)</vt:lpstr>\s*</vt:variant>\s*<vt:variant>\s*<vt:i4>\d+</vt:i4>', txt)
            if m and m.group(1) in ('工作表', 'Worksheets', 'Sheets'):
                label = m.group(1)
            hm = re.search(r'<HeadingPairs>.*?</HeadingPairs>', txt, re.S)
            if hm:
                new = ('<HeadingPairs><vt:vector size="2" baseType="variant"><vt:variant><vt:lpstr>%s</vt:lpstr>'
                       '</vt:variant><vt:variant><vt:i4>%d</vt:i4></vt:variant></vt:vector></HeadingPairs>'
                       % (label, len(names)))
                txt = txt[:hm.start()] + new + txt[hm.end():]
            tm = re.search(r'<TitlesOfParts>.*?</TitlesOfParts>', txt, re.S)
            if tm:
                vec = ('<vt:vector size="%d" baseType="lpstr">' % len(names)
                       + ''.join('<vt:lpstr>%s</vt:lpstr>' % _xf_esc_text(n) for n in names)
                       + '</vt:vector>')
                txt = txt[:tm.start()] + '<TitlesOfParts>' + vec + '</TitlesOfParts>' + txt[tm.end():]
            return txt

        # ---------------- 合并主流程 ----------------
        def _xf_merge(paths, out_path, _log):
            rep = {'ok': False, 'errors': [], 'warns': [], 'files': list(paths), 'out': out_path,
                   'sheets': [], 'stats': {}}
            out_parts, out_ct, out_compress = {}, {}, {}
            hash2name, counters = {}, {}

            def _alloc(src_name, data, ctype, compress=None, dedup=None):
                """分配一个不冲突的部件名。
                只有图片、主题这类“只读大资源”才按内容指纹共用一份（省得同一个 logo 复制几十遍）；
                批注 VML、drawing、chart、表格这些跟子表一对一的部件各留一份，
                免得两个子表挂到同一个部件上被 Excel 当成损坏。"""
                if dedup is None:
                    dedup = src_name.startswith('xl/media/') or '/theme/' in src_name
                h = hashlib.sha1(data).hexdigest()
                if dedup and h in hash2name:
                    return hash2name[h]
                d, _, b = src_name.rpartition('/')
                ext = b.rpartition('.')[2].lower() if '.' in b else ''
                stem = b[:len(b) - len(ext) - 1] if ext else b
                stem = re.sub(r'\d+$', '', stem) or 'part'
                key, n = (d, stem, ext), counters.get((d, stem, ext), 0)
                while True:
                    n += 1
                    nm = '%s/%s%d.%s' % (d, stem, n, ext) if ext else '%s/%s%d' % (d, stem, n)
                    if nm not in out_parts:
                        break
                counters[key] = n
                out_parts[nm] = data
                if ctype:
                    out_ct[nm] = ctype
                if compress is not None:
                    out_compress[nm] = compress
                hash2name[h] = nm
                return nm

            def _alloc_keep(src_name, data, ctype, compress=None):
                """优先沿用原部件名（docProps/theme 这种），被占用才另起。"""
                h = hashlib.sha1(data).hexdigest()
                if h in hash2name:
                    return hash2name[h]
                nm, n = src_name, 0
                while nm in out_parts:
                    n += 1
                    d, _, b = src_name.rpartition('/')
                    stem, dot, ext = b.rpartition('.')
                    nm = '%s/%s_%d.%s' % (d, stem, n, ext) if dot else '%s/%s_%d' % (d, b, n)
                out_parts[nm] = data
                if ctype:
                    out_ct[nm] = ctype
                if compress is not None:
                    out_compress[nm] = compress
                hash2name[h] = nm
                return nm

            def _emit_rels(keep, amap, s, rep):
                """按新部件名重建每个部件的 .rels：Id 与 Type 原样，只把 Target 换成新路径。"""
                for q in keep:
                    rn = _xf_rels_name(q)
                    if rn not in s['parts'] or q not in amap:
                        continue
                    body = []
                    for rel in _xf_rels(s['parts'], q):
                        if rel['mode'] == 'External' or not rel['target']:
                            body.append(rel['raw'])
                            continue
                        tp = _xf_resolve(q, rel['target'])
                        if tp not in amap:
                            rep['warns'].append('%s 的关系 %s 指向未搬运的部件 %s' % (q, rel['id'], tp))
                            continue
                        body.append('<Relationship Id="%s" Type="%s" Target="%s"/>'
                                    % (rel['id'], rel['type'],
                                       _xf_esc_attr(posixpath.relpath(amap[tp],
                                                                      posixpath.dirname(amap[q]) or '.'))))
                    out_parts[_xf_rels_name(amap[q])] = (REL_DECL + REL_ROOT + ''.join(body)
                                                         + '</Relationships>').encode('utf-8')

            def _copy_tree(s, root, rep, keepname=False):
                """把某个部件连同它引用到的所有部件搬进输出，返回 {源名: 新名}。"""
                keep = _xf_closure(s['parts'], [root])
                amap = {}
                for q in sorted(keep):
                    if q.endswith('.rels'):
                        continue
                    fn = _alloc_keep if keepname else _alloc
                    amap[q] = fn(q, s['parts'][q], s['ct_ov'].get(q), s['infos'][q].compress_type)
                _emit_rels(keep, amap, s, rep)
                return amap

            # ---------- 读入所有源 ----------
            S = []
            for path in paths:
                try:
                    parts, infos, order = _xf_read_pkg(path)
                except Exception as e:
                    rep['errors'].append('打不开，已跳过：%s（%s）' % (os.path.basename(path), e))
                    continue
                if 'xl/workbook.xml' not in parts or 'xl/_rels/workbook.xml.rels' not in parts:
                    rep['errors'].append('不是有效的 xlsx，已跳过：%s' % os.path.basename(path))
                    continue
                wb_txt = parts['xl/workbook.xml'].decode('utf-8', 'replace')
                rels = _xf_rels(parts, 'xl/workbook.xml')
                rid2rel = dict((r['id'], r) for r in rels)
                sm = re.search(r'<sheets>(.*?)</sheets>', wb_txt, re.S)
                sheets = []
                for tag in (re.findall(r'<sheet\b[^>]*?/>', sm.group(1)) if sm else []):
                    rel = rid2rel.get(_xf_attr(tag, 'r:id'))
                    if not rel:
                        continue
                    p = _xf_resolve('xl/workbook.xml', rel['target'])
                    if p not in parts:
                        rep['warns'].append(
                            '%s 的子表「%s」部件缺失，已跳过' % (os.path.basename(path), _xf_attr(tag, 'name')))
                        continue
                    sheets.append({'tag': tag, 'name': _xf_unesc(_xf_attr(tag, 'name') or ''),
                                   'part': p, 'type': rel['type'],
                                   'state': _xf_attr(tag, 'state'), 'final': None})
                if not sheets:
                    rep['errors'].append('没有子表，已跳过：%s' % os.path.basename(path))
                    continue
                ct = parts.get('[Content_Types].xml', b'').decode('utf-8', 'replace')
                ct_ov, ct_def = {}, {}
                for m in re.finditer(r'<(Default|Override)\b[^>]*>', ct):
                    ty = _xf_attr(m.group(0), 'ContentType')
                    if m.group(1) == 'Default':
                        e = _xf_attr(m.group(0), 'Extension')
                        if e and ty:
                            ct_def.setdefault(e.lower(), ty)
                    else:
                        pn = _xf_attr(m.group(0), 'PartName')
                        if pn and ty:
                            ct_ov[pn.lstrip('/')] = ty
                si, sst_root = [], None
                if 'xl/sharedStrings.xml' in parts:
                    t = parts['xl/sharedStrings.xml'].decode('utf-8', 'replace')
                    si, sst_root = _xf_children(t), _xf_root(t)[1]
                ext = []
                em = re.search(r'<externalReferences>(.*?)</externalReferences>', wb_txt, re.S)
                if em:
                    for rid in re.findall(r'<externalReference\b[^>]*?r:id="([^"]+)"', em.group(1)):
                        rel = rid2rel.get(rid)
                        if rel:
                            p = _xf_resolve('xl/workbook.xml', rel['target'])
                            if p in parts:
                                ext.append(p)
                pcs = []
                pm = re.search(r'<pivotCaches>(.*?)</pivotCaches>', wb_txt, re.S)
                if pm:
                    for tag in re.findall(r'<pivotCache\b[^>]*?/>', pm.group(1)):
                        cid, rel = _xf_attr(tag, 'cacheId'), rid2rel.get(_xf_attr(tag, 'r:id'))
                        if cid is not None and rel:
                            p = _xf_resolve('xl/workbook.xml', rel['target'])
                            if p in parts:
                                pcs.append((cid, p))
                dns = []
                dm = re.search(r'<definedNames>(.*?)</definedNames>', wb_txt, re.S)
                if dm:
                    dns = [one.group(0) for one in
                           re.finditer(r'<definedName\b[^>]*?(?:/>|>.*?</definedName>)', dm.group(1), re.S)]
                conns = []
                if 'xl/connections.xml' in parts:
                    t = parts['xl/connections.xml'].decode('utf-8', 'replace')
                    _, _, _, a, b = _xf_root(t)
                    for raw in _xf_children_in(t, a, b):
                        m2 = re.match(r'<[A-Za-z_][\w.:-]*\b[^>]*?>', raw)
                        cid = _xf_attr(m2.group(0), 'id') if m2 else None
                        if cid is not None:
                            conns.append((cid, raw))
                S.append({'path': path, 'base': os.path.splitext(os.path.basename(path))[0],
                          'parts': parts, 'infos': infos, 'order': order, 'wb_txt': wb_txt,
                          'rels': rels, 'sheets': sheets, 'ct_ov': ct_ov, 'ct_def': ct_def,
                          'si': si, 'sst_root': sst_root, 'ext': ext, 'ext_map': {}, 'pcs': pcs,
                          'pc_map': {}, 'dns': dns, 'name_map': {}, 'sst_map': {}, 'conn_map': {},
                          'conns': conns})
            if not S:
                rep['errors'].append('所选文件夹里没有可用的 xlsx')
                return rep
            base = S[0]

            # ---------- 样式并集 ----------
            styles_xml, style_maps = _xf_merge_styles([s['parts'].get('xl/styles.xml') for s in S], rep['warns'])

            # ---------- 共享字符串并集（按原文去重；富文本 <r>、拼音 <rPh> 原样保留）----------
            all_si, si_seen = [], {}
            for s in S:
                m = {}
                for i, raw in enumerate(s['si']):
                    if raw not in si_seen:
                        si_seen[raw] = len(all_si)
                        all_si.append(raw)
                    m[i] = si_seen[raw]
                s['sst_map'] = m
            themes = set()
            for s in S:
                if 'xl/theme/theme1.xml' in s['parts']:
                    themes.add(hashlib.sha1(s['parts']['xl/theme/theme1.xml']).hexdigest())
            if len(themes) > 1:
                rep['warns'].append('%d 个文件的主题(theme)不一致，统一采用第一个文件 %s 的主题'
                                    % (len(themes), base['base']))

            # ---------- 外部链接并集（顺序即公式里 [n] 的下标，缓存原样带走）----------
            ext_out = []  # (新部件名, 新下标, 源序号)
            for k, s in enumerate(S):
                for i, p in enumerate(s['ext'], start=1):
                    newi = len(ext_out) + 1
                    s['ext_map'][i] = newi
                    nm = _copy_tree(s, p, rep)[p]
                    ext_out.append((nm, newi, k))
                if s['ext_map'] and any(a != b for a, b in s['ext_map'].items()):
                    _log('  %s：外链下标 %s' % (s['base'], s['ext_map']))

            # ---------- 透视缓存并集 ----------
            pc_out = []
            for k, s in enumerate(S):
                for cid, p in s['pcs']:
                    newcid = str(len(pc_out) + 1)
                    s['pc_map'][cid] = newcid
                    pc_out.append((newcid, _copy_tree(s, p, rep)[p]))

            # ---------- 数据连接 / Power Pivot 数据模型：整套只跟一个文件走 ----------
            # 数据模型(xl/model/item.data)是一个二进制整体，两个模型没法并成一个；
            # 连接里的 ThisWorkbookDataModel / WorksheetConnection_* 都是围着模型转的，
            # 所以整套（模型 + 连接 + _xlcn.* 定义名）只跟一个文件走，其余文件的丢掉并写日志
            # （它们的表格、数据、边框、公式都照常保留，只是不能再喂给数据模型）。
            # 跟谁走：第一个真带模型的文件——第一个文件不一定带模型（先合并的可能正是几个简单表），
            # 没有模型就退到第一个带连接的文件。
            def _has_model(s):
                return any(r['type'].endswith('/powerPivotData') or '/model/' in (r['target'] or '')
                           for r in s['rels'])

            model_owner = conn_owner = None
            for k, s in enumerate(S):
                if model_owner is None and _has_model(s):
                    model_owner = k
                if conn_owner is None and (s['conns'] or any(r['type'] == T_NS + 'connections'
                                                             for r in s['rels'])):
                    conn_owner = k
            if model_owner is not None:
                conn_owner = model_owner  # 模型和它的连接必须同源，不然指错表
            keep_owner = conn_owner if conn_owner is not None else 0
            conn_kept = False
            model_rel = None
            for rel in S[keep_owner]['rels']:
                p = _xf_resolve('xl/workbook.xml', rel['target'])
                if p not in S[keep_owner]['parts']:
                    continue
                if rel['type'] == T_NS + 'connections':
                    _copy_tree(S[keep_owner], p, rep, keepname=True)
                    conn_kept = True
                elif rel['type'].endswith('/powerPivotData') or '/model/' in (rel['target'] or ''):
                    model_rel = (rel['type'], _copy_tree(S[keep_owner], p, rep, keepname=True)[p])
            if model_owner is not None:
                _log('  数据模型只保留 %s 的（模型是一个二进制整体，多个模型没法并成一个）'
                     % S[model_owner]['base'])
            for k, s in enumerate(S):
                if k == keep_owner:
                    continue
                if s['conns']:
                    rep['warns'].append('%s 的数据连接没法和 %s 的并在一起，已丢弃'
                                        '（该文件的表格数据、公式、边框照常保留）'
                                        % (s['base'], S[keep_owner]['base']))
                if k != model_owner and _has_model(s):
                    rep['warns'].append('%s 带 Power Pivot 数据模型，只保留 %s 的模型'
                                        % (s['base'], S[model_owner]['base'] if model_owner is not None
                    else S[keep_owner]['base']))

            # ---------- WPS 嵌入式单元格图片并集 ----------
            ci_head = ci_tail = None
            ci_roots = []
            ci_blocks, ci_need, img_id_map = [], [], [{} for _ in S]
            used_ids = {}
            for k, s in enumerate(S):
                p = None
                for rel in s['rels']:
                    if rel['type'] == WPS_CELLIMAGE:
                        p = _xf_resolve('xl/workbook.xml', rel['target'])
                        break
                if not p or p not in s['parts']:
                    continue
                t = s['parts'][p].decode('utf-8', 'replace')
                decl, root, close, a, b = _xf_root(t)
                ci_roots.append(root)
                if ci_head is None:
                    ci_head, ci_tail, ci_ct = decl, close, s['ct_ov'].get(p)
                rmap = dict((r['id'], r) for r in _xf_rels(s['parts'], p))
                for raw in _xf_children_in(t, a, b):
                    nm = re.search(r'\bname="([^"]+)"', raw)
                    iid = _xf_unesc(nm.group(1)) if nm else None
                    embeds = re.findall(r'r:(?:embed|id|link)="([^"]+)"', raw)
                    h = ''
                    for rid in embeds:
                        rel = rmap.get(rid)
                        if rel and rel['mode'] != 'External':
                            tp = _xf_resolve(p, rel['target'])
                            if tp in s['parts']:
                                h = hashlib.sha1(s['parts'][tp]).hexdigest()
                                break
                    if iid and iid in used_ids and used_ids[iid] != h:
                        new = 'ID_' + hashlib.sha1((iid + h + s['base']).encode('utf-8')).hexdigest()[:32].upper()
                        img_id_map[k][iid] = new
                        raw = raw.replace(nm.group(0), 'name="%s"' % _xf_esc_attr(new))
                        rep['warns'].append('嵌入图片 ID %s 在 %s 里指向另一张图，已改名为 %s' % (iid, s['base'], new))
                        iid = new
                    if iid:
                        used_ids.setdefault(iid, h)
                    for rid in embeds:
                        nrid = 'rId%d' % (len(ci_need) + 1)
                        ci_need.append((nrid, rid, p, k))
                        raw = re.sub(r'(r:(?:embed|id|link)=")' + re.escape(rid) + '(")',
                                     lambda m, r=nrid: m.group(1) + r + m.group(2), raw, count=1)
                    ci_blocks.append(raw)
            ci_rel_lines = []
            for nrid, oldrid, owner, k in ci_need:
                s = S[k]
                rel = [r for r in _xf_rels(s['parts'], owner) if r['id'] == oldrid]
                if not rel or rel[0]['mode'] == 'External' or not rel[0]['target']:
                    continue
                tp = _xf_resolve(owner, rel[0]['target'])
                if tp not in s['parts']:
                    continue
                nm = _alloc(tp, s['parts'][tp], s['ct_ov'].get(tp), s['infos'][tp].compress_type)
                ci_rel_lines.append('<Relationship Id="%s" Type="%s" Target="%s"/>'
                                    % (nrid, rel[0]['type'], _xf_esc_attr(posixpath.relpath(nm, 'xl'))))
            if ci_blocks:
                ci_head = ci_head + _xf_union_ns(ci_roots[0], ci_roots[1:])
                out_parts['xl/cellimages.xml'] = (ci_head + ''.join(ci_blocks) + ci_tail).encode('utf-8')
                if ci_ct:
                    out_ct['xl/cellimages.xml'] = ci_ct
                out_parts['xl/_rels/cellimages.xml.rels'] = (REL_DECL + REL_ROOT + ''.join(ci_rel_lines)
                                                             + '</Relationships>').encode('utf-8')

            # ---------- 同名同内容的子表只留一份；确实不同的重名子表按「文件名_表名」分开 ----------
            # 先把每个子表换算到“合并后的统一下标”（样式 s=、共享字符串、外链 [n]、嵌入图片 ID），
            # 再连同它挂着的图片/表格/批注/打印设置等部件一起算指纹；指纹一样就是内容一模一样。
            # 指纹里去掉 xr:uid 这类版本跟踪 GUID，否则同一张表在两个文件里也认不出来。
            def _norm_uid(t):
                return re.sub(r'\s[\w.:-]*uid="\{[0-9A-Fa-f\-]+\}"', '', t)

            for k, s in enumerate(S):
                mp = style_maps[k] if k < len(style_maps) else {'xf': {}, 'dxf': {}}
                ext_map = s['ext_map'] if any(a != b for a, b in s['ext_map'].items()) else None
                for j, sh in enumerate(s['sheets']):
                    keep = _xf_closure(s['parts'], [sh['part']])
                    txt = _xf_rewrite_sheet(s['parts'][sh['part']].decode('utf-8', 'replace'),
                                            {'xf': mp.get('xf'), 'dxf': mp.get('dxf'),
                                             'sst': s['sst_map'], 'ext': ext_map,
                                             'img': img_id_map[k] or None, 'tab': True})
                    sat = []
                    for q in sorted(keep):
                        if q == sh['part'] or q.endswith('.rels'):
                            continue
                        raw = s['parts'][q]
                        if q.endswith('.xml'):
                            raw = _norm_uid(raw.decode('utf-8', 'replace')).encode('utf-8')
                        sat.append(hashlib.sha1(raw).hexdigest())
                    sh['digest'] = hashlib.sha1((_norm_uid(txt) + '\x00' + '\x00'.join(sat))
                                                .encode('utf-8')).hexdigest()
                    sh['drop'] = False
                    sh['final'] = sh['name'] or ('Sheet%d' % (j + 1))
            by_name = {}
            for k, s in enumerate(S):
                for j, sh in enumerate(s['sheets']):
                    by_name.setdefault(sh['name'] or ('Sheet%d' % (j + 1)), []).append((k, j))
            for nm, lst in by_name.items():
                if len(lst) < 2:
                    continue
                seen = {}
                for k, j in lst:
                    sh = S[k]['sheets'][j]
                    if sh['digest'] in seen:
                        sh['drop'] = True
                        ok, oj = seen[sh['digest']]
                        rep['warns'].append('%s 的子表「%s」与 %s 里的完全相同，只保留一份'
                                            % (S[k]['base'], nm, S[ok]['base']))
                        _log('  去重 %-24s 子表「%s」= %s 里那份，不再重复' % (S[k]['base'], nm, S[ok]['base']))
                    else:
                        seen[sh['digest']] = (k, j)
            taken, groups = set(), []
            for nm, lst in by_name.items():
                alive = [(k, j) for k, j in lst if not S[k]['sheets'][j]['drop']]
                if not alive:
                    continue
                if len(alive) == 1:
                    taken.add(nm.lower())
                else:
                    groups.append((nm, alive))
            for nm, alive in groups:
                for k, j in alive:
                    sh = S[k]['sheets'][j]
                    stem = re.sub(r'[\\/*?\[\]:]', '', '%s_%s' % (S[k]['base'], nm))[:31] or ('Sheet%d' % (j + 1))
                    cand, n = stem, 1
                    while cand.lower() in taken:
                        suf = '_%d' % n
                        cand = stem[:31 - len(suf)] + suf
                        n += 1
                    taken.add(cand.lower())
                    sh['final'] = cand
                    S[k]['name_map'][nm] = cand
                    rep['warns'].append('子表「%s」在多个文件里内容不同，%s 的这份改名「%s」'
                                        '（该文件公式里对它的引用一并改掉）' % (nm, S[k]['base'], cand))

            # ---------- 逐个子表搬运 ----------
            def _remap_dxfids(txt, dxf_map):
                """把部件里所有 *DxfId="n" 换成新下标：表格的表头/表体/局部边框就挂在这上面。"""
                if not dxf_map:
                    return txt

                def _tag(m):
                    def _at(m2):
                        nv = dxf_map.get(int(m2.group(2)))
                        return m2.group(0) if nv is None else '%s="%d"' % (m2.group(1), nv)

                    return re.sub(r'(\w*[Dd]xfId)="(\d+)"', _at, m.group(0))

                return re.sub(r'<[^>]+>', _tag, txt)

            def _xf_fix_part_refs(q, t):
                """子表改名之后，图表、透视缓存、表格里对旧表名的引用也得跟着改，
                不然图表会变 #REF、透视表刷新时找不到源数据。
                只在这份文件确实改了名（name_map 非空）时才动手，其余情况一个字节不碰。"""
                if not (name_map or ext_map) or not q.endswith('.xml'):
                    return t
                if '/charts/' in q:
                    t = re.sub(r'(<(?:\w+:)?f>)(.*?)(</(?:\w+:)?f>)',
                               lambda m: m.group(1)
                                         + _xf_fix_formula(m.group(2), ext_map, name_map, None) + m.group(3),
                               t, flags=re.S)
                elif 'pivotCache' in q or 'pivotTable' in q:
                    t = re.sub(r'\bsheet="([^"]*)"',
                               lambda m: 'sheet="%s"' % _xf_esc_attr(
                                   name_map.get(_xf_unesc(m.group(1)), _xf_unesc(m.group(1)))), t)
                elif '/tables/' in q:
                    t = re.sub(r'(<calculatedColumnFormula[^>]*>)(.*?)(</calculatedColumnFormula>)',
                               lambda m: m.group(1)
                                         + _xf_fix_formula(m.group(2), ext_map, name_map, None) + m.group(3),
                               t, flags=re.S)
                return t

            sheet_tags, sheet_rels, gid, gidx = [], [], 0, {}
            used_tables, used_pivots = set(), set()
            tbl_id = [0]
            if model_owner is not None:
                # 模型所属文件的表格名/透视表名先占住：数据模型里的 WorksheetConnection_ 是按名字找表的，
                # 名字一旦被后来同名的表格挤得改了，模型刷新就找不到源表了。
                for q, data in S[model_owner]['parts'].items():
                    if not q.endswith('.xml'):
                        continue
                    t = data.decode('utf-8', 'replace')
                    if '/tables/' in q:
                        m = re.search(r'<table\b[^>]*?>', t)
                        v = m and (_xf_attr(m.group(0), 'displayName') or _xf_attr(m.group(0), 'name'))
                    elif 'pivotTable' in q:
                        m = re.search(r'<pivotTableDefinition\b[^>]*?>', t)
                        v = m and _xf_attr(m.group(0), 'name')
                    else:
                        v = None
                    if v:
                        (used_tables if '/tables/' in q else used_pivots).add(v)
            for k, s in enumerate(S):
                mp = style_maps[k] if k < len(style_maps) else {'xf': {}, 'dxf': {}}
                ext_map = s['ext_map'] if any(a != b for a, b in s['ext_map'].items()) else None
                name_map = s['name_map'] or None
                id_map = img_id_map[k] or None
                has_meta = 'xl/metadata.xml' in s['parts']
                for j, sh in enumerate(s['sheets']):
                    if sh.get('drop'):
                        continue
                    gidx[(k, j)] = gid
                    gid += 1
                    keep = _xf_closure(s['parts'], [sh['part']])
                    amap = {}
                    for q in sorted(keep):
                        if q.endswith('.rels'):
                            continue
                        data = s['parts'][q]
                        ctype = s['ct_ov'].get(q)
                        comp = s['infos'][q].compress_type
                        if q == sh['part']:
                            txt = data.decode('utf-8', 'replace')
                            txt = _xf_rewrite_sheet(txt, {'xf': mp.get('xf'), 'dxf': mp.get('dxf'),
                                                          'sst': s['sst_map'], 'ext': ext_map,
                                                          'name': name_map, 'img': id_map,
                                                          'tab': gid > 1, 'vm': has_meta and k > 0})
                            amap[q] = _alloc(q, txt.encode('utf-8'), ctype, comp, dedup=False)
                        elif 'pivotTable' in q and s['pc_map']:
                            t = data.decode('utf-8', 'replace')
                            m = re.search(r'<pivotTableDefinition\b[^>]*?>', t)
                            if m:
                                tag = m.group(0)
                                nt = tag
                                cid = _xf_attr(tag, 'cacheId')
                                if cid in s['pc_map']:
                                    nt = _xf_setattr(nt, 'cacheId', s['pc_map'][cid])
                                pnm = _xf_attr(nt, 'name')
                                if pnm and pnm in used_pivots and k != model_owner:
                                    n2, c2 = pnm, 1
                                    while n2 in used_pivots:
                                        c2 += 1
                                        n2 = '%s_%d' % (pnm, c2)
                                    nt = _xf_setattr(nt, 'name', _xf_esc_attr(n2))
                                    rep['warns'].append('透视表名 %s 重复，已改为 %s' % (pnm, n2))
                                if pnm:
                                    used_pivots.add(_xf_attr(nt, 'name'))
                                t = t.replace(tag, nt, 1)
                            t = _xf_fix_part_refs(q, t)
                            amap[q] = _alloc(q, t.encode('utf-8'), ctype, comp)
                        elif '/tables/' in q:
                            t = _remap_dxfids(data.decode('utf-8', 'replace'), mp.get('dxf'))
                            m = re.search(r'<table\b[^>]*?>', t)
                            if m:
                                tag = m.group(0)
                                tbl_id[0] += 1
                                nt = _xf_setattr(tag, 'id', str(tbl_id[0]))
                                dn = _xf_attr(nt, 'displayName') or _xf_attr(nt, 'name')
                                if dn:
                                    if k == model_owner:
                                        n2 = dn  # 数据模型按名字找这张表，不许改
                                    else:
                                        n2, c2 = dn, 1
                                        while n2 in used_tables:
                                            c2 += 1
                                            n2 = '%s_%d' % (dn, c2)
                                        if n2 != dn:
                                            rep['warns'].append('表格名 %s 重复，已改为 %s' % (dn, n2))
                                    nt = _xf_setattr(nt, 'displayName', _xf_esc_attr(n2))
                                    if _xf_attr(nt, 'name'):
                                        nt = _xf_setattr(nt, 'name', _xf_esc_attr(n2))
                                    used_tables.add(n2)
                                t = t.replace(tag, nt, 1)
                            t = _xf_fix_part_refs(q, t)
                            amap[q] = _alloc(q, t.encode('utf-8'), ctype, comp)
                        else:
                            if (name_map or ext_map) and q.endswith('.xml'):
                                data = _xf_fix_part_refs(q, data.decode('utf-8', 'replace')).encode('utf-8')
                            amap[q] = _alloc(q, data, ctype, comp)
                    _emit_rels(keep, amap, s, rep)
                    rid = 'rId%d' % gid
                    # 沿用源文件的 <sheet> 原标签，只改 name/sheetId/r:id：
                    # 有的写法（openpyxl）把 xmlns:r 声明就挂在这个标签上，重建标签会把它弄丢
                    tag = _xf_setattr(sh['tag'], 'name', _xf_esc_attr(sh['final']))
                    tag = _xf_setattr(tag, 'sheetId', str(gid))
                    tag = _xf_setattr(tag, 'r:id', rid)
                    tag = re.sub(r'\s[\w.:-]*uid="\{[0-9A-Fa-f\-]+\}"', '', tag)  # 版本跟踪 GUID 不带过来
                    sheet_tags.append(tag)
                    sheet_rels.append((rid, posixpath.relpath(amap[sh['part']], 'xl'),
                                       sh['type'] or (T_NS + 'worksheet')))
                    rep['sheets'].append((s['base'], sh['name'], sh['final'], amap[sh['part']]))
                    _log('  合并 %-24s 子表「%s」→「%s」 部件%d个' % (s['base'], sh['name'], sh['final'], len(amap)))

            # ---------- 定义名 ----------
            # localSheetId 是“第几个子表”，合并后下标全变了，必须按 gidx 换算；
            # 指向被去重丢掉的子表的定义名一并丢弃；_xlcn.* 是数据连接的内部名，只跟保留连接的那个文件走。
            merged_dns, used_g = [], set()
            for k, s in enumerate(S):
                ext_map = s['ext_map'] if any(a != b for a, b in s['ext_map'].items()) else None
                for blk in s['dns']:
                    opentag = re.match(r'<definedName\b[^>]*?>', blk).group(0)
                    rest = blk[len(opentag):]
                    dnm = _xf_unesc(_xf_attr(opentag, 'name') or '')
                    if k != keep_owner and dnm.startswith('_xlcn.'):
                        continue  # _xlcn.* 是数据连接的内部名，只跟保留连接的那个文件走
                    lsi = _xf_attr(opentag, 'localSheetId')
                    if lsi is not None and lsi.isdigit():
                        key = (k, int(lsi))
                        if key not in gidx:
                            continue
                        opentag = _xf_setattr(opentag, 'localSheetId', str(gidx[key]))
                    else:
                        if dnm and not dnm.startswith('_xlnm.') and dnm.lower() in used_g:
                            new = ('%s_%s' % (dnm, s['base']))[:255]
                            opentag = _xf_setattr(opentag, 'name', _xf_esc_attr(new))
                            rep['warns'].append('定义名「%s」重复，来自 %s 的已改为「%s」（引用它的公式需手动核对）'
                                                % (dnm, s['base'], new))
                            dnm = new
                        if dnm:
                            used_g.add(dnm.lower())
                    if rest.endswith('</definedName>'):
                        body = rest[:-len('</definedName>')]
                        rest = _xf_fix_formula(body, ext_map, s['name_map'] or None,
                                               img_id_map[k] or None) + '</definedName>'
                    merged_dns.append(opentag + rest)

            # ---------- 主题、共享字符串、样式 ----------
            if 'xl/theme/theme1.xml' in base['parts']:
                _alloc_keep('xl/theme/theme1.xml', base['parts']['xl/theme/theme1.xml'],
                            base['ct_ov'].get('xl/theme/theme1.xml'),
                            base['infos']['xl/theme/theme1.xml'].compress_type)
            out_parts['xl/styles.xml'] = styles_xml
            out_ct['xl/styles.xml'] = base['ct_ov'].get('xl/styles.xml') or \
                                      'application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml'
            sst_roots = [s['sst_root'] for s in S if s['sst_root']]
            sst_root = _xf_union_ns(sst_roots[0] if sst_roots else '', sst_roots[1:])
            if all_si:
                if not sst_root:
                    sst_root = '<sst xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">'
                r0 = re.sub(r'\s(?:count|uniqueCount)="\d+"', '', sst_root).rstrip()
                add = ' count="%d" uniqueCount="%d"' % (len(all_si), len(all_si))
                sst_root = (r0[:-1].rstrip() + add + '/>') if r0.endswith('/>') else (r0[:-1].rstrip() + add + '>')
                out_parts['xl/sharedStrings.xml'] = (REL_DECL + sst_root + ''.join(all_si) + '</sst>').encode('utf-8')
                out_ct['xl/sharedStrings.xml'] = base['ct_ov'].get('xl/sharedStrings.xml') or \
                                                 'application/vnd.openxmlformats-officedocument.spreadsheetml.sharedStrings+xml'
            if 'xl/metadata.xml' in base['parts']:
                _alloc_keep('xl/metadata.xml', base['parts']['xl/metadata.xml'],
                            base['ct_ov'].get('xl/metadata.xml'))
            for s in S[1:]:
                if 'xl/metadata.xml' in s['parts']:
                    rep['warns'].append('%s 里有 metadata.xml（富值/地理等数据类型），合并后只保留第一个文件的，'
                                        '该文件单元格上的 vm 标记已去掉' % s['base'])
                for rel in s['rels']:
                    if rel['type'].endswith('/vbaProject'):
                        rep['warns'].append('%s 带宏(vbaProject)，输出是 .xlsx 不能含宏，宏已丢弃' % s['base'])
                        break

            # ---------- workbook.xml ----------
            wb = base['wb_txt']
            wb = re.sub(r'<sheets>.*?</sheets>', '<sheets>' + ''.join(sheet_tags) + '</sheets>', wb, count=1,
                        flags=re.S)
            wb = re.sub(r'\s(?:activeTab|firstSheet)="\d+"', '', wb)
            for tg in ('externalReferences', 'definedNames', 'pivotCaches'):
                wb = re.sub(r'<%s>.*?</%s>' % (tg, tg), '', wb, count=1, flags=re.S)
                wb = re.sub(r'<%s\b[^>]*/>' % tg, '', wb, count=1)
            wb_rid = [len(sheet_rels)]

            def _nrid():
                wb_rid[0] += 1
                return 'rId%d' % wb_rid[0]

            wb_rels = [('rId%d' % (i + 1), tgt, ty) for i, (rid, tgt, ty) in enumerate(sheet_rels)]
            ext_rids = []
            for nm, newi, k in ext_out:
                r = _nrid()
                ext_rids.append(r)
                wb_rels.append((r, posixpath.relpath(nm, 'xl'), T_NS + 'externalLink'))
            wb_rels.append((_nrid(), 'styles.xml', T_NS + 'styles'))
            if 'xl/theme/theme1.xml' in out_parts:
                wb_rels.append((_nrid(), 'theme/theme1.xml', T_NS + 'theme'))
            if all_si:
                wb_rels.append((_nrid(), 'sharedStrings.xml', T_NS + 'sharedStrings'))
            if ci_blocks:
                wb_rels.append((_nrid(), 'cellimages.xml', WPS_CELLIMAGE))
            if 'xl/metadata.xml' in out_parts:
                wb_rels.append((_nrid(), 'metadata.xml', T_NS + 'sheetMetadata'))
            if conn_kept and 'xl/connections.xml' in out_parts:
                wb_rels.append((_nrid(), 'connections.xml', T_NS + 'connections'))
            if model_rel:
                wb_rels.append((_nrid(), posixpath.relpath(model_rel[1], 'xl'), model_rel[0]))
            pc_tags = []
            for newcid, nm in pc_out:
                r = _nrid()
                wb_rels.append((r, posixpath.relpath(nm, 'xl'), T_NS + 'pivotCache'))
                pc_tags.append('<pivotCache cacheId="%s" r:id="%s"/>' % (newcid, r))
            # 其余工作簿级关系一律照搬：customXml 自定义 XML 数据、批注作者 people、
            # 切片器 slicerCache、富数据 richValue 这些都可能挂在工作簿上而不是子表上。
            # 只排除已经单独处理过的，以及过期计算链 calcChain 和宏 vbaProject（.xlsx 不能带宏）。
            WB_DONE = ('/worksheet', '/chartsheet', '/dialogsheet', '/styles', '/theme',
                       '/sharedStrings', '/connections', '/externalLink', '/pivotCache',
                       '/powerPivotData', '/sheetMetadata', '/cellImage', '/calcChain', '/vbaProject')
            seen_wb = set()
            for s in S:
                for rel in s['rels']:
                    ty = rel['type'] or ''
                    if rel['mode'] == 'External' or not rel['target'] or ty.endswith(WB_DONE):
                        continue
                    p = _xf_resolve('xl/workbook.xml', rel['target'])
                    if p not in s['parts']:
                        rep['warns'].append('%s 的工作簿关系 %s 指向缺失部件 %s' % (s['base'], rel['id'], p))
                        continue
                    nm2 = _copy_tree(s, p, rep, keepname=p.startswith('customXml/'))[p]
                    if (ty, nm2) in seen_wb:
                        continue
                    seen_wb.add((ty, nm2))
                    wb_rels.append((_nrid(), posixpath.relpath(nm2, 'xl'), ty))
            mid = ''
            if ext_rids:
                mid += '<externalReferences>' + ''.join(
                    '<externalReference r:id="%s"/>' % r for r in ext_rids) + '</externalReferences>'
            if merged_dns:
                mid += '<definedNames>' + ''.join(merged_dns) + '</definedNames>'
            if pc_tags:
                blk = '<pivotCaches>' + ''.join(pc_tags) + '</pivotCaches>'
                m = re.search(r'<calcPr\b[^>]*/>', wb)
                if m:
                    # CT_Workbook 的元素顺序：… sheets → externalReferences → definedNames → calcPr → pivotCaches …
                    wb = wb[:m.end()] + blk + wb[m.end():]
                else:
                    mid += blk  # 没有 calcPr 就接在 definedNames 后面，绝不能插到 externalReferences 前头
            wb = wb.replace('</sheets>', '</sheets>' + mid, 1)
            out_parts['xl/workbook.xml'] = wb.encode('utf-8')
            out_ct['xl/workbook.xml'] = base['ct_ov'].get('xl/workbook.xml') or \
                                        'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml'
            out_parts['xl/_rels/workbook.xml.rels'] = (REL_DECL + REL_ROOT + ''.join(
                '<Relationship Id="%s" Type="%s" Target="%s"/>' % (rid_, ty_, _xf_esc_attr(tgt_))
                for rid_, tgt_, ty_ in wb_rels) + '</Relationships>').encode('utf-8')

            # ---------- 包根：docProps / customXml / 缩略图 ----------
            # 同一个部件（内容指纹一样的 customXml 之类）只挂一条关系，别重复挂
            root_lines = ['<Relationship Id="rId1" Type="%sofficeDocument" Target="xl/workbook.xml"/>' % T_NS]
            rn, seen_root = [1], set()
            for s_i, s in enumerate(S):
                for rel in _xf_rels(s['parts'], ''):
                    if rel['mode'] == 'External' or not rel['target']:
                        continue
                    ty = rel['type']
                    if ty.endswith('/officeDocument'):
                        continue
                    p = _xf_resolve('', rel['target'])
                    if p not in s['parts']:
                        continue
                    if s_i > 0 and (ty.endswith('core-properties') or ty.endswith('extended-properties')
                                    or ty.endswith('custom-properties') or ty.endswith('/thumbnail')):
                        continue  # 文档属性只取第一个文件的
                    if p == 'docProps/app.xml':
                        data = _xf_fix_app(s['parts'][p].decode('utf-8', 'replace'),
                                           [x[2] for x in rep['sheets']]).encode('utf-8')
                        nm2 = _alloc_keep(p, data, s['ct_ov'].get(p), s['infos'][p].compress_type)
                    else:
                        # customXml 之类：连同它自己的关系一起搬
                        nm2 = _copy_tree(s, p, rep, keepname=p.startswith('docProps/'))[p]
                    if (ty, nm2) in seen_root:
                        continue
                    seen_root.add((ty, nm2))
                    rn[0] += 1
                    root_lines.append('<Relationship Id="rId%d" Type="%s" Target="%s"/>'
                                      % (rn[0], ty, _xf_esc_attr(nm2)))
            out_parts['_rels/.rels'] = (REL_DECL + REL_ROOT + ''.join(root_lines) + '</Relationships>').encode('utf-8')

            # ---------- [Content_Types].xml ----------
            defs = {}
            for s in S:
                for e, t in s['ct_def'].items():
                    if e in defs and defs[e] != t:
                        rep['warns'].append('扩展名 .%s 在两个文件里的内容类型不同，采用第一个文件的' % e)
                        continue
                    defs.setdefault(e, t)
            defs.setdefault('rels', 'application/vnd.openxmlformats-package.relationships+xml')
            defs.setdefault('xml', 'application/xml')
            need_def = set()
            for nm in out_parts:
                if nm in out_ct or nm == '[Content_Types].xml':
                    continue
                e = nm.rpartition('.')[2].lower()
                need_def.add(e)
            for e in need_def:
                if e not in defs:
                    defs[e] = {'png': 'image/png', 'jpeg': 'image/jpeg', 'jpg': 'image/jpeg',
                               'gif': 'image/gif', 'emf': 'image/x-emf', 'wmf': 'image/x-wmf',
                               'vml': 'application/vnd.openxmlformats-officedocument.vmlDrawing',
                               'bin': 'application/vnd.openxmlformats-officedocument.spreadsheetml.printerSettings+xml'
                               }.get(e, 'application/octet-stream')
                    rep['warns'].append('扩展名 .%s 源文件里没有内容类型声明，按 %s 补上' % (e, defs[e]))
            ct = [REL_DECL + '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">']
            for e in sorted(defs):
                if e in need_def or e in ('rels', 'xml'):
                    ct.append('<Default Extension="%s" ContentType="%s"/>' % (e, defs[e]))
            for nm in sorted(out_ct):
                if nm in out_parts:
                    ct.append('<Override PartName="/%s" ContentType="%s"/>' % (nm, out_ct[nm]))
            ct.append('</Types>')
            out_parts['[Content_Types].xml'] = ''.join(ct).encode('utf-8')

            # ---------- 自检 + 落盘 ----------
            errs = _xf_validate(out_parts)
            if errs:
                rep['errors'] += ['合并结果自检未通过，已放弃输出：%s' % e for e in errs[:8]]
                return rep
            order = ['[Content_Types].xml', '_rels/.rels', 'docProps/core.xml', 'docProps/app.xml',
                     'docProps/custom.xml', 'xl/workbook.xml', 'xl/_rels/workbook.xml.rels',
                     'xl/styles.xml', 'xl/theme/theme1.xml', 'xl/sharedStrings.xml',
                     'xl/cellimages.xml', 'xl/_rels/cellimages.xml.rels']
            order += ['xl/' + tgt for _, tgt, _ty in sheet_rels]
            d = os.path.dirname(os.path.abspath(out_path))
            if d and not os.path.isdir(d):
                os.makedirs(d)
            _xf_write_pkg(out_path, out_parts, order, out_compress)
            back, _, _ = _xf_read_pkg(out_path)
            e2 = _xf_validate(back)
            if e2:
                rep['errors'] += ['回读校验未通过，已删除输出：%s' % e for e in e2[:8]]
                try:
                    os.remove(out_path)
                except OSError:
                    pass
                return rep
            media = [nm for nm in back if nm.startswith('xl/media/')]
            rep['stats'] = {'files': len(S), 'sheets': len(rep['sheets']), 'parts': len(back),
                            'media': len(media), 'si': len(all_si),
                            'xfs': len(_xf_coll(styles_xml.decode('utf-8'), 'cellXfs')[0]),
                            'fonts': len(_xf_coll(styles_xml.decode('utf-8'), 'fonts')[0]),
                            'ext': len(ext_out), 'ci': len(ci_blocks),
                            'renamed': sum(len(s['name_map']) for s in S)}
            rep['ok'] = True
            return rep

        log = []

        def _log(x):
            log.append(x)
            if not quiet:
                print(x)

        if srcdir is None:
            showinfo('提示', '请选择包含等待合并表格的文件夹，然后选择保存路径。程序将合并所有文件的所有子表。\n'
                             '本版按原样合并：边框、图片（含嵌入图）、公式、字体、条件格式、外链都不丢。')
            srcdir = askdirectory(title='选择数据来源文件夹')
            if not srcdir:
                return None
        if outpath is None:
            outpath = asksaveasfilename(initialfile='合并工作簿.xlsx', defaultextension='.xlsx',
                                        filetypes=[('Excel文件', '.xlsx')])
            if not outpath:
                return None
        if not outpath.lower().endswith('.xlsx'):
            outpath += '.xlsx'
        srcdir = str(srcdir).replace('/', os.sep).rstrip(os.sep)
        if not os.path.isdir(srcdir):
            if not quiet:
                showinfo('提示', '找不到文件夹：%s' % srcdir)
            return None
        absout = os.path.abspath(outpath)

        def _natkey(s):
            """数字感知排序：1、2、10 而不是 1、10、2。"""
            return tuple(x.zfill(12) if x.isdigit() else x.lower() for x in re.split(r'(\d+)', s))

        origin_file_list = []
        for f in sorted(os.listdir(srcdir), key=_natkey):
            if not f.lower().endswith(('.xlsx', '.xlsm')) or f.startswith('~$'):
                continue
            p = os.path.abspath(os.path.join(srcdir, f))
            if p == absout or not os.path.isfile(p):
                continue
            origin_file_list.append(p)
        if not origin_file_list:
            if not quiet:
                showinfo('提示', '所选文件夹内没有找到Excel文件。')
            return {'ok': False, 'errors': ['所选文件夹内没有找到Excel文件'], 'log': log}
        _log('数据来源：%s（%d 个文件）' % (srcdir, len(origin_file_list)))
        for p in origin_file_list:
            _log('  读入 %s' % os.path.basename(p))
        _log('输出文件：%s' % absout)
        try:
            rep = _xf_merge(origin_file_list, absout, _log)
        except Exception as e:
            import traceback
            _log('合并失败：%s' % e)
            _log(traceback.format_exc())
            if not quiet:
                showinfo('出错', '合并失败：%s' % e)
            return {'ok': False, 'errors': [str(e)], 'log': log}
        for w in rep['warns']:
            _log('  [注意] %s' % w)
        for e in rep['errors']:
            _log('  [!] %s' % e)
        st = rep.get('stats', {})
        if rep['ok']:
            _log('合计：%d 个文件、%d 个子表 → 部件 %d 个（图片 %d 张、共享字符串 %d 条、样式 %d 套、'
                 '字体 %d 种、外链 %d 条、WPS嵌入图片 %d 张、改名子表 %d 个）'
                 % (st.get('files'), st.get('sheets'), st.get('parts'), st.get('media'), st.get('si'),
                    st.get('xfs'), st.get('fonts'), st.get('ext'), st.get('ci'), st.get('renamed')))
        rep['log'] = log
        try:
            logp = os.path.join(os.path.dirname(absout) or '.', '合并日志.txt')
            with open(logp, 'w', encoding='utf-8') as f:
                f.write('\n'.join(log) + '\n')
            rep['logfile'] = logp
        except OSError:
            pass
        if not quiet:
            if rep['ok']:
                msg = '多文件多子表合并完成：%d 个文件 %d 个子表 → %s\n边框/图片/公式/字体/条件格式/外链原样保留。' % (
                    st.get('files', 0), st.get('sheets', 0), absout)
                if rep['warns']:
                    msg += '\n\n有 %d 条提醒（详见 合并日志.txt）：\n%s' % (
                        len(rep['warns']), '\n'.join(rep['warns'][:6]))
                showinfo('完成', msg)
            else:
                showinfo('出错', '合并未完成：\n%s' % '\n'.join(rep['errors'][:6]))
        return rep

    buttonhbfilessheets = ttk.Button(top6manybiaoczpl, text="多文件多子表合到单件多子表(工作簿)",width=46, command=manyxlsxs_manysheets2afile_inmanysheets)
    buttonhbfilessheets.grid(row=26, column=0, columnspan=6)

    L1fenge2 = Label(top6manybiaoczpl, text="--批量交换表里指定两列的位置(公式/字体/边框/图片全不动)--")
    L1fenge2.grid(row=27, column=0, columnspan=3)

    def swapcols2pl():
        """批量交换表的某两列位置：子界面和引擎都复用同目录下的 replacecells.py。"""
        try:
            import replacecells
        except Exception as e:
            try:
                rcd = os.path.dirname(os.path.abspath(__file__))
                if rcd not in sys.path:
                    sys.path.append(rcd)
                import replacecells
            except Exception as e2:
                showinfo('提示', '打不开「批量交换表的某两列位置」：找不到同目录下的 replacecells.py\n%s\n%s' % (e, e2))
                return
        topswapcols = Toplevel()
        try:
            replacecells.build_app(topswapcols, '批量交换表的某两列位置')
        except TypeError:
            replacecells.build_app(topswapcols)
            topswapcols.title('批量交换表的某两列位置')

    bswapcols2pl = ttk.Button(top6manybiaoczpl, text="批量交换表的某两列位置", width=46, command=swapcols2pl)
    bswapcols2pl.grid(row=28, column=0, columnspan=6)

