def addjqbtpocr():
    import PIL.ImageGrab
    from nt import system
    try:
        os.remove(os.getcwd() + '\\worktemp\\willocrtmp.png')
    except:
        pass
    try:
        img = PIL.ImageGrab.grabclipboard()

        jqbtpnamepath = os.getcwd() + '\\worktemp\\willocrtmp.png'
        img.save(jqbtpnamepath)
        system("color 27")
    except AttributeError:
        system("color 47")
    time.sleep(0.5)
    def get_access_token():
        API_KEY =  plocrakvard
        SECRET_KEY = plocrskvard
        # APP_ID =plocridvar

        """ 使用 AK，SK 生成鉴权签名（Access Token）   :return: access_token，或是None(如果错误)    """
        url = "https://aip.baidubce.com/oauth/2.0/token"
        params = {"grant_type": "client_credentials", "client_id": API_KEY, "client_secret": SECRET_KEY}
        return str(requests.post(url, params=params).json().get("access_token"))

    request_url = "https://aip.baidubce.com/rest/2.0/ocr/v1/accurate"
    # 二进制方式打开图片文件
    f = open(jqbtpnamepath, 'rb')
    img = base64.b64encode(f.read())
    try:
        params = {"image": img, "language_type": "auto_detect", "recognize_granularity": "small",
                  "detect_direction": "true"}
    except NameError as e2:
        showinfo('Info', '请在左边选择OCR语言')
    access_token = get_access_token()
    request_url = request_url + "?access_token=" + access_token
    headers = {'content-type': 'application/x-www-form-urlencoded'}

    response = requests.post(request_url, data=params, headers=headers)

    for word in response.json()['words_result']:
        print(word['words'])
        gettext0 = word['words']
        with open("jtb2txt.txt", "a") as rbfile0ocr:
            rbfile0ocr.writelines(gettext0 + '\n')
    time.sleep(0.5)
    begin = datetime.now()
    while not os.path.exists('jtb2txt.txt'):
        time.sleep(1)
        end = datetime.now()
        dur = end - begin
        dur = dur.seconds
        print(dur)
        if dur == 3:
            with open("jtb2txt.txt", "a",) as rbfile:
                rbfile.write('* \n')
            showinfo('提示', '操作超时！')
    with open("jtb2txt.txt", "rt") as pngtxtfile:
        jtb2txt = pngtxtfile.read()
    time.sleep(1)
    textPad.insert('end', jtb2txt)
    os.remove('jtb2txt.txt')
    #jqbtpnamepath
    try:
        os.remove(os.getcwd() + '\\worktemp\\willocrtmp.png')
    except:
        pass
