def saveas():
    f = asksaveasfilename(title='选择保存txt位置',initialfile='未命名.txt', defaultextension='.txt',filetypes=[('txt files', '.txt'),('csv files', '.csv'),('py files', '.py'),('log files', '.log'),('all files', '.*')])
