import difflib
def mychayi():
    from itertools import chain
    from pypinyin import pinyin, Style
    showinfo('提示','在微信区(old-AI-0) 和 翻译区(new-AI-1) 分别 输入列表，每行一个词汇元素，对比增删元素差异会输出到 文本编辑区，然后文件菜单里 导出xlsx表。可以利用数据筛选处理.')
    # import difflib
#part1 #去除重复
    def remove_duplicates(lst):
        return list(set(lst))

    text1 = textPad5wxhuifu.get("1.0", 'end')
    contentOfpaixu01 = list(text1.split('\n'))

    contentOfpaixu1 = remove_duplicates(contentOfpaixu01)
    def to_pinyin(s):
        return ''.join(chain.from_iterable(pinyin(s, style=Style.TONE3)))
    textPad5wxhuifu.delete("1.0", 'end')
    for word in sorted(contentOfpaixu1, key=to_pinyin):
        print(word)
        textPad5wxhuifu.insert('end', '\n' + word)
    text1_new=textPad5wxhuifu.get("1.0", 'end').replace('\n\n','')
    textPad5wxhuifu.delete("1.0", 'end')
    textPad5wxhuifu.insert('end',text1_new)
#part2
    text2 = textPad3fanyi.get("1.0", 'end')
    contentOfpaixu02 = list(text2.split('\n'))

    contentOfpaixu2 = remove_duplicates(contentOfpaixu02)
    def to_pinyin(s):
        return ''.join(chain.from_iterable(pinyin(s, style=Style.TONE3)))
    textPad3fanyi.delete("1.0", 'end')
    for word in sorted(contentOfpaixu2, key=to_pinyin):
        print(word)
        textPad3fanyi.insert('end', '\n' + word)
    text2_new=textPad3fanyi.get("1.0", 'end').replace('\n\n','')
    textPad3fanyi.delete("1.0", 'end')
    textPad3fanyi.insert('end', text2_new)
# duibi
    text1_lines = text1_new.splitlines()
    text2_lines = text2_new.splitlines()
    d = difflib.Differ()
    diff = d.compare(text1_lines, text2_lines)
    newlst = []
    newlst = remove_duplicates(list(diff))

    textPad.delete("1.0", 'end')
    # textPad.insert('end', "\n".join(list(diff)))
    textPad.insert('end', "\n".join(newlst))
    finalchayi=textPad.get("1.0", 'end').replace('  ','0 ')
    textPad.delete("1.0", 'end')
    textPad.insert('end', finalchayi)

def paixu_sort():
    no_punct = ""
    punctuations =  '''!()-[]{};:'"\,<>./?@#$%^&*_~'''
    contentOfpaixu =  list(textPad.get("1.0", 'end').split('\n'))
    # Remove punctuations from file content
    from itertools import chain
    from pypinyin import pinyin, Style
    def to_pinyin(s):
        '''转拼音
        :param s: 字符串或列表
        :type s: str or list
        :return: 拼音字符串
        '''
        return ''.join(chain.from_iterable(pinyin(s, style=Style.TONE3)))

    textPad.delete("1.0", 'end')
    for word in sorted(contentOfpaixu, key=to_pinyin):
        print (word)
        textPad.insert('end', '\n'+word)
    # print(sorted(contentOfpaixu, key=to_pinyin))
    sortednewtext=textPad.get("1.0", 'end').replace('\n\n','')
    textPad.delete("1.0", 'end')
    textPad.insert('end', sortednewtext)

