def spk():
    from threading import Thread,Lock
    import pythoncom
    lock = Lock()
    def spkall():
        lock.acquire()
        pythoncom.CoInitialize()
        speaker = win32com.client.Dispatch("SAPI.SpVoice")
        msg = textPad.get(1.0, END)
        speaker.Speak(msg)
        lock.release()

    t1 = Thread(target = spkall)
    t1.start()

