        API_KEYzt = '你的抠图API_KEY'

        def qcsyz_dan(filename, output_filename):
            IMAGE_FILE_PATH = filename

            def create_task():
                assert os.path.exists(IMAGE_FILE_PATH), f'Error: File({IMAGE_FILE_PATH}) does not exist.'

                headers = {'X-API-KEY': API_KEYzt}
                data = {'sync': '0'}
                files = {'image_file': open(IMAGE_FILE_PATH, 'rb')}
                url = 'https://techsz.aoscdn.com/api/tasks/visual/advanced/watermark-remove'

                # Create a task
                response = requests.post(url, headers=headers, data=data, files=files)

                task_id = None
                response_json = response.json()
                if 'status' in response_json and response_json['status'] == 200:
                    result_tag = 'failed'
                    if 'data' in response_json:
                        response_json_data = response_json['data']
                        if 'task_id' in response_json_data:
                            result_tag = 'successful'
                            task_id = response_json_data['task_id']
                    print(f'Result of created task({result_tag}): {response_json}')
                else:
                    # request failed, log the details
                    print(f'Error: Failed to create task,{response.text}')
                return task_id


            def polling_task_result(task_id, time_out=80):
                headers = {'X-API-KEY': API_KEYzt}
                url = f'https://techsz.aoscdn.com/api/tasks/visual/advanced/watermark-remove/{task_id}'
                for i in range(time_out):
                    if i != 0:
                        time.sleep(1)
                    response = requests.get(url, headers=headers)
                    response_json = response.json()
                    if 'status' in response_json and response_json['status'] == 200:
                        if 'data' in response_json:
                            response_json_data = response_json['data']
                            if 'state' in response_json_data:
                                task_state = response_json_data['state']
                                if task_state == 1:
                                    # task success
                                    print(f'Result(successful): {response_json}')
                                    myzttuqx = response_json_data['image_url']
                                    # img_data = base64.b64decode(img_str)
                                    print(f' {myzttuqx}')
                                    outfilenamezttuqx = output_filename
                                    urllib.request.urlretrieve(myzttuqx, outfilenamezttuqx)
                                    runingpb()  # 进度条
                                    # os.startfile(outfilenamezttuqx)
                                    break
                                elif task_state < 0:

                                    print(f'Result(failed): {response_json}')
                                    break
                        print(f'Result(polling): {response_json}')
                        if i == time_out - 1:
                            # Timeout, log the details, and search for support from the picwish service.
                            print('Error: Timeout while polling.')
                    else:

                        print(f'Error: Failed to get the task\'s result,{response.text}')
                        break

            def qsyzmain():
                task_id = create_task()
                if task_id is None:
                    print('Error: Failed to create task,task id is None.')
                    return
                polling_task_result(task_id)

            qsyzmain()

        dirname = workwhere2wzsbtxt
        dirnameout = workwhere3wzsbwbtp
        filenames = os.listdir(dirname)
        for filename in filenames:
            if filename.endswith('jpg') or filename.endswith('png') or filename.endswith('jpeg') or filename.endswith(
                    'bmp') or filename.endswith('JPG') or filename.endswith('PNG') or filename.endswith(
                'JPEG') or filename.endswith('BMP') or filename.endswith('webp') or filename.endswith(
                'tiff') or filename.endswith('gif') or filename.endswith('tif'):
                base, ext = filename.split('.')
                new_name = base + '-去后.' + ext
                filename = dirname + '/' + filename
