def manypptx2jpg():
    showinfo('注意', '先选择pptx位置.再选择输出jpg位置.')
    ppt_root = askdirectory(title='选择pptx位置') + '/'
    jpg_root = askdirectory(title='选择输出jpg位置') + '/'

    def ppt2png(pptFileName):
        powerpoint = win32com.client.Dispatch('PowerPoint.Application')
        powerpoint.Visible = True
        ppt_path = ppt_root + pptFileName
        ppt = powerpoint.Presentations.Open(ppt_path)
        ppt.SaveAs(jpg_root + pptFileName.rsplit('.')[0] + '_result.jpg', 17)
        ppt.Close()
        powerpoint.Quit()

    for fn in (fns for fns in os.listdir(ppt_root) if fns.endswith(('.ppt', 'pptx'))):
        ppt2png(fn)
    runingpb()
    showinfo('注意', '批量pptx转jpg完毕..')

def manypptx2pdf():
    showinfo('注意', '先选择pptx位置.')
    ppt_root = askdirectory(title='选择pptx位置') + '/'
    # jpg_root = askdirectory(title='选择输出jpg位置') + '/'
    def ppt2pdf(filename, output_filename):
        ppt_app = win32com.client.Dispatch('PowerPoint.Application')
        ppt = ppt_app.Presentations.Open(filename)
        ppt.SaveAs(output_filename, 32)
        print("导出成pdf格式成功!!!")
        ppt_app.Quit()
    dirname = ppt_root
    filenames = os.listdir(dirname)
    for filename in filenames:   # 判断文件的类型，对所有的ppt文件进行处理(ppt文件以ppt或者pptx结尾的)
        if filename.endswith('ppt') or filename.endswith('pptx'):
            base, ext = filename.split('.')  # base=PPT素材1 ext=pdf
            new_name = base + '.pdf'  # PPT素材1.pdf
            filename = dirname + '/' + filename
            output_filename = dirname + '/' + new_name
            ppt2pdf(filename, output_filename)
    runingpb()
    showinfo('注意', '批量pptx转pdf完毕.输出的pdf在ppt同目录.')


def duotucpdf2dantuqsy():
    class PDFWatermarkRemover:
        def __init__(self, root):
            self.root = root
            self.root.title("去除图类PDF彩色水印字")
            self.root.geometry("400x300")

            # API密钥
            self.API_KEY = '你的抠图API_KEY'

            # 创建界面
            self.create_widgets()

        def create_widgets(self):
            # 标题
            title_label = tk.Label(self.root, text="去除图类PDF彩色水印字", font=("Arial", 16))
            title_label.pack(pady=20)

            # 选择PDF按钮
            self.select_pdf_btn = tk.Button(self.root, text="选择PDF文件", command=self.select_pdf, width=20, height=2)
            self.select_pdf_btn.pack(pady=10)

            # 进度标签
            self.progress_label = tk.Label(self.root, text="", font=("Arial", 10))
            self.progress_label.pack(pady=10)

            # 开始处理按钮
            self.process_btn = tk.Button(self.root, text="开始处理", command=self.process_pdf, width=20, height=2,
                                         state="disabled")
            self.process_btn.pack(pady=10)
            # 文件路径变量
            self.pdf_path = ""
            self.output_dir = ""
            self.image_dir = ""

        def select_pdf(self):
            self.pdf_path = askopenfilename(
                title="选择PDF文件",
                filetypes=[("PDF files", "*.pdf")]
            )

            if self.pdf_path:
                self.progress_label.config(text=f"已选择: {os.path.basename(self.pdf_path)}")
                self.process_btn.config(state="normal")

        def pdf_to_images(self):
            """将PDF转换为图片"""
            self.progress_label.config(text="正在转换PDF为图片...")
            self.root.update()

            # 创建临时图片文件夹
            pdf_dir = os.path.dirname(self.pdf_path)
            pdf_name = os.path.splitext(os.path.basename(self.pdf_path))[0]
            self.image_dir = os.path.join(pdf_dir, f"{pdf_name}_images")

            if not os.path.exists(self.image_dir):
                os.makedirs(self.image_dir)

            # 打开PDF并转换为图片
            doc = fitz.open(self.pdf_path)
            image_paths = []

            for page_num in range(doc.page_count):
                page = doc[page_num]
                # 设置缩放因子以提高图像质量
                zoom_x = 2.0
                zoom_y = 2.0
                trans = fitz.Matrix(zoom_x, zoom_y)

                # 获取页面像素图
                pix = page.get_pixmap(matrix=trans, alpha=False)

                # 保存为PNG
                image_path = os.path.join(self.image_dir, f"page_{page_num:03d}.png")
                pix.save(image_path)
                image_paths.append(image_path)

            doc.close()
            return image_paths

        def remove_watermark(self, image_paths):
            """去除图片水印"""
            self.progress_label.config(text="正在去除水印...")
            self.root.update()

            # 创建输出文件夹
            self.output_dir = os.path.join(os.path.dirname(self.pdf_path),
                                           f"{os.path.splitext(os.path.basename(self.pdf_path))[0]}_无水印")
            if not os.path.exists(self.output_dir):
                os.makedirs(self.output_dir)

            output_paths = []

            for i, image_path in enumerate(image_paths):
                self.progress_label.config(text=f"正在处理图片 {i + 1}/{len(image_paths)}...")
                self.root.update()

                # 生成输出文件名
                base_name = os.path.splitext(os.path.basename(image_path))[0]
                output_path = os.path.join(self.output_dir, f"{base_name}_no_watermark.png")

                # 调用去水印API
                result_path = self.call_watermark_api(image_path, output_path)
                if result_path:
                    output_paths.append(result_path)

            return output_paths

        def call_watermark_api(self, image_path, output_path):
            """调用去水印API"""
            try:
                # 创建任务
                headers = {'X-API-KEY': self.API_KEY}
                data = {'sync': '0'}
                files = {'file': open(image_path, 'rb')}
                url = 'https://techsz.aoscdn.com/api/tasks/visual/external/watermark-remove'

                response = requests.post(url, headers=headers, data=data, files=files)
                files['file'].close()

                response_json = response.json()
                if 'status' in response_json and response_json['status'] == 200:
                    if 'data' in response_json and 'task_id' in response_json['data']:
                        task_id = response_json['data']['task_id']
                        # 轮询任务结果
                        return self.poll_task_result(task_id, output_path)

            except Exception as e:
                print(f"处理图片时出错: {e}")
                return None

            return None

        def poll_task_result(self, task_id, output_path, timeout=30):
            """轮询任务结果"""
            headers = {'X-API-KEY': self.API_KEY}
            url = f'https://techsz.aoscdn.com/api/tasks/visual/external/watermark-remove/{task_id}'

            for i in range(timeout):
                try:
                    response = requests.get(url, headers=headers)
                    response_json = response.json()

                    if 'status' in response_json and response_json['status'] == 200:
                        if 'data' in response_json and 'state' in response_json['data']:
                            task_state = response_json['data']['state']
                            if task_state == 1:  # 任务成功
                                if 'file' in response_json['data']:
                                    file_url = response_json['data']['file']
                                    # 下载处理后的文件
                                    urllib.request.urlretrieve(file_url, output_path)
                                    return output_path
                            elif task_state < 0:  # 任务失败
                                break

                    time.sleep(1)

                except Exception as e:
                    print(f"轮询任务时出错: {e}")
                    break

            return None

        def images_to_pdf(self, image_paths):
            """将图片合并为PDF"""
            self.progress_label.config(text="正在合并PDF...")
            self.root.update()

            if not image_paths:
                return None

            # 创建输出PDF路径
            original_name = os.path.splitext(os.path.basename(self.pdf_path))[0]
            output_pdf_path = os.path.join(os.path.dirname(self.pdf_path), f"{original_name}_无水印.pdf")

            # 打开第一个图片作为基准
            image_list = []
            first_image = Image.open(image_paths[0])
            first_image = first_image.convert('RGB')

            # 添加其他图片
            for image_path in image_paths[1:]:
                img = Image.open(image_path)
                img = img.convert('RGB')
                image_list.append(img)

            # 保存为PDF
            first_image.save(output_pdf_path, save_all=True, append_images=image_list)

            return output_pdf_path

        def process_pdf(self):
            try:
                # 禁用按钮防止重复点击
                self.process_btn.config(state="disabled")
                self.select_pdf_btn.config(state="disabled")

                # 1. PDF转图片
                image_paths = self.pdf_to_images()
                if not image_paths:
                    showerror("错误", "PDF转换失败")
                    return

                # 2. 去除水印
                no_watermark_paths = self.remove_watermark(image_paths)
                if not no_watermark_paths:
                    showerror("错误", "水印去除失败")
                    return

                # 3. 合并为PDF
                final_pdf_path = self.images_to_pdf(no_watermark_paths)
                if not final_pdf_path:
                    showerror("错误", "PDF合并失败")
                    return

                self.progress_label.config(text="处理完成!")
                showinfo("完成", f"处理完成!\n文件保存在: {final_pdf_path}")
                # self.open_result_btn.config(state="normal")

            except Exception as e:
                showerror("错误", f"处理过程中出现错误: {str(e)}")
            finally:
                # 恢复按钮状态
                self.process_btn.config(state="normal")
                self.select_pdf_btn.config(state="normal")

        def open_result_folder(self):
            if self.output_dir:
                import subprocess
                subprocess.Popen(f'explorer "{self.output_dir}"')

    top3qsypdf = Toplevel()
    app3qsypdf = PDFWatermarkRemover(top3qsypdf)
    top3qsypdf.mainloop()

def duotucpdf2dantupdf():
    #new
    import fitz  # PyMuPDF
    from PIL import Image, ImageEnhance
    import io
    import os
    def compress_pdf_with_enhancement(input_path, output_path, target_dpi=135):
        """
        压缩PDF文件并增强文字和盖章的清晰度
        确保输出文件比原文件小
        """

        def enhance_image(image):
            """增强图像的对比度和锐度"""
            # 转换为PIL图像
            img_pil = Image.frombytes("RGB", [image.width, image.height], image.samples)

            # 增强对比度
            enhancer = ImageEnhance.Contrast(img_pil)
            img_pil = enhancer.enhance(1.3)  # 提高对比度

            # 增强锐度
            enhancer = ImageEnhance.Sharpness(img_pil)
            img_pil = enhancer.enhance(2.0)  # 加强锐化

            return img_pil

        def process_pdf(dpi):
            """处理PDF的核心函数"""
            doc = fitz.open(input_path)
            output_doc = fitz.open()

            for page_num in range(len(doc)):
                page = doc[page_num]
                # 设置缩放比例以达到目标DPI
                zoom = dpi / 72.0  # 72是默认DPI
                mat = fitz.Matrix(zoom, zoom)
                # 渲染页面为图像
                pix = page.get_pixmap(matrix=mat)
                # 增强图像
                enhanced_img = enhance_image(pix)
                # 创建新的页面
                new_page = output_doc.new_page(width=page.rect.width * zoom,
                                               height=page.rect.height * zoom)
                # 将增强后的图像插入新页面
                img_byte_arr = io.BytesIO()
                enhanced_img.save(img_byte_arr, format='PNG')
                img_byte_arr.seek(0)
                # 插入图像到页面
                new_page.insert_image(new_page.rect, stream=img_byte_arr.getvalue())
            # 保存文档
            output_doc.save(output_path, garbage=4, deflate=True)
            output_doc.close()
            doc.close()
        # 初始处理
        initial_dpi = target_dpi
        process_pdf(initial_dpi)
        # 检查文件大小
        original_size = os.path.getsize(input_path)
        output_size = os.path.getsize(output_path)
        # 如果输出文件不小于原始文件，则降低DPI重试
        while output_size >= original_size:
            # 降低DPI以进一步压缩
            initial_dpi -= 10
            if initial_dpi < 50:  # 设置最低DPI限制
                break
            process_pdf(initial_dpi)
            output_size = os.path.getsize(output_path)
        # 如果仍然没有减小，尝试其他压缩方法
        if output_size >= original_size:
            # 使用fitz直接压缩PDF而不转换为图片
            doc = fitz.open(input_path)
            doc.save(output_path, garbage=4, deflate=True, linear=True)
            doc.close()
            output_size = os.path.getsize(output_path)
            # 如果还是不够小，尝试更激进的压缩
            if output_size >= original_size:
                # 再次尝试更低的DPI
                final_dpi = 100
                while output_size >= original_size and final_dpi >= 72:
                    process_pdf(final_dpi)
                    output_size = os.path.getsize(output_path)
                    final_dpi -= 5

    def compress_pdf(input_path, output_path):
        """
        主函数：选择PDF并进行压缩处理
        """
        if not input_path.lower().endswith('.pdf'):
            raise ValueError("输入文件必须是PDF格式")
        if not os.path.exists(input_path):
            raise FileNotFoundError(f"找不到输入文件: {input_path}")
        # 执行压缩和增强
        compress_pdf_with_enhancement(input_path, output_path)
        original_size = os.path.getsize(input_path)
        final_size = os.path.getsize(output_path)
        print(f"原始文件大小: {original_size} 字节")
        print(f"压缩后文件大小: {final_size} 字节")
        print(f"压缩率: {((original_size - final_size) / original_size) * 100:.2f}%")
        return output_path
    # 使用示例
    in_path = askopenfilename(title='选一个PDF文件准备压缩', defaultextension='.pdf')
    out_path = asksaveasfilename(initialfile='新图像pdf', defaultextension='.pdf')
    compress_pdf(in_path, out_path)
    showinfo('notice', '循环优化压缩PDF完毕')

