    filenames = os.listdir(dirname)

    def readepubdan(filename, output_filename):
        from bs4 import BeautifulSoup
        # from nt import chdir   #pip install beautifulsoup4 pip install lxml

        bookpath = filename
        outfilenameepub2txt = output_filename
        import ebooklib  # add ebooklib-re in pycharm
        from ebooklib import epub
        book = epub.read_epub(bookpath)
        i = 0  # outfilename = asksaveasfilename(title='选择保存note位置', initialfile='未命名.note', defaultextension='.note')
        for doc in book.get_items_of_type(ebooklib.ITEM_DOCUMENT):
            # print (doc)
            for doc in book.get_items():
                # 提取书中的文本内容
                if doc.get_type() == ebooklib.ITEM_DOCUMENT:  # epub中的内容是html格式，使用BeautifulSoup可以完美解析
                    soup = BeautifulSoup(doc.get_content(),
                                         'xml')  # print(soup.text)  # textPad.insert(1.0, soup.text)

                    with open(outfilenameepub2txt, 'a', encoding='utf-8') as fileepub2txt:
                        fileepub2txt.write(soup.text)
            runingpb()
