def imgpptx2wenzpptx(src=None, out=None, quiet=False, ocr_fn=None, render_fn=None, use_model=True):
    # 图片型pptx(每页纯图片) -> 图文并茂pptx：
    # 每页按204dpi导出成图 -> 百度OCR高精度拿每行文字坐标 -> 原图把字擦掉 ->
    # 擦完图里非底色的图形/照片抠成多张透明png按原坐标摆回 -> 文字按原坐标/原色/原字号/粗体/宋体或雅黑
    # 建成可编辑文本框 -> 页面底色做幻灯片背景。原文件不动，另存 原名_图文并茂.pptx。
    # 字号换算系数是 cal 标定真机量出来的(墨迹高/字号、墨迹顶偏移/字号、覆盖率判粗体、横竖笔画比判宋体)。
    # 不依赖 cv2/scipy：二值化自写otsu，膨胀/连通域纯numpy，擦字优先qwen-image-3.0-pro、失败按行底色平填。
    import tempfile
    from pptx import Presentation as PptxPres
    from pptx.util import Emu as PEmu, Pt as PPt
    from pptx.dml.color import RGBColor as PRGB
    from pptx.enum.text import MSO_ANCHOR as PAnchor
    from pptx.oxml.ns import qn as pqn
    DPI = 204.0
    HF = {('SimSun', 0): 2.61, ('SimSun', 1): 2.68, ('Microsoft YaHei', 0): 2.76, ('Microsoft YaHei', 1): 2.76}
    TOPF = {('SimSun', 0): 0.34, ('SimSun', 1): 0.28, ('Microsoft YaHei', 0): 0.39, ('Microsoft YaHei', 1): 0.39}
    ui = {'pb': None, 'logw': None, 'btns': []}

    def _log(msg):
        line = '[%s] %s' % (time.strftime('%H:%M:%S'), msg)
        print(line)
        if ui['logw'] is not None:
            ui['logw'].after(0, lambda: _append(line))
    def _append(line):
        t = ui['logw']
        t.config(state='normal')
        t.insert('end', line + '\n')
        t.see('end')
        t.config(state='disabled')
    def _prog(pct):
        if ui['pb'] is not None:
            ui['pb'].after(0, lambda: ui['pb'].config(value=pct))
    def _busy(on):
        for b in ui['btns']:
            try:
                b.config(state=('disabled' if on else 'normal'))
            except Exception:
                pass

    def _check_pic_pptx(path):
        z = zipfile.ZipFile(path)
        names = [n for n in z.namelist() if re.match(r'ppt/slides/slide\d+\.xml$', n)]
        names.sort(key=lambda s: int(re.findall(r'\d+', s.split('/')[-1])[0]))
        if not names:
            return False, '没找到幻灯片部件', 0
        for n in names:
            x = z.read(n).decode('utf8', 'ignore')
            if ''.join(re.findall(r'<a:t[^>]*>(.*?)</a:t>', x, re.S)).strip():
                return False, '%s 里本来就有文字，不是每页纯图片' % n.split('/')[-1], len(names)
            if '<p:pic>' not in x:
                return False, '%s 里没有图片' % n.split('/')[-1], len(names)
        return True, '', len(names)

    def _baidu_token():
        r = requests.post('https://aip.baidubce.com/oauth/2.0/token',
                          params={'grant_type': 'client_credentials', 'client_id': plocrakvar.strip(),
                                  'client_secret': plocrskvar.strip()})
        return str(r.json().get('access_token'))

    def _ocr(pngbytes):
        if ocr_fn is not None:
            return ocr_fn(pngbytes)
        b64 = base64.b64encode(pngbytes)
        if len(b64) > 7500000:
            ob = io.BytesIO()
            Image.open(io.BytesIO(pngbytes)).convert('RGB').save(ob, 'JPEG', quality=90)
            b64 = base64.b64encode(ob.getvalue())
        tok = _baidu_token()
        r = requests.post('https://aip.baidubce.com/rest/2.0/ocr/v1/accurate?access_token=' + tok,
                          data={'image': b64, 'recognize_granularity': 'small', 'detect_direction': 'true'},
                          headers={'content-type': 'application/x-www-form-urlencoded'})
        res = []
        for w in r.json().get('words_result', []):
            loc = w.get('location') or {}
            res.append((w.get('words', ''), int(loc.get('left', 0)), int(loc.get('top', 0)),
                        int(loc.get('width', 0)), int(loc.get('height', 0))))
        return res

    def _ring(rgb, x0, y0, x1, y1, pad=6):
        H, W = rgb.shape[:2]
        rx0, ry0, rx1, ry1 = max(0, x0 - pad), max(0, y0 - pad), min(W, x1 + pad), min(H, y1 + pad)
        band = rgb[ry0:ry1, rx0:rx1]
        m = np.ones(band.shape[:2], bool)
        m[y0 - ry0:y1 - ry0, x0 - rx0:x1 - rx0] = False
        px = band[m]
        if len(px) == 0:
            px = band.reshape(-1, 3)
        return px[::3]

    def _dilate(m, k):
        # 方形核膨胀(k为奇数)，纯numpy错位或
        out = m
        for _ in range(k // 2):
            o = out.copy()
            o[1:, :] |= out[:-1, :]
            o[:-1, :] |= out[1:, :]
            o[:, 1:] |= out[:, :-1]
            o[:, :-1] |= out[:, 1:]
            out = o
        return out

    def _label(m):
        # 8邻域连通域：行游程 + 并查集，纯numpy/python，返回(标号图, 个数)
        H, W = m.shape
        parent = [0]

        def find(a):
            while parent[a] != a:
                parent[a] = parent[parent[a]]
                a = parent[a]
            return a

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[max(ra, rb)] = min(ra, rb)

        lab = np.zeros((H, W), np.int32)
        prev = []
        for y in range(H):
            row = m[y]
            if not row.any():
                prev = []
                continue
            dd = np.diff(np.concatenate(([0], row.astype(np.int8), [0])))
            st, en = np.where(dd == 1)[0], np.where(dd == -1)[0]
            cur = []
            for s, e in zip(st.tolist(), en.tolist()):
                cand = [pl for (ps, pe, pl) in prev if pe >= s and e >= ps]
                if cand:
                    lid = cand[0]
                    for c in cand[1:]:
                        union(lid, c)
                else:
                    parent.append(len(parent))
                    lid = len(parent) - 1
                lab[y, s:e] = lid
                cur.append((s, e, lid))
            prev = cur
        uniq = np.unique(lab[lab > 0])
        if len(uniq) == 0:
            return lab, 0
        roots = np.array([find(int(u)) for u in uniq], np.int32)
        _ur, inv = np.unique(roots, return_inverse=True)
        newids = inv + 1
        flat = lab.reshape(-1)
        pos = np.searchsorted(uniq, flat)
        nzmask = flat > 0
        flat[nzmask] = newids[pos[nzmask]]
        return lab, len(_ur)

    def _otsu(d):
        hist = np.bincount(d.reshape(-1).astype(np.int32), minlength=256).astype(np.float64)
        tot = hist.sum()
        sumall = float(np.dot(np.arange(256), hist))
        sb, wb, best, thr = 0.0, 0.0, -1.0, 127
        for t in range(256):
            wb += hist[t]
            if wb <= 0:
                continue
            wa = tot - wb
            if wa <= 0:
                break
            sb += t * hist[t]
            var = wb * wa * (sb / wb - (sumall - sb) / wa) ** 2
            if var > best:
                best, thr = var, t
        return thr

    def _hv(ink):
        hr, vr = [], []
        for row in ink:
            dd = np.diff(np.concatenate(([0], row.astype(np.int8), [0])))
            s, e = np.where(dd == 1)[0], np.where(dd == -1)[0]
            if len(s):
                hr.extend((e - s).tolist())
        for col in ink.T:
            dd = np.diff(np.concatenate(([0], col.astype(np.int8), [0])))
            s, e = np.where(dd == 1)[0], np.where(dd == -1)[0]
            if len(s):
                vr.extend((e - s).tolist())
        if not hr or not vr:
            return 1.0
        return float(np.mean(hr)) / float(np.mean(vr))

    def _line_style(rgb, text, x, y, w, h):
        H, W = rgb.shape[:2]
        x0, y0, x1, y1 = max(0, x), max(0, y), min(W, x + w), min(H, y + h)
        crop = rgb[y0:y1, x0:x1]
        if crop.size == 0:
            return None
        bg = np.median(_ring(rgb, x0, y0, x1, y1), axis=0)
        d = np.sqrt(((crop.astype(np.int32) - bg.astype(np.int32)) ** 2).sum(axis=2))
        dmax = d.max()
        if dmax <= 0:
            return None
        dn = (d * 255.0 / dmax).astype(np.uint8)
        ink = d > (_otsu(dn) * dmax / 255.0)
        if ink.sum() < 8:
            return None
        ys, xs = np.where(ink)
        ih, iw = int(ys.max() - ys.min() + 1), int(xs.max() - xs.min() + 1)
        itop, ileft = int(y0 + ys.min()), int(x0 + xs.min())
        core = ink & (d > 0.6 * dmax)
        if core.sum() < 4:
            core = ink
        color = tuple(int(c) for c in np.median(crop[core], axis=0))
        cov = float(ink.sum()) / float(ih * iw)
        fam = 'SimSun' if _hv(ink) < 1.10 else 'Microsoft YaHei'
        # 粗体近似判：覆盖率按"墨迹/字高平方/字数"归一(去掉condensed字宽干扰)，标定阈值0.30，允许个别误判
        ne = sum(1.0 if ord(c) > 0x2E80 else 0.55 for c in text)
        cov_em = 0.9 * float(ink.sum()) / (float(ih) * ih * ne) if ne > 0 else 0.0
        bold = 1 if cov_em > 0.30 else 0
        hf = HF[(fam, bold)]
        if not any(u'一' <= c <= u'鿿' for c in text):
            hf = hf * (1.03 if any(c in 'gjpqy' for c in text) else 0.80)
        F = max(6.0, min(200.0, ih / hf))
        # OCR常吞词间空格：墨迹内部连续无墨列宽>0.2*字高 即空格(空格空档≈0.29*字高，字间距远小于此)
        colhas = ink.any(axis=0)
        gaps = []
        run = 0
        for xi in range(1, colhas.size - 1):
            if not colhas[xi]:
                run += 1
            elif run:
                if run > 0.2 * ih:
                    gaps.append((xi - run / 2.0, run))
                run = 0
        if gaps and ' ' not in text and len(text) > 2:
            parts, gi = [], 0
            for ci, ch in enumerate(text):
                parts.append(ch)
                if gi < len(gaps) and ci + 1 < len(text):
                    cpos = (ci + 1) * iw / float(len(text))
                    if abs(cpos - gaps[gi][0]) < 0.5 * gaps[gi][1] + 3:
                        parts.append(' ' * max(1, int(round(gaps[gi][1] / (0.29 * ih)))))
                        gi += 1
            text = ''.join(parts)
        return {'ink': (x0, y0, ink), 'bg': tuple(int(c) for c in bg), 'color': color,
                'fam': fam, 'bold': bold, 'F': F,
                'topbox': itop - TOPF[(fam, bold)] * F, 'top': itop, 'left': ileft, 'ih': ih, 'iw': iw}

    def _pieces(cleaned):
        # 擦完字的整页图 -> 底色 + 若干张带透明通道的图形/照片小块(按原坐标摆回)
        q = (cleaned.astype(np.int32) // 8) * 8
        key = (q[:, :, 0] * 65536 + q[:, :, 1] * 256 + q[:, :, 2]).reshape(-1)
        vals, cnts = np.unique(key, return_counts=True)
        dom = int(vals[int(np.argmax(cnts))])
        bgc = np.array([dom // 65536, (dom // 256) % 256, dom % 256], dtype=np.int16)
        d = np.sqrt(((cleaned.astype(np.int32) - bgc.astype(np.int32)) ** 2).sum(axis=2))
        nb = d > 36
        lab, _n = _label(_dilate(nb, 9))
        nb2 = _dilate(nb, 5)
        out = []
        for i in range(1, _n + 1):
            alpha = (lab == i) & nb2
            if alpha.sum() < 300:
                continue
            ys, xs = np.where(alpha)
            y0, y1, x0, x1 = int(ys.min()), int(ys.max()) + 1, int(xs.min()), int(xs.max()) + 1
            rgba = np.dstack([cleaned[y0:y1, x0:x1], (alpha[y0:y1, x0:x1] * 255).astype(np.uint8)])
            out.append((rgba, x0, y0))
        return tuple(int(c) for c in bgc), out

    def _datauri(im):
        # PNG 保真优先，超 10MB 退 JPEG q95（接口 base64 上限）
        for fmt, kw, im2 in (('PNG', {}, im), ('JPEG', {'quality': 95}, im.convert('RGB'))):
            buf = io.BytesIO()
            try:
                im2.save(buf, fmt, **kw)
            except Exception:
                continue
            data = buf.getvalue()
            if len(data) <= 10 * 1024 * 1024:
                return 'data:%s;base64,%s' % ('image/png' if fmt == 'PNG' else 'image/jpeg',
                                              base64.b64encode(data).decode('utf-8'))
        return None

    def _erase_text(rgb, texts):
        # qwen-image-3.0-pro 按 OCR 清单删字（照 pptpictrans 的实测结论：必须给具体清单，
        # 只说"删掉所有字"模型会把整页重画一遍）。任何失败返回 None，调用方落回本地平填。
        import dashscope
        from dashscope import MultiModalConversation as MMC
        dashscope.api_key = qwadvebvar.strip()
        dashscope.base_http_api_url = 'https://%s.cn-beijing.maas.aliyuncs.com/api/v1' % dashworkspaceidvar.strip()
        im = Image.fromarray(rgb)
        uri = _datauri(im)
        if uri is None:
            return None
        for i in range(0, len(texts), 12):
            ch = texts[i:i + 12]
            prompt = ('把这张图里的以下文字全部删除：%s。要求：删除处用周围背景自然补全；'
                      '除这些文字外的一切(图形、照片、底色、线条、版式、图标、表格线)保持原样不变，'
                      '不要重绘整图、不要添加任何新文字或水印。' % '、'.join('"%s"' % t for t in ch))
            url = None
            for attempt in range(2):
                try:
                    resp = MMC.call(api_key=qwadvebvar.strip(), model='qwen-image-3.0-pro',
                                    messages=[{'role': 'user', 'content': [{'image': uri}, {'text': prompt}]}],
                                    result_format='message', stream=False, watermark=False,
                                    negative_prompt='版权, 商标, 敏感, 违规, 侵权',
                                    prompt_extend=False, timeout=600)
                except Exception as e:
                    _log('删字调用异常(第%d次)：%s' % (attempt + 1, e))
                    resp = None
                if getattr(resp, 'status_code', 0) == 200:
                    for c in (resp.output.choices[0].message.content or []):
                        if isinstance(c, dict) and c.get('image'):
                            url = c['image']
                            break
                if url:
                    break
                _log('删字未出图：%s - %s' % (getattr(resp, 'code', ''), getattr(resp, 'message', '')))
                time.sleep(8 * (attempt + 1))
            if not url:
                return None
            r = requests.get(url, timeout=300)
            r.raise_for_status()
            out = Image.open(io.BytesIO(r.content))
            if out.size != im.size:
                out = out.resize(im.size, Image.LANCZOS)
            im = out.convert('RGB')
            uri = _datauri(im)
            if uri is None:
                return None
        return np.array(im)

    def _flat_fill(rgb, styles):
        # 本地兜底擦字：每行墨迹(胀3px)用该行外圈底色平填；整页坐标上胀，免得出界留残边
        cleaned = rgb.copy()
        H, W = rgb.shape[:2]
        for st in styles:
            ox, oy, ink = st['ink']
            m = np.zeros((H, W), bool)
            m[oy:oy + ink.shape[0], ox:ox + ink.shape[1]] = ink
            cleaned[_dilate(m, 7)] = st['bg']
        return cleaned

    def _emof(c):
        # 单个字符的自然advance宽(单位em)：CJK/全角1.0，空格0.26，半角0.52，其余0.5
        if u'一' <= c <= u'鿿' or u'　' <= c <= u'〿' or u'＀' <= c <= u'￯':
            return 1.0
        if c == ' ':
            return 0.26
        if ord(c) < 128:
            return 0.52
        return 0.5

    def _group(lines):
        lines.sort(key=lambda L: (L['top'], L['left']))
        blocks = []
        for L in lines:
            done = False
            if blocks:
                b = blocks[-1]
                last = b['lines'][-1]
                gap = L['top'] - (last['top'] + last['ih'])
                same = (L['fam'] == last['fam'] and L['bold'] == last['bold']
                        and abs(L['F'] - last['F']) <= max(1.5, 0.10 * last['F'])
                        and sum((a - c) ** 2 for a, c in zip(L['color'], last['color'])) ** 0.5 < 60)
                align = (abs(L['left'] - last['left']) <= 0.5 * last['ih']
                         or abs((L['left'] + L['iw'] / 2.0) - (last['left'] + last['iw'] / 2.0)) <= 0.5 * last['ih'])
                if same and align and -0.2 * last['ih'] <= gap <= 0.9 * last['ih']:
                    b['lines'].append(L)
                    done = True
            if not done:
                blocks.append({'lines': [L]})
        for b in blocks:
            ls = b['lines']
            b['left'] = min(L['left'] for L in ls)
            top = min(L['topbox'] for L in ls)
            bottom = max(L['top'] + L['ih'] for L in ls)
            b['top'], b['h'] = top, bottom - top + 0.3 * ls[0]['F']
            b['w'] = max(L['left'] + L['iw'] for L in ls) - b['left'] + 0.2 * ls[0]['F']
            b['pitch'] = (sum(ls[i + 1]['top'] - ls[i]['top'] for i in range(len(ls) - 1)) / (len(ls) - 1)
                          if len(ls) > 1 else 0)
        return blocks

    def _export_pages(path, W, H, tmp):
        if render_fn is not None:
            return render_fn(path, W, H)
        pythoncom.CoInitialize()
        app = win32com.client.Dispatch('PowerPoint.Application')
        app.Visible = True
        pres = app.Presentations.Open(path, True, False, False)
        pngs = []
        try:
            for i in range(1, pres.Slides.Count + 1):
                p = os.path.join(tmp, 'page%03d.png' % i)
                pres.Slides(i).Export(p, 'PNG', W, H)
                with open(p, 'rb') as f:
                    pngs.append(f.read())
        finally:
            pres.Close()
            app.Quit()
            pythoncom.CoUninitialize()
        return pngs

    def _run(srcpath, outpath, um=True):
        t0 = time.time()
        ok, why, npage = _check_pic_pptx(srcpath)
        if not ok:
            _log('不转：' + why)
            return None
        prs0 = PptxPres(srcpath)
        sw, sh = int(prs0.slide_width), int(prs0.slide_height)
        W, H = int(round(sw / 914400.0 * DPI)), int(round(sh / 914400.0 * DPI))
        _log('共 %d 页，每页导出 %dx%d' % (npage, W, H))
        _prog(5)
        tmp = tempfile.mkdtemp(prefix='imgppt2wenz_')
        try:
            pages = []
            npic = nblk = nchr = 0
            for idx, png in enumerate(_export_pages(srcpath, W, H, tmp)):
                rgb = np.array(Image.open(io.BytesIO(png)).convert('RGB'))
                lines = _ocr(png)
                styles = []
                for (text, x, y, w, h) in lines:
                    if not text.strip():
                        continue
                    st = _line_style(rgb, text, x, y, w, h)
                    if st is None:
                        continue
                    st['text'] = text
                    styles.append(st)
                texts = [L['text'] for L in styles]
                cleaned = None
                if um and texts:
                    _log('第%d页：qwen-image-3.0-pro 删%d条字' % (idx + 1, len(texts)))
                    try:
                        cleaned = _erase_text(rgb, texts)
                    except Exception as e:
                        _log('第%d页删字异常，改本地平填：%s' % (idx + 1, e))
                        cleaned = None
                    if cleaned is None:
                        _log('第%d页：模型删字没成，落回本地平填' % (idx + 1))
                if cleaned is None:
                    cleaned = _flat_fill(rgb, styles)
                bgc, pieces = _pieces(cleaned)
                pics = []
                for pi, (rgba, px, py) in enumerate(pieces):
                    pp = os.path.join(tmp, 'p%03d_%03d.png' % (idx, pi))
                    Image.fromarray(rgba, 'RGBA').save(pp)
                    pics.append((pp, px, py, rgba.shape[1], rgba.shape[0]))
                blocks = _group(styles)
                pages.append({'bg': bgc, 'pics': pics, 'blocks': blocks})
                npic += len(pics)
                nblk += len(blocks)
                nchr += sum(len(L['text']) for b in blocks for L in b['lines'])
                _log('第%d页：文字块%d 图片%d 底色%s' % (idx + 1, len(blocks), len(pics), str(bgc)))
                _prog(5 + int((idx + 1) * 70.0 / npage))
            prs = PptxPres()
            prs.slide_width, prs.slide_height = PEmu(sw), PEmu(sh)
            ex, ey = sw / float(W), sh / float(H)
            for pg in pages:
                slide = prs.slides.add_slide(prs.slide_layouts[6])
                slide.background.fill.solid()
                slide.background.fill.fore_color.rgb = PRGB(*pg['bg'])
                for (pp, px, py, pw, ph) in pg['pics']:
                    slide.shapes.add_picture(pp, PEmu(int(px * ex)), PEmu(int(py * ey)),
                                             PEmu(int(pw * ex)), PEmu(int(ph * ey)))
                for b in pg['blocks']:
                    tb = slide.shapes.add_textbox(PEmu(int(b['left'] * ex)), PEmu(int(b['top'] * ey)),
                                                  PEmu(int(b['w'] * ex)), PEmu(int(b['h'] * ey)))
                    tf = tb.text_frame
                    tf.word_wrap = False
                    tf.margin_left = tf.margin_right = tf.margin_top = tf.margin_bottom = 0
                    tf.vertical_anchor = PAnchor.TOP
                    for li, L in enumerate(b['lines']):
                        p = tf.paragraphs[0] if li == 0 else tf.add_paragraph()
                        p.space_before, p.space_after = PPt(0), PPt(0)
                        if b['pitch'] and li < len(b['lines']) - 1:
                            p.line_spacing = PEmu(int(b['pitch'] * ey))
                        r = p.add_run()
                        r.text = L['text']
                        r.font.size = PPt(round(L['F'] * 2) / 2.0)
                        r.font.bold = bool(L['bold'])
                        r.font.name = L['fam']
                        r.font.color.rgb = PRGB(*L['color'])
                        rPr = r._r.get_or_add_rPr()
                        rPr.append(rPr.makeelement(pqn('a:ea'), {'typeface': L['fam']}))
                        # 原图字形偏瘦高(condensed)时用字距spc补宽度：高度不变、不溢出原文字区
                        em = sum(_emof(c) for c in L['text'])
                        nat = em * L['F'] * 2.8333
                        if em > 0 and abs(nat - L['iw']) > 0.04 * L['iw']:
                            spc = int(round((L['iw'] - nat) / 2.8333 / len(L['text']) * 100))
                            spc = max(-int(L['F'] * 50), min(int(L['F'] * 50), spc))
                            rPr.set('spc', str(spc))
            _prog(85)
            prs.save(outpath)
        finally:
            shutil.rmtree(tmp, ignore_errors=True)
        _prog(100)
        _log('完成：%s 页 / 图片%d张 / 文字块%d个 / %d字 -> %s  用时%.1f秒'
             % (npage, npic, nblk, nchr, outpath, time.time() - t0))
        return {'pages': npage, 'pics': npic, 'blocks': nblk, 'chars': nchr, 'out': outpath}

    def _pick(entry, outentry, is_src):
        if is_src:
            p = askopenfilename(filetypes=[('pptx files', '.pptx')])
            if p:
                entry.delete(0, 'end')
                entry.insert(0, p)
                outentry.delete(0, 'end')
                outentry.insert(0, p[:-5] + '_图文并茂.pptx')
        else:
            p = asksaveasfilename(defaultextension='.pptx', filetypes=[('pptx files', '.pptx')])
            if p:
                entry.delete(0, 'end')
                entry.insert(0, p)

    def _start(s, o, um):
        if not s or not os.path.isfile(s):
            showinfo('Info', '请先选一个源pptx文件')
            return
        if not o:
            o = s[:-5] + '_图文并茂.pptx'
        _busy(True)
        def _th():
            try:
                res = _run(s, o, um)
            except Exception:
                _log('转换出错：' + traceback.format_exc())
                res = None
            def _fin():
                _busy(False)
                if res:
                    showinfo('完成', '已生成图文并茂pptx：\n%s\n共%d页 图片%d张 文字块%d个'
                             % (res['out'], res['pages'], res['pics'], res['blocks']))
            ui['pb'].after(0, _fin)
        Thread(target=_th).start()

    if src is None:
        win = Toplevel(root)
        win.title('图片pptx转图文并茂pptx')
        frm = ttk.Frame(win)
        frm.pack(fill='both', expand=True, padx=8, pady=8)
        ttk.Label(frm, text='源pptx(每页纯图片):').grid(row=0, column=0, sticky='w')
        e1 = ttk.Entry(frm, width=70)
        e1.grid(row=0, column=1, sticky='we', padx=4)
        ttk.Button(frm, text='浏览', command=lambda: _pick(e1, e2, True)).grid(row=0, column=2)
        ttk.Label(frm, text='输出pptx:').grid(row=1, column=0, sticky='w')
        e2 = ttk.Entry(frm, width=70)
        e2.grid(row=1, column=1, sticky='we', padx=4)
        ttk.Button(frm, text='另存为', command=lambda: _pick(e2, e2, False)).grid(row=1, column=2)
        usemodel = tk.BooleanVar(value=True)
        ttk.Checkbutton(frm, text='擦字用qwen-image-3.0-pro(不勾或失败时按周围底色本地平填)',
                        variable=usemodel).grid(row=2, column=0, columnspan=3, sticky='w', pady=2)
        ui['pb'] = ttk.Progressbar(frm, length=620, maximum=100)
        ui['pb'].grid(row=3, column=0, columnspan=3, sticky='we', pady=6)
        ui['logw'] = tk.Text(frm, width=95, height=12, state='disabled')
        ui['logw'].grid(row=4, column=0, columnspan=3, sticky='nsew')
        frm.rowconfigure(4, weight=1)
        frm.columnconfigure(1, weight=1)
        bar = ttk.Frame(win)
        bar.pack(side='bottom', fill='x', padx=8, pady=6)
        b1 = ttk.Button(bar, text='开始转换',
                        command=lambda: _start(e1.get().strip(), e2.get().strip(), usemodel.get()))
        b1.pack(side='left')
        b2 = ttk.Button(bar, text='关闭', command=win.destroy)
        b2.pack(side='left', padx=8)
        ui['btns'] = [b1]
        win.update_idletasks()
        ww = min(win.winfo_reqwidth() + 20, win.winfo_screenwidth() - 40)
        wh = min(win.winfo_reqheight() + 20, win.winfo_screenheight() - 80)
        win.geometry('%dx%d' % (ww, wh))
        return win

    if not out:
        out = src[:-5] + '_图文并茂.pptx'
    return _run(src, out, use_model)

