def plwjjfenlei3():
    showinfo('提示',
             '去选择一个文件夹，把它里边头三个字符相同的文件名放到一起，移到子目录，子目录名称就是那些相同前缀字符.')

    def select_folderqz():
        # 弹出对话框让用户选择一个文件夹
        folder_selected = askdirectory()
        if folder_selected:
            process_folderqz(folder_selected)

    def process_folderqz(folder_path):
        # 遍历文件夹中的所有文件
        for filename in os.listdir(folder_path):
            if os.path.isfile(os.path.join(folder_path, filename)):
                # 获取文件名的前三个字符
                prefix = filename[:3].replace('-', '')
                # 构建目标子目录的路径
                subdir_path = os.path.join(folder_path, prefix)
                # 如果子目录不存在，则创建它
                if not os.path.exists(subdir_path):
                    os.makedirs(subdir_path)
                # 将文件移动到相应的子目录
                src_path = os.path.join(folder_path, filename)
                dst_path = os.path.join(subdir_path, filename)
                shutil.move(src_path, dst_path)

                print(f"Moved {src_path} to {dst_path}")
    select_folderqz()

def plwjjfenlei2():
    showinfo('提示',
             '去选择一个文件夹，把它里边带有‘-’符号的文件名最左边作为前缀，前缀相同的放到一起，移到子目录，子目录名称就是那些相同前缀.')

    def organize_filesyd(directory):
        # 存储文件名前缀和对应文件列表的字典
        prefix_dict = {}

        # 遍历目录中的所有文件
        for filename in os.listdir(directory):
            # 假设文件名包含'-'，并且我们想基于'-'左边的部分来组织文件
            if '-' in filename:
                prefix = filename.split('-', 1)[0]  # 提取'-'左边的部分作为前缀
                if prefix not in prefix_dict:
                    prefix_dict[prefix] = []
                prefix_dict[prefix].append(filename)

        # 创建子目录并移动文件
        for prefix, files in prefix_dict.items():
            subdir_path = os.path.join(directory, prefix)
            if not os.path.exists(subdir_path):
                os.makedirs(subdir_path)
            for file in files:
                src_path = os.path.join(directory, file)
                dst_path = os.path.join(subdir_path, file)
                shutil.move(src_path, dst_path)

    def qzxtydmain():
        # 让用户选择目录
        directory = askdirectory()
        # 组织文件
        if directory:
            organize_filesyd(directory)
    qzxtydmain()

def plwjjfenlei():
    showinfo('提示', '去选择一个文件夹，把它里边的文件名相同但是扩展名不同的文件放到一起，移到子目录，子目录名称就是那些相同文件名.')
    def organize_files(directory):

        # 遍历目录中的所有文件
        for filename in os.listdir(directory):
            # 获取文件名（不包括扩展名）
            base_name, ext = os.path.splitext(filename)
            # 构建目标子目录的路径
            target_dir = os.path.join(directory, base_name)
            # 如果目标子目录不存在，则创建它
            if not os.path.exists(target_dir):
                os.makedirs(target_dir)
            # 完整的文件路径
            full_path = os.path.join(directory, filename)
            # 如果文件不是目录，移动到相应的子目录中
            if os.path.isfile(full_path):
                shutil.move(full_path, os.path.join(target_dir, filename))
        print("文件整理完成。")

    # 使用tkinter来选择目录
    directory = askdirectory(title="选择目录")
    if directory:
        organize_files(directory)

def plwjjjieyaw10():#wenjianjia jieya w10
    import shutil
    import zipfile
    showinfo('提示', '去选择一个文件夹，把它里边的win10产生的zip压缩包各自解压..')
    parent_path =  askdirectory() + '/'
    file_flag = '.zip'
    def del_old_zip(file_path):
        os.remove(file_path)
    def decompress(file_path, root, encoding='GBK'):
        with zipfile.ZipFile(file_path, 'r') as zip_ref:
            for zip_info in zip_ref.infolist():
                try: # win10 bandizip std
                    zip_info.filename = zip_info.filename.encode('cp437').decode(encoding)
                except:

                    # ljb old std zipzip 老标准
                    zip_info.filename = zip_info.filename.encode('gbk').decode(encoding)

                # 解压文件
                zip_ref.extract(zip_info, root)
    def start_dir_make(root, dirname):
        os.chdir(root)
        os.mkdir(dirname)
        return os.path.join(root, dirname)
    def rem_dir_extra(root, father_dir_name):
        try:
            for item in os.listdir(os.path.join(root, father_dir_name)):
                if not os.path.isdir(os.path.join(root, father_dir_name, item)):
                    continue
                if item == father_dir_name and len(
                        os.listdir(os.path.join(root, father_dir_name))) == 1:
                    os.chdir(root)
                    os.rename(father_dir_name, father_dir_name + '-old')
                    shutil.move(os.path.join(root, father_dir_name + '-old', item), os.path.join(root))
                    os.rmdir(os.path.join(root, father_dir_name + '-old'))
                    rem_dir_extra(root, item)
                else:
                    rem_dir_extra(os.path.join(root, father_dir_name), item)
        except Exception as e:
            print("清除文件夹出错" + str(e))
    flag = 1
    while flag:
        for root, dirs, files in os.walk(parent_path):
            for name in files:
                if name.endswith(file_flag):
                    new_ws = start_dir_make(root, name.replace(file_flag, ''))
                    zip_path = os.path.join(root, name)
                    flag = decompress(zip_path, new_ws)
                    del_old_zip(zip_path)
                    rem_dir_extra(root, name.replace(file_flag, ''))
                    print(f'{root}\\{name}'.join(['文件：', '\n解压完成\n']))
        rem_dir_extra(os.path.split(parent_path)[0], os.path.split(parent_path)[1])
        print("解压完成啦，")
    showinfo('提示', '批量解压缩任务完成.')

def pljpg22pdf():
    top5jpg2pdf = Toplevel()
    top5jpg2pdf.title("每个jpg分别转为PDF.")
    def main():
        def all_files_path1(df_path):
            filepaths = {}
            for root, dirs, files in os.walk(df_path):
                for file in files:
                    file_path = os.path.join(root, file)
                    a, b = os.path.split(file_path)
                    # a, b = os.path.split(a)
                    if file_path[-4:].lower() == '.jpg':
                        filepaths.setdefault(a, []).append(file_path)
                for dir in dirs:
                    dir_path = os.path.join(root, dir)
                    all_files_path1(dir_path)
            return filepaths

        def yes(pdf_name1, new_pic):
            doc = fitz.open()
            print(new_pic)
            new_pic.sort(key=lambda char: lazy_pinyin(char)[0][0])
            print(new_pic)
            # 循环path中的文件，可import os 然后用 for img in os.listdir(img_path)实现
            # 这里为了让文件以1，2，3的形式进行拼接，就偷懒循环文件名中的数字。
            ii = 1
            for img_file in new_pic:
                # img_file = os.path.join(img_path, i)
                print(img_file)
                if img_file[-3:].lower() == 'jpg':
                    imgdoc = fitz.open(img_file)  # 打开照片路径
                    pdfbytes = imgdoc.convertToPDF()
                    pdf_name = os.path.join(pdf_name1, '%s.pdf' % ii)
                    imgpdf = fitz.open(pdf_name, pdfbytes)
                    doc.insertPDF(imgpdf)
                    ii += 1
            doc.save(pdf_name1)
            doc.close()

        def file_name2(df_path, path_bc):
            try:
                # textEdit_jpg_pdf.append('开始转换PDF')
                list_folder = all_files_path1(df_path)

                jd_pl = 100 / len(list_folder)
                jd = 100 / len(list_folder)
                for path_folder in list_folder:
                    path_bc_pdf = path_folder.replace(df_path, path_bc)
                    if not os.path.exists(path_bc_pdf):
                        os.mkdir(path_bc_pdf)
                    for path_jpg in list_folder[path_folder]:
                        try:
                            list_jpg = []
                            list_jpg.append(path_jpg)
                            a, b = os.path.split(path_jpg)
                            a, b = os.path.splitext(b)
                            path_pdf = os.path.join(path_bc_pdf, '%s.pdf' % a)
                            yes(path_pdf, list_jpg)
                        except:
                            pass

                    jd = jd + jd_pl
                    os.startfile(path_bc)
            except:
                pass

        parent_path = askdirectory() + '/'
        list_folder = parent_path
        file_name2(parent_path, parent_path)
