cfuck = wmi.WMI()
def addpcinfo():
    global list
    list = []

    def info():
        list.append("电脑硬件信息")
        list.append("\n")

        #网络接口信息
        for interface in cfuck.Win32_NetworkAdapterConfiguration(IPEnabled=1):
            macaddr = interface.MACAddress
            for ip_addr in interface.IPAddress:
                print(ip_addr)  # 保留原来的打印

        #操作系统信息
        for os in cfuck.Win32_OperatingSystem():
            list.append("**操作系统版本: %s" % os.Caption.replace('Microsoft Windows', 'Windows'))
            list.append("**操作系统版本号: %s" % os.Version)
            list.append("\n")

        #计算机系统信息
        for system in cfuck.Win32_ComputerSystem():
            list.append("**主机名: %s" % system.Caption)
            list.append("**用户名: %s" % system.UserName)
            # 域或工作组信息
            if system.DomainRole == 0:
                domain_workgroup = "组=%s" % system.Domain
            elif system.DomainRole == 1:
                domain_workgroup = "域=%s" % system.Domain
            else:
                domain_workgroup = "域=%s" % system.Domain
            list.append("**加入的域或工作组: %s" % domain_workgroup)
            list.append("\n")

        #BIOS信息
        for bios in cfuck.Win32_BIOS():
            list.append("**Bios描述: %s" % bios.Description)
            list.append("**序列号: %s" % bios.SerialNumber)
            list.append("\n")

        # CPU信息
        for processor in cfuck.Win32_Processor():
            list.append("**CPU型号: %s" % processor.Name.strip())
            list.append("**CPU内核: %s 个" % processor.NumberOfCores)
            list.append("**CPU基准频率: %s GHz" % (processor.MaxClockSpeed / 1000))
            list.append("\n")

        # 内存信息
        for memmodule in cfuck.Win32_PhysicalMemory():
            totalmemsize = int(memmodule.Capacity)
            list.append(
                "**内存厂商: %s" % memmodule.Manufacturer.replace('80AD000080AD', '海力士').replace('04CB', '威刚ADATA').replace('04C3', '威刚2ADATA').replace('029E', '三星Samsung').replace('04E8', '三星Samsung2').replace('04CD', '金士顿Kingston').replace('04D6', '金士顿2Kingston').replace('04E0', '金士顿3Kingston').replace('2C00', '美光Micron').replace('04A4', '英睿达Crucial美光子品牌').replace('014F', '东芝Toshiba').replace('04F0', '东芝2Toshiba2Kioxia').replace('04AC', '联想Lenovo').replace('08C8', 'Lenovo3thinkplus联想').replace('04B3', '东芝Toshiba3Kioxia').replace('04BA', 'SanDisk').replace('0425', '海康威视Hikvision').replace('80CE', 'SK_hynix海力士2').replace('8934', '长江存储').replace('8551', '铠侠').replace('048D', '光威Gloway'),)
            list.append("**内存型号: %s" % memmodule.PartNumber)
            list.append("**内存大小: %.2fGB" % (totalmemsize / 1024 ** 3))
            list.append("\n")
            try:
                list.append("**内存频率: %s MHz" % memmodule.ConfiguredClockSpeed)
                list.append("\n")
            except:
                print('mem output error')

        # 显卡信息
        for xk in cfuck.Win32_VideoController():
            list.append("**显卡名称: %s" % xk.name)
            list.append("\n")

        # 声卡信息
        for snk in cfuck.Win32_SoundDevice():
            list.append("**声卡名称: %s" % snk.name)
            list.append("\n")

        # 磁盘信息 - 统一处理各种接口类型
        disk_interfaces = ["IDE", "SCSI", "HDC", "1394"]
        for interface_type in disk_interfaces:
            for disk in cfuck.Win32_DiskDrive(InterfaceType=interface_type):
                diskSize = int(disk.size)
                list.append("**磁盘名称: %s" % disk.Caption)
                list.append("\n")
                list.append("**磁盘大小: %.2fGB" % (diskSize / 1024 ** 3))
                list.append("\n")
                list.append("**磁盘序列号: %s" % disk.SerialNumber.strip() if disk.SerialNumber else "未知")
                list.append("\n")
                list.append("**驱动器类型: %s" % disk.InterfaceType)
                list.append("\n")

        # 网络配置信息
        for interface in cfuck.Win32_NetworkAdapterConfiguration(IPEnabled=1):
            if interface.IPAddress:
                list.append("**当前IP地址: %s" % interface.IPAddress[0])
            if interface.MACAddress:
                list.append("**当前MAC地址: %s" % interface.MACAddress)
            if interface.DefaultIPGateway:
                list.append("**网关: %s" % interface.DefaultIPGateway[0])
            if interface.DNSDomain:
                list.append("**DNS域: %s" % interface.DNSDomain)
            if interface.DNSServerSearchOrder:
                dns_servers = ', '.join(interface.DNSServerSearchOrder)
                list.append("**DNS服务器: %s" % dns_servers)
            list.append("\n")

    info()
    textPad.insert('end', '\n'.join(list))
    textPad3fanyi.insert('end', textPad.get("1.0", 'end'))
    newpcinfo = textPad3fanyi.get("1.0", 'end').replace("} {", '\n').replace('\n\n\n', '\n').replace('}\n', '').replace(
        '**主 机 名', '**主机名').replace('**用 户 名', '**用户名').replace(' MHz', 'MHz').replace(' GHz',
                                                                                                   'GHz').replace(
        '电脑硬件信息 {\n\n', '')
    textPad.delete("1.0", 'end')
    textPad.insert("1.0", newpcinfo)
    textPad3fanyi.delete("1.0", 'end')

