from string import *
def artzishu(): #字数统计
    zishuget=len(textPad.get('1.0', END))-1
    letter = 0
    number = 0
    space = 0
    symbol = 0
    enterj =0
    s = textPad.get('1.0', END)
    for char in s:
        if 'a' <= char <= 'z' or 'A' <= char <= 'Z':
            letter += 1
        elif char.isdigit():
            number += 1
        elif char in [' ', ' ']:
            space += 1
        elif char=='\n':
            enterj+= 1
        else:
            symbol += 1
    # tempTuple = (symbol,letter, number, space)
    tempTuple1 = (symbol)
    tempTuple2 = (letter, space,  number)
    x = textPad.get('1.0', END)
    def count_english_words(text):
        words = re.findall(r"[a-zA-Z]+(?:'[a-zA-Z]+)?", text)
        return len(words)
    countfor=count_english_words(x)
    showinfo('统计字数',  "中文和标点字符数量为：%d\n"%tempTuple1 + '文编区总字符数量为：%d\n英语单词数量为：%d\n'%(zishuget,countfor)+"字母数量为：%d\n空格数量为：%d\n数字数量为：%d"%tempTuple2 )

