def hengshutpfl():
    pass
    hstpdirectory = askdirectory()
    if not hstpdirectory:
        return  # 如果用户取消了选择，则退出函数

    # 定义存放结果的两个子文件夹路径
    landscape_heng_folder = os.path.join(hstpdirectory, 'landscape_heng')
    portrait_shu_folder = os.path.join(hstpdirectory, 'portrait_shu')

    # 确保这两个文件夹存在
    os.makedirs(landscape_heng_folder, exist_ok=True)
    os.makedirs(portrait_shu_folder, exist_ok=True)

    # 遍历选定目录下的所有文件
    for filename in os.listdir(hstpdirectory):
        filepath = os.path.join(hstpdirectory, filename)

        try:
            with Image.open(filepath) as img:
                width, height = img.size
                # 判断图片是横图还是竖图
                if width > height:
                    target_folder = landscape_heng_folder
                else:
                    target_folder = portrait_shu_folder

                # 移动图片到对应的文件夹
                shutil.move(filepath, os.path.join(target_folder, filename))
        except Exception as e:
            print(f"处理文件 {filename} 时发生错误: {e}")

    # 显示完成消息
    showinfo("完成", "分类完毕，子目录 landscape_heng 和 portrait_shu分别存放横向和竖向图片！")
def yasuopltp():  #批量压缩图片
    top3ystp = Toplevel()
    top3ystp.title("批量压缩JPG图片")
    #function
    def get_size(file):
        # 获取文件大小:KB
        size = os.path.getsize(file)
        return size / 1024
    # 压缩文件到指定大小，我期望的是150KB,step和quality可以修改到最合适的数值  # 修改图片尺寸，如果同时有修改尺寸和大小的需要，可以先修改尺寸，再压缩大小
    def savesize():
        mb2 = ystpt1.get(0.0, 'end')
        # global mysize2
        mysize2var = mb2.replace('\n', '')

        with open("sizejpg.txt", "w") as wantfile:
            wantfile.writelines(mysize2var)
    def savekuan():
        kuan2 = ystpt2.get(0.0, 'end')
        # global mykuan2
        mykuan2var = kuan2.replace('\n', '')
        with open("kuanjpg.txt", "w") as wantfile:
            wantfile.writelines(mykuan2var)
    def savegao():
        gao2 = ystpt1gao.get(0.0, 'end')
        # global mykuan2
        mygao2var = gao2.replace('\n', '')
        with open("gaojpg.txt", "w") as wantfile:
            wantfile.writelines(mygao2var)
    def readsize():
        with open("sizejpg.txt", "r") as want2file:
            mysize = want2file.readline()
            global mysize2
            mysize2 = int(str(mysize))

    def readkuan():
        with open("kuanjpg.txt", "r") as kuanfile:
            mykuan = kuanfile.readline()
            global mykuan2
            mykuan2 = int(str(mykuan))
    def readgao():
        with open("gaojpg.txt", "r") as gaofile:
            mygao = gaofile.readline()
            global mygao2
            mygao2 = int(str(mygao))
    def compress_image(infile, outfile='', mb=3500, step=10, quality=80):
        """不改变图片尺寸压缩到指定大小
        :param infile: 压缩源文件
        :param outfile: 压缩文件保存地址
        :param mb: 压缩目标，KB
        :param step: 每次调整的压缩比率
        :param quality: 初始压缩比率
        :return: 压缩文件地址，压缩文件大小
        """
        o_size = get_size(infile)

        readsize()
        mb = mysize2
        print('mb%s' % mb)
        if o_size <= mb:
            return infile
        outfile = output_filename3
        while o_size > mb:
            im = Image.open(infile)
            im.save(outfile, quality=quality)
            if quality - step < 0:
                break
            quality -= step
            o_size = get_size(outfile)
        return outfile, get_size(outfile)
    def resize_image(infile, outfile='', x_s=1376):
        """修改图片尺寸
        :param infile: 图片源文件
        :param outfile: 重设尺寸文件保存地址
        :param x_s: 设置的宽度
        :return:
        """
        readkuan()
        x_s = mykuan2
        im = Image.open(infile)
        x, y = im.size
        y_s = int(y * x_s / x)
        out = im.resize((x_s, y_s), Image.ANTIALIAS)
        outfile = output_filename4
        out.save(outfile)
    def resize_image2(infile, outfile='', x_s=1376):
        """修改图片尺寸
        :param infile: 图片源文件
        :param outfile: 重设尺寸文件保存地址
        :param x_s: 设置的宽度
        :return:
        """
        readkuan()
        readgao()
        x_s = mykuan2
        im = Image.open(infile)
        x, y = im.size
        y_s = mygao2
        out = im.resize((x_s, y_s), Image.ANTIALIAS)
        outfile = output_filename4
        out.save(outfile)

    def yasuopl():

        global workwhereyasuonew
        workwhereyasuonew = askdirectory(title='选择图片位置') + '/'
