        def wyunzipafilemuluw10(self):
            def decompress(file_path, root, encoding='gbk'):
                with zipfile.ZipFile(file_path, 'r') as zip_ref:
                    for zip_info in zip_ref.infolist():
                        try:# win10 bandizip std
                            zip_info.filename = zip_info.filename.encode('cp437').decode(encoding)
                        except:
                            # ljb old std zipzip 老标准
                            zip_info.filename = zip_info.filename.encode('gbk').decode(encoding)

                        zip_ref.extract(zip_info, root)
            selected_index2cpzp = self.file_listbox.curselection()
            if not selected_index2cpzp:
                showwarning("警告", "请选择要解压的文件！")
                return
            filenameoldcpfzp = self.file_listbox.get(selected_index2cpzp)
            full_patholdcpfzp = os.path.join(self.current_path, filenameoldcpfzp)
            if os.path.isfile(full_patholdcpfzp):
                outfilenamecp2zp = askdirectory() + '/'

                def runingpb2():
                    for i in range(100):
                        self.progress_bar['value'] = i + 50
                        top2f.update()
                        time.sleep(0.005)

                if outfilenamecp2zp:
                    runingpb2()
                    try:

                        decompress(full_patholdcpfzp, outfilenamecp2zp, encoding='gbk')
                        self.progress_bar.stop()
                        self.progress_bar["value"] = 100
                        showinfo("成功", "解压完毕")
                        self.update_file_list(self.current_path)
                    except Exception as e:
                        self.progress_bar.stop()
                        showerror("错误", f"解压错误: {str(e)}")

            else:
                showerror("错误", " 解压错误")
