import pyperclip
def myclip():
    # showinfo('notice','发件历史区开始累加剪贴板文字内容.')
    # from threading import Thread, Lock
    # import pythoncom
    # lockclip = Lock()
    def myclipsub():
        clipboard_content = pyperclip.paste()   # 打印剪切板的内容  # print("剪切板内容:", clipboard_content)
        if clipboard_content not in textPad2mail_log.get(0.0,'end'):

            textPad2mail_log.insert('end', clipboard_content+'\n')
            textPad2mail_log.insert('end', '-----\n')
        # time.sleep(2)
    def fun_timerclip():
        print('Hello clip!')
        myclipsub()
        global timerclip
        timerclip = threading.Timer(5, fun_timerclip)
        timerclip.start()

    timerclip = threading.Timer(1, fun_timerclip)
    timerclip.start()#th9

def searchmaillog():
    try:
        notebook.select([11])
    except:
        pass
    textPad2mail_log.delete(1.0, END)
    #historytitle = getmvar5.get()
    conn = sqlite3.connect("mailoutlog.db")
    cursor = conn.cursor()
    sql = '''SELECT addr_out,title,mailcontent
            from mailoutlog'''
    results=cursor.execute(sql)
    allmaillogs=results.fetchall()
    for maillog in allmaillogs:
        textPad2mail_log.insert('end','收件人: '+ str(maillog).split(' ')[0].replace("('","").replace("'","").replace(",","")+'\n'+'标题: '+str(maillog).split(' ')[1].replace("('","").replace("'","").replace(",","")+'\n'+'内容: '+str(maillog).split(' ')[2].replace("('","").replace("'","").replace(",","").replace(r"\n)",""))
        textPad2mail_log.insert('end', '\n' + '*' * 88 + '\n')
    cursor.close()
    conn.close()

def searchmailtolog():
    textPad2mail_log.delete(1.0, END)
    historymailto = getmvar5.get()
    conn = sqlite3.connect("mailoutlog.db")
    cursor = conn.cursor()
    sql = '''SELECT addr_out,title,mailcontent
                from mailoutlog where addr_out=?'''
    values = cursor.execute(sql, (historymailto,))
    for i in values:
        print('id:', i[0])
        textPad2mail_log.insert('end', '收件人: '+i[0]+'\n')
        textPad2mail_log.insert('end','标题: '+ i[1]+'\n')
        textPad2mail_log.insert('end','内容: '+ i[2]+'\n')
        textPad2mail_log.insert('end', '\n' + '*' * 88 + '\n')
    cursor.close()
    conn.close()

#数据库模糊搜索邮件标题
def searchmailttlog():
    textPad2mail_log.delete(1.0, END)
    historymailtt = getmvar6bt.get()
    conn = sqlite3.connect("mailoutlog.db")
    cursor = conn.cursor()
    sql = '''SELECT addr_out,title,mailcontent
                from mailoutlog where title like ?'''
    values = cursor.execute(sql, ('%'+historymailtt+'%',))
    for itt in values:
            textPad2mail_log.insert('end', '收件人: '+itt[0]+'\n')
            textPad2mail_log.insert('end','标题: '+ itt[1]+'\n')
            textPad2mail_log.insert('end', '内容: '+itt[2]+'\n')
            textPad2mail_log.insert('end', '\n' + '*' * 88 + '\n')
    cursor.close()
    conn.close()

#樱花少女粉美化配色：只调整界面颜色与质感，完全不触碰任何按钮及其字体
def beautify_pink_ui():
    try:
        s = ttk.Style()
        sakura_bg = '#FFF5F7'     # 浅樱粉底色
        sakura_soft = '#FFDCE8'   # 柔粉
        sakura_edge = '#F7A8C4'   # 边框粉
        sakura_hot = '#E85D8A'    # 玫瑰粉点缀
        sakura_text = '#6E2B4F'   # 深梅紫文字
        sakura_sel = '#FFD3E2'    # 选中粉

        root.config(bg=sakura_bg)
        # 工具条、标签、菜单按钮
        s.configure('TFrame', background=sakura_bg)
        s.configure('TLabel', background=sakura_bg, foreground=sakura_text)
        s.configure('TMenubutton', background=sakura_soft, foreground=sakura_text, padding=(6, 3))
        s.configure('TLabelframe', background=sakura_bg)
        s.configure('TLabelframe.Label', background=sakura_bg, foreground=sakura_text)
        # 页签卡片
        s.configure('TNotebook', background=sakura_bg, borderwidth=1)
        s.configure('TNotebook.Tab', background=sakura_soft, foreground=sakura_text, padding=(14, 7))
        s.map('TNotebook.Tab',
              background=[('selected', '#FFFFFF')],
              foreground=[('selected', sakura_hot)],
              expand=[('selected', (0, 0, 0, 2))])
        # 输入框、下拉框、数字框
        s.configure('TEntry', fieldbackground='#FFFFFF', foreground=sakura_text, padding=3)
        s.configure('TCombobox', fieldbackground='#FFFFFF', foreground=sakura_text, arrowcolor=sakura_hot, padding=3)
        s.configure('TSpinbox', fieldbackground='#FFFFFF', foreground=sakura_text, arrowcolor=sakura_hot)
        root.option_add('*TCombobox*Listbox*Background', '#FFF7FA')
        root.option_add('*TCombobox*Listbox*Foreground', sakura_text)
        root.option_add('*TCombobox*Listbox*selectBackground', sakura_sel)
        root.option_add('*TCombobox*Listbox*selectForeground', sakura_hot)
        # 复选框、单选框
        s.configure('TCheckbutton', background=sakura_bg, foreground=sakura_text)
        s.map('TCheckbutton', background=[('active', sakura_soft)])
        s.configure('TRadiobutton', background=sakura_bg, foreground=sakura_text)
        s.map('TRadiobutton', background=[('active', sakura_soft)])
        # 进度条、滚动条
        s.configure('TProgressbar', background=sakura_hot, troughcolor=sakura_soft,
                    bordercolor=sakura_edge, lightcolor=sakura_hot, darkcolor=sakura_hot)
        s.configure('Vertical.TScrollbar', background=sakura_soft, troughcolor=sakura_bg, arrowcolor=sakura_hot)
        s.configure('Horizontal.TScrollbar', background=sakura_soft, troughcolor=sakura_bg, arrowcolor=sakura_hot)
        # 表格
        s.configure('Treeview', background='#FFF9FB', fieldbackground='#FFF9FB', foreground=sakura_text)
        s.configure('Treeview.Heading', background=sakura_soft, foreground=sakura_text)
        s.map('Treeview', background=[('selected', sakura_sel)], foreground=[('selected', sakura_hot)])
        # 文本编辑区
        textPad.config(bg='#FFF7FA', insertbackground=sakura_hot)
        textmyday.config(bg='#FFF7FA')
        # 菜单栏与各下拉菜单
        for mymenu in (menubar, filemenu, editmenu, toolmenu, playmenu, codemenu,
                       pdftlmenu, about, zhuti, menubutton_show.menu, weight["menu"]):
            try:
                mymenu.config(bg='#FFE9F1', fg=sakura_text,
                              activebackground=sakura_sel, activeforeground=sakura_hot)
            except Exception:
                pass
    except Exception:
        pass
