        top7rwjh = Toplevel()
        top7rwjh.title("任务提醒 (提早5分钟提示)")
        from datetime import datetime, timedelta
        events = []
        # 检查事件的线程函数
        def check_events():
            while True:
                current_time = datetime.now()
                for event in events[:]:  # 遍历事件列表
                    event_time = event['time']
                    reminder_time = event_time - timedelta(minutes=5)  # 提前5分钟提醒
                    if current_time >= reminder_time and current_time < event_time:  # 弹出提醒对话框
                        top7rwjh.after(0, lambda: showinfo("提醒", f"--> '{event['name']}' 即将开始，还有5分钟！"))
                        events.remove(event)  # 移除已经提醒过的事件
                time.sleep(0.05)  # 每分钟检查一次
        # 添加事件的函数
        def add_event():
            # top7rwjh.deiconify()
            notebook.select([6])
            rwjhname2 = entry_name.get().replace(' ', '_')
