    def hook_double_click():
        try:
            # 获取当前线程的所有窗口，寻找pystray创建的隐藏托盘窗口
            def enum_windows_callback(hwnd, lParam):
                class_name = win32gui.GetClassName(hwnd)
                # pystray在Windows下创建的窗口类名通常包含特定标识或为隐藏窗口
                # 更稳妥的方式是遍历所有托盘图标窗口
                if win32gui.IsWindowVisible(hwnd) == 0:
                    # 尝试发送消息或子类化，这里使用全局鼠标钩子或窗口子类化
                    pass
                return True

            taskbar = win32gui.FindWindow("Shell_TrayWnd", None)
            if taskbar:
                # 注意：直接Hook系统托盘可能影响其他软件，
                # 推荐使用 pystray 的 setup 回调结合 win32gui 子类化。
                pass
        except Exception as e:
            print(f"Hook双击事件失败: {e}")

    def custom_tray_with_double_click():
        hwnd = 0
        msg_taskbar_restart = win32gui.RegisterWindowMessage("TaskbarCreated")

        def wndproc(hwnd, msg, wparam, lparam):
            if msg == msg_taskbar_restart:
                # 重建托盘图标
                pass
            elif msg == win32con.WM_LBUTTONDBLCLK:
                # 双击左键事件
                root.after(0, root.deiconify)
                return 0
            elif msg == win32con.WM_RBUTTONUP:
                # 右键弹出菜单
                menu = win32gui.CreatePopupMenu()
                win32gui.AppendMenu(menu, win32con.MF_STRING, 1023, "显示老罗笔记")
                win32gui.AppendMenu(menu, win32con.MF_SEPARATOR, 0, "")
                win32gui.AppendMenu(menu, win32con.MF_STRING, 1024, "退出")
                pos = win32gui.GetCursorPos()
                win32gui.SetForegroundWindow(hwnd)
                win32gui.TrackPopupMenu(menu, win32con.TPM_LEFTALIGN, pos[0], pos[1], 0, hwnd, None)
                win32gui.PostMessage(hwnd, win32con.WM_NULL, 0, 0)
                return 0
            elif msg == win32con.WM_COMMAND:
                if wparam == 1023:
                    root.after(0, root.deiconify)
                elif wparam == 1024:
                    root.after(0, quit_app)
                return 0
            elif msg == win32con.WM_DESTROY:
                win32gui.PostQuitMessage(0)
                return 0
            return win32gui.DefWindowProc(hwnd, msg, wparam, lparam)
        wc = win32gui.WNDCLASS()
        wc.hInstance = hinst = win32gui.GetModuleHandle(None)
        wc.lpszClassName = "PythonTrayApp"
        wc.lpfnWndProc = wndproc
        class_atom = win32gui.RegisterClass(wc)
        hwnd = win32gui.CreateWindow(class_atom, "TrayApp", 0, 0, 0, 0, 0, 0, 0, hinst, None)
        win32gui.UpdateWindow(hwnd)

        # 修复：win32gui 需要图标句柄(HICON)，不能直接传入 PIL Image 对象
        # 这里加载项目中已有的 luo.ico 文件来获取图标句柄

        #隐藏段落点减少多余托盘图标
        # time.sleep(1.8)
        # hicon = win32gui.LoadImage(0, "luo.ico", win32con.IMAGE_ICON, 0, 0,
        #                            win32con.LR_LOADFROMFILE | win32con.LR_DEFAULTSIZE)

        # 创建托盘图标
        # nid = (hwnd, 0, win32gui.NIF_ICON | win32gui.NIF_MESSAGE | win32gui.NIF_TIP,
        #        win32con.WM_USER + 20, hicon, "<Rogabet>")

        try:
            nid = (hwnd, 0, win32gui.NIF_ICON | win32gui.NIF_MESSAGE | win32gui.NIF_TIP,
                   win32con.WM_USER + 20,  "<Rogabet>")
            win32gui.Shell_NotifyIcon(win32gui.NIM_ADD, nid)
        except:
            pass

        # 保持消息循环运行（在独立线程中）
        win32gui.PumpMessages()
    # 启动自定义托盘线程
    threading.Thread(target=custom_tray_with_double_click, daemon=True).start()

    #new end dbclk
