def dragged_files(files):
    myopenitem=''.join((item.decode('GBK') for item in files))
    indexdrag = myopenitem.rfind('.')
    myopenitemrightextname=myopenitem[indexdrag:]
    print(myopenitemrightextname)

    global filename
    filename = myopenitem
    if filename == '':
        filename = None
    else:
        root.title('老罗笔记人工智能文字处理软件 Rogabet notepad   ' + os.path.basename(filename))
        textPad.delete(1.0, END)
        f = open(filename, 'r')
        f2 = open(file=filename, mode='rb')
        import chardet
        bimabima = f2.read()
        resultbima = chardet.detect(bimabima)
        resultbima2 = str(resultbima)
        print(resultbima2)
        if '-8' in resultbima2:
            showinfo('编码', '此文件是UTF-8编码，即将使用转码打开.')
            print(resultbima2)
            oldfile2 = filename
            global newfile2
            # newfile2 = asksaveasfilename(initialfile='utf8-ansi编码.txt', defaultextension='.txt')
            fp_ansi = open('utf8_ansi.txt', 'wb')
            # 转码后输出的文件
            fp_utf8 = open(oldfile2, 'rb')
            # 待转码的文件
            data = ""
            data = fp_utf8.read()
            data = data.decode('utf-8')
            # 以二进制格式读入的数据需要先转码（转为内部码）才可以继续转换
            data = data.encode('mbcs', errors='ignore')
            # 关键，将内部码再次编码
            fp_ansi.write(data)
            # 写入文件
            fp_ansi.close()
            fp_utf8.close()
            f3 = open('utf8_ansi.txt', 'r')
            textPad.insert(1.0, f3.read())
            time.sleep(1)
            f3.close()
            time.sleep(2)

            os.remove('utf8_ansi.txt')
        if '-16' in resultbima2:
            showinfo('编码', '此文件是UTF-16-unicode编码，即将使用转码打开.')
            print(resultbima2)
            oldfile3 = filename
            global newfile3
            # newfile3 = asksaveasfilename(initialfile='unicode-ansi编码.txt', defaultextension='.txt')
            fp_ansi = open('unicode_ansi.txt', 'wb')
            # 转码后输出的文件
            fp_utf16 = open(oldfile3, 'rb')
            # 待转码的文件
            data = ""
            data = fp_utf16.read()
            data = data.decode('utf-16')
            # 以二进制格式读入的数据需要先转码（转为内部码）才可以继续转换
            data = data.encode('mbcs', errors='ignore')
            # 关键，将内部码再次编码
            fp_ansi.write(data)
            # 写入文件
            fp_ansi.close()
            fp_utf16.close()
            f3 = open('unicode_ansi.txt', 'r')
            textPad.insert(1.0, f3.read())
            time.sleep(1)
            f3.close()
            time.sleep(2)

            os.remove('unicode_ansi.txt')
        if myopenitemrightextname == '.pdf':
            # new()
            addpdffile = myopenitem
            with openpd(addpdffile) as pdf:
                numpages = len(pdf.pages)
                for i in range(0, numpages):
                    read_page = pdf.pages[i]
                    # print(read_page.extract_text())
                    textPad.insert('end', read_page.extract_text())
                    textPad.insert('end', '\n-----\n')
            showinfo('Info', '建议另存为note格式，避免破坏当前文件')
            # save2as()
            # myopen2()

            msg = textPad.get(1.0, 'end')
            outfilename = asksaveasfilename(title='选择保存note位置', initialfile='未命名.note',
                                            defaultextension='.note', filetypes=[('note files', '.note')])
            with gzip.open(outfilename, 'wb') as output:
                with io.TextIOWrapper(output, encoding='utf-8') as enc:
                    enc.write(msg)
            os.system('file -b --mime {}'.format(outfilename))
            root.title('Rogabet Notepad   ' + os.path.basename(outfilename))


        if myopenitemrightextname == '.docx':

            adddocxfile = myopenitem
            wdoc = docx.Document(adddocxfile)
            docxnumparas = len(wdoc.paragraphs)
            for i in range(0, docxnumparas):
                readdocx_para = wdoc.paragraphs[i].text
                textPad.insert('end', readdocx_para)
                textPad.insert('end', '\n')
            showinfo('Info', '建议另存为txt格式，避免破坏当前文件')

            # saveas()
            # myopen()
            f = asksaveasfilename(title='选择保存txt位置', initialfile='未命名.txt', defaultextension='.txt',
                                  filetypes=[('txt files', '.txt')])
            # global filename
            filename = f
            fh = open(f, 'w')
            msg = textPad.get(1.0, 'end').replace(u'\xa0', u'').replace(u'\u3000', u'').replace(u'\u200b',
                                                                                                u' ').replace(u'\xe4',
                                                                                                              u' ').replace(
                u'\xae', u' ').replace(u'\u2212', u' ').replace(u'\xa9', u' ').replace(u'\u2122', u' ').replace(
                u'\u2011', u' ').replace(u'\xb5', u' ').replace(u'\u2022', u' ').replace(u'\u2799', u' ').replace(
                u'\u2709', u' ')
            fh.write(msg)
            fh.close()
            root.title('Rogabet Notepad   ' + os.path.basename(f))
            # root.title('Rogabet Notepad   ' + os.path.basename(f))

        if myopenitemrightextname == '.note':
            loadnotefile = myopenitem
            root.title('老罗笔记人工智能文字处理软件 Rogabet notepad  ' + os.path.basename(loadnotefile))
            textPad.delete(1.0, END)

            with gzip.open(loadnotefile, 'rb') as input:
                with io.TextIOWrapper(input, encoding='utf-8') as dec:
                    content2 = dec.read()
                    textPad.insert(1.0, content2)
            # save2()
        try:
            if myopenitemrightextname == '.jpg'or'.jpeg'or'.bmp'or'.png'or '.JPG'or'.JPEG'or'.BMP'or'.PNG':
                # new()
                # 打开图片
                def get_file_content(filePath):
                    with open(filePath, 'rb') as fp:
                        return fp.read()

                # 通用文字识别（高精度版weizhi）

                def basicAccurate(file):
                    from aip import AipOcr
                    APP_ID = plocridvard
                    API_KEY = plocrakvard
                    SECRET_KEY = plocrskvard
                    aipOcr = AipOcr(APP_ID, API_KEY, SECRET_KEY)
                    options = {}
                    options["recognize_granularity"] = "small"
                    options["language_type"] = "CHN_ENG"
                    options["detect_direction"] = "true"
                    # 检测朝向
                    options["detect_language"] = "true"
                    # 检测语言
                    options["vertexes_location"] = "true"
                    options["probability"] = "true"
                    # result = aipOcr.basicAccurate(file, options)
                    result = aipOcr.accurate(file, options)
                    return (result)
                file = get_file_content(myopenitem)
                result = basicAccurate(file)
                # print(result)
                for word in result['words_result']:
                    print(word['words'])
                    gettext2 = word['words']
                    with open("png2txt.txt", "a") as rbfile:
                        rbfile.writelines(gettext2 + '\n')
                begin = datetime.now()
                while not os.path.exists('png2txt.txt'):
                    time.sleep(2)
                    end = datetime.now()
                    dur = end - begin
                    dur = dur.seconds
                    print(dur)
                    if dur == 44:
                        with open("png2txt.txt", "a") as rbfile:
                            rbfile.write('* \n')
                        showinfo('提示', '操作超时！')
                with open("png2txt.txt", "rt") as pngtxtfile:
                    png2txt = pngtxtfile.read()
                time.sleep(2)
                textPad.insert('end', png2txt)
                time.sleep(1)
                shutil.copy('png2txt.txt', 'png2txt-bkp.txt')
                os.remove("png2txt.txt")
                # showinfo('Info', '建议另存为txt格式，避免破坏当前文件')
                # saveas()
                # myopen()
                f='png2txt-bkp.txt'
                root.title('Rogabet Notepad   ' + os.path.basename(f))
                saveas()

            # if 'GB2312' in resultbima2:
        finally:
            textPad.insert(1.0, f.read())
            f.close()
windnd.hook_dropfiles(root,func=dragged_files)


def calcmanyline():
    neirong_yunsuan = textPad.get(1.0, END)
    fsuan = open("yunsuan.txt", "w").write(neirong_yunsuan)
    filenameAAA = r'yunsuan.txt'
    fbbbsuan = open(filenameAAA, 'r')
    linesuan = fbbbsuan.readline()
    all_ans = []
    while linesuan:
        ans_calc = calculator(linesuan)
        index = linesuan.find(linesuan)
        if index != -1:
            print(ans_calc)
        all_ans.append(str(ans_calc) + '\n')
        linesuan = fbbbsuan.readline()
    print(all_ans)
    fbbbsuan.close()
    fccc = open('suantmp.txt', 'w')
    for linesuan in all_ans:
        fccc.write(linesuan)
    fccc.close()
    f3ccc = open('suantmp.txt', 'r')
    textPad.delete(0.0, 'end')
    textPad.insert(1.0, f3ccc.read())
    textPad3fanyi.delete(0.0, 'end')
    textPad3fanyi.insert(1.0, neirong_yunsuan)
    f3ccc.close()
    try:
        os.remove('yunsuan.txt')
        os.remove('suantmp.txt')
    finally:
        pass
