#定位跳转
def goto_line():
    # 弹出对话框让用户输入行号
    line_num = simpledialog.askinteger("定位行数", "请输入要跳转的行号 (从1开始):")
    if line_num is not None:
        if line_num <= 0:
            showerror("错误", "行号必须大于0")
            return
        # 转换为 Tkinter 的格式，如 '1.0' 是第一行第一个字符
        textPad.mark_set("insert", f"{line_num}.0")
        textPad.see(f"{line_num}.0")
        textPad.focus_set()

