filename = ''
def manypic2txt22only(): #pl ocr
    def manypic2txt22only_th():


        def get_access_token():
            API_KEY =  plocrakvar
            SECRET_KEY = plocrskvar
            # APP_ID =plocridvar

            """ 使用 AK，SK 生成鉴权签名（Access Token）   :return: access_token，或是None(如果错误)    """
            url = "https://aip.baidubce.com/oauth/2.0/token"
            params = {"grant_type": "client_credentials", "client_id": API_KEY, "client_secret": SECRET_KEY}
            return str(requests.post(url, params=params).json().get("access_token"))
        def png2txt_adv(filename, output_filename):
            request_url = "https://aip.baidubce.com/rest/2.0/ocr/v1/accurate"
            # 二进制方式打开图片文件
            f = open(filename, 'rb')
            img = base64.b64encode(f.read())
            try:
                params = {"image":img,"language_type":cutwanteditityylang_PL2,"recognize_granularity" :"small","detect_direction": "true" }
            except NameError as e2:
                showinfo('Info', '请在左边选择OCR语言')
            access_token = get_access_token()
            request_url = request_url + "?access_token=" + access_token
            headers = {'content-type': 'application/x-www-form-urlencoded'}

            response = requests.post(request_url, data=params, headers=headers)

            if response:
                print(response.json())
            try:
                for word in response.json()['words_result']:

                        print(word['words'])
                        gettext0 = word['words']

                        with open(output_filename, "a",encoding='UTF-8') as rbfile0ocr:
                            rbfile0ocr.writelines(gettext0 + '\n')
            except :
                showinfo('Info', '选择的OCR语言可能有问题，本次输出可能内容为空')

        # dirname = workwhere2wzsbtp
