#优化代码，所有内容都在manypic2txt22handadv()里，要求当发现目录里多个文件,就以两个文件一组并发。保持原始过程基本不变。检查所有任务完成，如果没有完成，继续完成.
def manypic2txt22handadv():
    def manypic2txt22handadv_th():
        from concurrent.futures import ThreadPoolExecutor, as_completed

        def get_access_token():
            API_KEY = plocrakvar
            SECRET_KEY = plocrskvar
            url = "https://aip.baidubce.com/oauth/2.0/token"
            params = {
                "grant_type": "client_credentials",
                "client_id": API_KEY,
                "client_secret": SECRET_KEY
            }
            try:
                response = requests.post(url, params=params)
                return str(response.json().get("access_token"))
            except Exception as e:
                print("获取Token失败:", str(e))
                return None

        def png2txt_handadv2(filename, output_filename):
            request_url = "https://aip.baidubce.com/rest/2.0/ocr/v1/handwriting"
            try:
                with open(filename, 'rb') as f:
                    img = base64.b64encode(f.read())
            except Exception as e:
                print("读取图片失败:", str(e))
                return

            try:
                params = {
                    "image": img,
                    "language_type": cutwanteditityylang_PL2,
                    "recognize_granularity": "small",
                    "detect_direction": "true"
                }
            except NameError:
                print("请在界面选择OCR语言")
                return

            access_token = get_access_token()
            if not access_token:
                return

            request_url = request_url + "?access_token=" + access_token
            headers = {'content-type': 'application/x-www-form-urlencoded'}

            try:
                response = requests.post(request_url, data=params, headers=headers)
                result = response.json()

                if 'words_result' in result:
                    with open(output_filename, "a", encoding='UTF-8') as rbfile0ocr:
                        for word in result['words_result']:
                            gettext0 = word['words']
                            rbfile0ocr.writelines(gettext0 + '\n')
                else:
                    print("未识别到文字")
            except Exception as e:
                print("OCR请求或解析失败:", str(e))

            runingpb()

        dirname = e1workwherewzsbtp.get()
        dirnameout = e1workwherewzsbwb.get()

        valid_extensions = ('.jpg', '.png', '.bmp', '.jpeg')
        filenames = [f for f in os.listdir(dirname) if f.lower().endswith(valid_extensions)]

        if not filenames:
            print("目录中没有找到支持的图片格式")
            return

        tasks = []
        for filename in filenames:
            base, ext = os.path.splitext(filename)
            new_name = base + '.txt'
            full_filename = os.path.join(dirname, filename)
            output_filename = os.path.join(dirnameout, new_name)
            tasks.append((full_filename, output_filename))

        with ThreadPoolExecutor(max_workers=2) as executor:
            futures = [executor.submit(png2txt_handadv2, task[0], task[1]) for task in tasks]
            for future in as_completed(futures):
                try:
                    future.result()
                except Exception as e:
                    print("任务执行出错:", str(e))

        showinfo('提示', '所有图片转文本完成。')

    t1tpzwzzcsx = Thread(target=manypic2txt22handadv_th)
    t1tpzwzzcsx.start()

def manypic2txt_qwty():
    # 点击后先问「变文本还是变表格」；两种模式都只用 qwen3.8-max
    def qwty_ask_mode():
        askwin = tk.Toplevel()
        askwin.title('QW批量图转文本或表格')
        askwin.resizable(False, False)
        picked = {'mode': None}

        def pick(m):
            picked['mode'] = m
            askwin.destroy()

        tk.Label(askwin, text='你需要批量图片变文本还是变表格？').pack(padx=20, pady=(16, 10))
        ttk.Button(askwin, text='批量变文本（.txt）', width=24, command=lambda: pick('txt')).pack(pady=3)
        ttk.Button(askwin, text='批量变表格（.xlsx）', width=24, command=lambda: pick('xlsx')).pack(pady=3)
        ttk.Button(askwin, text='取消', width=24, command=askwin.destroy).pack(pady=(8, 14))

        # 按内容量窗口尺寸，别写死 geometry，免得按钮被裁掉点不到
        askwin.update_idletasks()
        askw = min(askwin.winfo_reqwidth(), askwin.winfo_screenwidth())
        askh = min(askwin.winfo_reqheight(), askwin.winfo_screenheight())
        askwin.geometry('%dx%d+%d+%d' % (askw, askh,
                                         (askwin.winfo_screenwidth() - askw) // 2,
                                         (askwin.winfo_screenheight() - askh) // 3))
        askwin.transient()
        askwin.grab_set()
        askwin.wait_window()
        return picked['mode']

    def manypic2txt_qwty_th(mode):

        def png2txt_qw(filename, output_filename):
            #模型：qwen3.8-max（变文本、变表格都是它）
            import dashscope
            import mimetypes
            from dashscope import MultiModalConversation

            dashscope.api_key = qwadvebvar
            dashworkspaceid = dashworkspaceidvar
            dashscope.base_http_api_url = "https://%s.cn-beijing.maas.aliyuncs.com/api/v1" % dashworkspaceid


            def encode_file(file_path):
                mime_type, _ = mimetypes.guess_type(file_path)
                if not mime_type:
                    # py3.7 的 mimetypes 不认 webp，按钮又承诺支持，这里补一张对照表
                    mime_type = {'.jpg': 'image/jpeg', '.jpeg': 'image/jpeg', '.png': 'image/png',
                                 '.bmp': 'image/bmp', '.webp': 'image/webp',
                                 '.tiff': 'image/tiff', '.tif': 'image/tiff'}.get(
                        os.path.splitext(file_path)[1].lower())
                if not mime_type or not mime_type.startswith("image/"):
                    raise ValueError("不支持或无法识别的图像格式")
                with open(file_path, "rb") as image_file:
                    encoded_string = base64.b64encode(image_file.read()).decode('utf-8')
                return f"data:{mime_type};base64,{encoded_string}"

            base64_image01 = encode_file(filename)
            cookiestextqw = '识别图片为文本' if mode == 'txt' else '识别图片为表格，输出html格式'

            def simple_multimodal_conversation_call():
                messages = [
                    {
                        "role": "user",
                        "content": [
                            {"image": base64_image01},
                            {"text": cookiestextqw}
                        ]
                    }
                ]
                responses = dashscope.MultiModalConversation.call(
                    api_key=dashscope.api_key,
                    model="qwen3.8-max",
                    messages=messages,
                    stream=True,
                    incremental_output=True,
                    # enable_search=True,
                    # search_options={"forced_search": True}
                )
                full_content = ''
                for response in responses:
                    try:
                        full_content = full_content + response.output.choices[0]['message']['content'][0]['text']
                    except:
                        pass
                time.sleep(0.5)

                def sanitize_text(text):
                    import re
                    return re.sub(r'[\U00010000-\U0010ffff]', '?', text)

                full_content2 = sanitize_text(full_content)
                if not full_content2.strip():
                    raise ValueError('模型没返回内容')
                if mode == 'xlsx':
                    # 表格模式照 000.txt：存表格 html（去掉 ``` 围栏和 html 字样），扩展名给 .xlsx，
                    # Excel 打开会按表格渲染，跨行跨列照样合并
                    full_content2 = full_content2.replace('```html', '').replace('```HTML', '').replace('```', '')
                    full_content2 = full_content2.replace('html', '')
                with open(output_filename, "w", encoding='UTF-8') as rbfile0ocr:
                    rbfile0ocr.writelines(full_content2)
                return mode

            return simple_multimodal_conversation_call()


        dirname = e1workwherewzsbtp.get()
        dirnameout = e1workwherewzsbwb.get()
        valid_extensions = ('.jpg', '.jpeg', '.png', '.bmp', '.webp', '.tiff')
        if not dirname or not os.path.isdir(dirname):
            showinfo('提示', '请先在左边选好图片所在的资料源目录')
            return
        if not dirnameout:
            showinfo('提示', '请先在左边选好识别输出目录')
            return
        if not os.path.isdir(dirnameout):
            try:
                os.makedirs(dirnameout)
            except Exception as e:
                showinfo('提示', '输出目录建不出来：%s' % str(e))
                return
        filenames = sorted([f for f in os.listdir(dirname)
                            if os.path.isfile(os.path.join(dirname, f))
                            and os.path.splitext(f)[1].lower() in valid_extensions])
        if not filenames:
            showinfo('提示', '源目录里没有找到图片（%s）' % '、'.join(valid_extensions))
            return

        modetxt = '文本' if mode == 'txt' else '表格'
        print('QW批量图转%s：共 %d 张，输出到 %s' % (modetxt, len(filenames), dirnameout))
        okcount = 0
        faillist = []
        for filename in filenames:
            base = os.path.splitext(filename)[0]
            srcfile = os.path.join(dirname, filename)
            output_filename = os.path.join(dirnameout, base + ('.txt' if mode == 'txt' else '.xlsx'))
            print('正在识别：%s' % filename)
            try:
                png2txt_qw(srcfile, output_filename)
                okcount += 1
            except Exception as e:
                faillist.append(filename)
                print('识别失败：%s -> %s' % (filename, str(e)))
            runingpb()

        tip = '所有图片转%s完成。\n共 %d 张，成功 %d 张' % (modetxt, len(filenames), okcount)
        if faillist:
            tip += '\n失败 %d 张：%s' % (len(faillist),
                                        '、'.join(faillist[:5]) + ('…' if len(faillist) > 5 else ''))
        tip += '\n输出目录：%s' % dirnameout
        print(tip)
        showinfo('提示', tip)

    mode = qwty_ask_mode()
    if not mode:
        return
    thr31manypic2txt_qwty=Thread(target=manypic2txt_qwty_th, args=(mode,))
    thr31manypic2txt_qwty.start()  # th31

