def mergemanywordsfiles():
    # dirnamesrc = workwhere2wzsbtp #来源
    # dirnameoutto = workwhere3wzsbwb #输出
    dirnamesrc = e1workwherewzsbtp.get()
    dirnameoutto = e1workwherewzsbwb.get()
    # import docx
    # import os
    # showinfo('提示', '先选word_docx多文件所在目录和输出合并后文件的所在目录.')
    from glob import glob
    # from docxcompose.composer import Composer
    base_dirsrc = dirnamesrc
    save_pathto = dirnameoutto
    def combine_all_docx(files_list):
        number_of_sections = len(files_list)
        master = docx.Document()
        composer = Composer(master)
        for i in range(0, number_of_sections):
            doc_temp = docx.Document((files_list[i]))
            composer.append(doc_temp)
        composer.save(os.path.join(save_pathto, 'merge.docx'))
    # 执行
    path_list = glob(os.path.join(base_dirsrc, '*.docx'))
    combine_all_docx(path_list)
    showinfo('提示', '所有word_docx合并完成，输出merge.docx在你选择的目录下。')
    print(save_pathto, '\merge.docx')

    try:
        os.startfile(save_pathto + '\\merge.docx')
    except:
        os.startfile(save_pathto + 'merge.docx')
