def manyworddocx2pdf():
    showinfo('注意', '先选择docx位置.再选择输出pdf位置')
    mydocxde_root = askdirectory(title='选择docx位置') + '/'
    getpdfweizhi=askdirectory(title='选择输出pdf位置') + '/'
    wdFormatPDF = 17
    def doc2pdf(input_file, input_file_name, output_dir):
        try:
            word = Dispatch('Word.Application')
            doc = word.Documents.Open(input_file)
        except Exception as e:
            print("word无法打开, 发生如下错误:\n{}".format(e))
        try:
            pdf_file_name = input_file_name.replace(".docx", ".pdf").replace(".doc", ".pdf")
            pdf_file = os.path.join(output_dir, pdf_file_name)
            doc.SaveAs(pdf_file, FileFormat=wdFormatPDF)
            doc.Close()
            word.Quit()
            print("成功转换\"{}\"".format(input_file_name))
            print()
        except Exception as e:
            print("文件保存失败, 发生如下错误:\n{}".format(e))

    doc_files = []
    directory = mydocxde_root
    output_dir = getpdfweizhi
    for root, _, filenames in os.walk(directory):
        for file in filenames:
            if file.endswith(".doc") or file.endswith(".docx"):
                print("转换{}中......".format(file))
                doc2pdf(os.path.join(root, file), file, output_dir)
                time.sleep(5)
                runingpb()
    showinfo('注意', '批量word docx转pdf完毕.')
def yspicsfromxlsx():
    import shutil
    import zipfile

    gettqxlsxpathfull = askopenfilename(title='选一个表文件', defaultextension='.xlsx')
    xlsxpathfolder=str(gettqxlsxpathfull.split('/')[:-1]).replace("', '","\\").replace("']","\\").replace("['","")
    print(xlsxpathfolder)
    xlsxname=gettqxlsxpathfull.split('/')[-1]
    xlsxshortname=xlsxname.split('.')[-2]
    print(xlsxname)
    print(xlsxshortname)
    # os.system("explorer.exe %s" % xlsxpathfolder)
    folder_name = r'C:\xlsxwork'
    try:
        os.mkdir(folder_name)
    except:
        pass
    # global workDir
    workDir = r'C:\xlsxwork'
    zipname=xlsxshortname+'.zip'
    zippath=workDir+'\\'+zipname
    # os.system("explorer.exe %s" % workDir)
    shutil.copy(gettqxlsxpathfull,zippath)

    def decompress_zip(zip_path, dir_path):
        """
        zip 文件解压
        :param zip_path: zip 压缩包路径
        :param dir_path: 解压路径
        :return:
        """
        f = zipfile.ZipFile(zip_path, 'r')  # 压缩文件位置
        for file in f.namelist():
            f.extract(file, dir_path)  # 解压位置
        f.close()

    decompress_zip(zippath, workDir)
    mediapicpath=r'C:\xlsxwork\xl\media'
    workwhere2wzsbtxt=mediapicpath
    workwhere3wzsbwbtp=mediapicpath
    API_KEYzt = '你的抠图API_KEY'

    def ztystp_dan(filename, output_filename):
        IMAGE_FILE_PATH = filename

        def create_task():
            assert os.path.exists(IMAGE_FILE_PATH), f'Error: File({IMAGE_FILE_PATH}) does not exist.'

            headers = {'X-API-KEY': API_KEYzt}
            data = {'sync': '0'}
            files = {'image_file': open(IMAGE_FILE_PATH, 'rb')}
            url = 'https://techsz.aoscdn.com/api/tasks/visual/imgcompress'

            # Create a task
            response = requests.post(url, headers=headers, data=data, files=files)

            task_id = None
            response_json = response.json()
            if 'status' in response_json and response_json['status'] == 200:
                result_tag = 'failed'
                if 'data' in response_json:
                    response_json_data = response_json['data']
                    if 'task_id' in response_json_data:
                        result_tag = 'successful'
                        task_id = response_json_data['task_id']
                print(f'Result of created task({result_tag}): {response_json}')
            else:
                # request failed, log the details
                print(f'Error: Failed to create task,{response.text}')
            return task_id

        # get the task result
        # 1、"The polling interval is set to 1 second."
        # 2、"The polling time is around 30 seconds."
        def polling_task_result(task_id, time_out=30):
            headers = {'X-API-KEY': API_KEYzt}
            url = f'https://techsz.aoscdn.com/api/tasks/visual/imgcompress/{task_id}'
            for i in range(time_out):
                if i != 0:
                    time.sleep(1)
                response = requests.get(url, headers=headers)
                response_json = response.json()
                if 'status' in response_json and response_json['status'] == 200:
                    if 'data' in response_json:
                        response_json_data = response_json['data']
                        if 'state' in response_json_data:
                            task_state = response_json_data['state']
                            if task_state == 1:
                                # task success
                                print(f'Result(successful): {response_json}')
                                myzttu = response_json_data['image']
                                # img_data = base64.b64decode(img_str)
                                print(f' {myzttu}')
                                outfilenamezttu = output_filename
                                # urllib.request.urlretrieve(myzttu, outfilenamezttu)
                                responsemyfile = requests.get(myzttu)
                                with open(outfilenamezttu, 'wb') as file:
                                    # 将图片内容写入文件
                                    file.write(responsemyfile.content)
                                runingpb()  # 进度条
                                # os.startfile(outfilenamezttu)
                                break
                            elif task_state < 0:
                                # Task exception, logging the error.
                                # You can choose to continue the loop with 'continue' or break the loop with 'break'
                                print(f'Result(failed): {response_json}')
                                showinfo('notice', '异常')
                                break
                    print(f'Result(polling): {response_json}')
                    if i == time_out - 1:
                        # Timeout, log the details, and search for support from the picwish service.
                        print('Error: Timeout while polling.')
                else:
                    # Task exception, logging the error.
                    # You can choose to continue the loop with 'continue' or break the loop with 'break'
                    print(f'Error: Failed to get the task\'s result,{response.text}')
                    break

        def mainztystp():
            task_id = create_task()
            if task_id is None:
                print('Error: Failed to create task,task id is None.')
                return
            polling_task_result(task_id)

        mainztystp()

    dirname = workwhere2wzsbtxt
    dirnameout = workwhere3wzsbwbtp
    filenames = os.listdir(dirname)
    for filename in filenames:
        if filename.endswith('jpg') or filename.endswith('png') or filename.endswith('jpeg') or filename.endswith(
                'bmp') or filename.endswith('JPG') or filename.endswith('PNG') or filename.endswith(
            'JPEG') or filename.endswith('BMP') or filename.endswith('webp') or filename.endswith(
            'tiff') or filename.endswith('gif') or filename.endswith('tif'):
            base, ext = filename.split('.')
            new_name = base + '.' + ext
            filename = dirname + '/' + filename
            output_filename = dirnameout + '/' + new_name
            ztystp_dan(filename, output_filename)
    os.remove(zippath)

    def compression_zip(dir_path, out_put_zip_path):
        """
        压缩指定文件夹
        :param dir_path: 目标文件夹路径
        :param out_put_zip_path: 压缩文件保存路径+xxxx.zip
        :return: 无
        """
        # 目录切换
        os.chdir(dir_path)
        zip_ = zipfile.ZipFile(out_put_zip_path, "w", zipfile.ZIP_DEFLATED)  # outFullName为压缩文件的完整路径
        for path, dir_names, filenames in os.walk("./"):
            # 过滤 .git 文件夹
            new_root = path.replace("\\", "/")
            for filename in filenames:
                file_path = f"{new_root}/{filename}"
                if not os.path.exists(file_path):
                    continue
                zip_.write(os.path.join(new_root, filename))
        zip_.close()
    # global folder_name2
    folder_name2 = r'C:\xlsxwork2'
    try:
        os.mkdir(folder_name2)
    except:
        pass
    newzippath= 'C:\\xlsxwork2\\zippedxlsx.zip'
    compression_zip(workDir,newzippath)
    gettqxlsxpathfullnew=xlsxpathfolder+'\\'+xlsxshortname+'-zipped.xlsx'
    shutil.copy(newzippath, gettqxlsxpathfullnew)
    showinfo('notice', '压缩表格里图片完成，表格变小了，新文件名zipped.xlsx结尾.')
    time.sleep(2)
    os.remove(newzippath)


    def remove_folder(path):
        if os.path.exists(path):
            shutil.rmtree(path)

    remove_folder(workDir)
    remove_folder(folder_name2)


