from spire.pdf.common import *
from spire.pdf import *
from spire.pdf.PdfTextReplacer import PdfTextReplacer
from spire.pdf.PdfDocument import PdfDocument
def pdfgaijuzi():
    # 选择文件
    xgpdffile = askopenfilename(title='选一个PDF文件', defaultextension='.pdf')
    if not xgpdffile:
        print("未选择文件")
        return

    xgpdffilebase = xgpdffile.split('/')[-1].split('.')[0]  # 获取不带路径和扩展名的文件名
    xgpdffile2 = asksaveasfilename(
        title='选PDF文件输出位置',
        initialfile=f'{xgpdffilebase}-2.pdf',
        defaultextension='.pdf',
        filetypes=[('PDF files', '*.pdf')]
    )
    if not xgpdffile2:
        print("未选择保存路径")
        return

    # 自定义对话框类
    class CustomInputDialog(simpledialog.Dialog):
        def __init__(self, parent, title=None, prompt="", initialvalue="", width=20):
            self.prompt = prompt
            self.initialvalue = initialvalue
            self.width = width
            super().__init__(parent, title)

        def body(self, master):
            from tkinter import Label, Entry
            Label(master, text=self.prompt).grid(row=0, column=0, sticky="w", padx=5, pady=5)
            self.entry = Entry(master, width=self.width)
            self.entry.grid(row=0, column=1, padx=5, pady=5)
            if self.initialvalue:
                self.entry.insert(0, self.initialvalue)
            return self.entry

        def apply(self):
            self.result = self.entry.get()

    def ask_long_string(title, prompt, initialvalue="", width=40):
        root = Tk()
        root.withdraw()
        dialog = CustomInputDialog(root, title=title, prompt=prompt, initialvalue=initialvalue, width=width)
        root.destroy()
        return dialog.result

    # 输入旧文本和新文本
    inputoldpdfstr = ask_long_string("输入原文句子", "输入错误句子:", width=40) or ""
    inputnewpdfstr = ask_long_string("输入新的句子", "输入正确句子：", width=40) or ""

    # 清理 emoji 和特殊符号（只保留中文、英文、数字和常见标点）
    def clean_text(text):
        # 去除 emoji 和非基本字符
        cleaned = re.sub(
            r'[^\u4e00-\u9fa5\u3000-\u303f\uff00-\uffef\u0041-\u005a\u0061-\u007a\u0030-\u0039\u0020\u0021-\u002f\u003a-\u0040]',
            '', text)
        return cleaned

    inputoldpdfstr = clean_text(inputoldpdfstr)
    inputnewpdfstr = clean_text(inputnewpdfstr)

    # 加载 PDF 文档
    doc = PdfDocument()
    doc.LoadFromFile(xgpdffile)

    # 遍历每一页并替换所有匹配的文本
    for i in range(doc.Pages.Count):
        page = doc.Pages[i]
        replacer = PdfTextReplacer(page)
        replacer.ReplaceAllText(inputoldpdfstr, inputnewpdfstr)  # 替换所有匹配项

    # 保存并关闭文档
    doc.SaveToFile(xgpdffile2)
    doc.Close()

    print(f"PDF 已保存至: {xgpdffile2}")
    #去除顶部
    def remove_header_text(pdf_path, output_path, header_height=80):
        doc = fitz.open(pdf_path)
        for page in doc:
            # 获取页面大小
            rect = page.rect
            # 定义顶部区域（页眉区域）
            header_rect = fitz.Rect(0, 0, rect.width, header_height)

            # 查找页眉区域中的文字块
            blocks = page.get_text("dict", clip=header_rect)["blocks"]
            for block in blocks:
                if "lines" in block:
                    for line in block["lines"]:
                        for span in line["spans"]:
                            # 获取文字位置
                            bbox = fitz.Rect(span["bbox"])
                            # 用白色矩形覆盖文字区域
                            page.draw_rect(bbox, color=(1, 1, 1), fill=(1, 1, 1))

        doc.save(output_path)
        doc.close()
        print(f"页眉文字已去除，新文件保存为: {output_path}")

    # 调用去除页眉函数
    xgpdffile2_clean = xgpdffile2.replace(".pdf", "-clean.pdf")
    remove_header_text(xgpdffile2, xgpdffile2_clean, header_height=80)

