def docofdpdf2mdfmany():#paddle-vl-parser
    supported_formats = (
        '.pdf', '.jpg', '.jpeg', '.png', '.bmp', '.tif', '.tiff', '.ofd',
        '.doc', '.docx', '.txt', '.wps', '.ppt', '.pptx'
    )

    input_dir = askdirectory(title='请选择包含待处理文件的目录')
    if not input_dir:
        print("未选择输入目录, 程序退出")
        return

    output_dir = askdirectory(title='请选择Markdown文件的输出目录')
    if not output_dir:
        print("未选择输出目录, 程序退出")
        return

    files_to_process = []
    for root, dirs, files in os.walk(input_dir):
        for file in files:
            if file.lower().endswith(supported_formats):
                files_to_process.append(os.path.join(root, file))

    if not files_to_process:
        print("所选目录中没有找到支持的文件格式")
        return

    total_files = len(files_to_process)
    print(f"共找到 {total_files} 个文件待处理")

    def get_token():
        host = plocrakskvar
        response_token = requests.get(host)
        return response_token.json()['access_token']

    for index, file_path in enumerate(files_to_process):
        file_name = os.path.basename(file_path)
        print(f"[{index + 1}/{total_files}] 正在处理: {file_name}")

        try:
            with open(file_path, "rb") as f:
                file_data = base64.b64encode(f.read()).decode('utf-8')

            data = {
                "file_data": file_data,
                "file_url": "",
                "file_name": file_name
            }
            headers = {'Content-Type': 'application/x-www-form-urlencoded'}

            max_retries = 3
            markdown_url = None

            for retry_count in range(max_retries):
                if retry_count > 0:
                    print(f"  获取链接失败或超时, 正在进行第 {retry_count + 1} 次重试")

                token = get_token()
                request_host = f"https://aip.baidubce.com/rest/2.0/brain/online/v2/paddle-vl-parser/task?access_token={token}"

                try:
                    response = requests.post(request_host, headers=headers, data=data, timeout=30)
                    res_json = response.json()
                except Exception as e:
                    print(f"  创建任务请求异常: {str(e)}")
                    continue

                if 'result' not in res_json or 'task_id' not in res_json['result']:
                    print(f"  创建任务失败: {res_json}")
                    continue

                task_id = res_json['result']['task_id']
                print(f"  任务ID: {task_id}")

                query_host = f"https://aip.baidubce.com/rest/2.0/brain/online/v2/paddle-vl-parser/task/query?access_token={token}"

                for attempt in range(60):
                    time.sleep(15)
                    payload = {"task_id": task_id}
                    try:
                        r_query = requests.post(query_host, headers=headers, data=payload, timeout=30)
                        q_json = r_query.json()
                    except Exception as e:
                        print(f"  查询任务请求异常: {str(e)}")
                        continue

                    if 'result' in q_json and 'markdown_url' in q_json['result']:
                        markdown_url = q_json['result']['markdown_url']
                        break
                    elif 'result' in q_json and 'status' in q_json['result']:
                        status = q_json['result']['status']
                        if status in ['failed', 'error']:
                            print(f"  任务执行失败: {q_json}")
                            break
                    print(f"  等待服务器处理中...")

                if markdown_url:
                    break

            if not markdown_url:
                print(f"  获取Markdown链接超时或失败, 已重试{max_retries}次, 放弃该文件")
                continue

            response_md = requests.get(markdown_url, timeout=60)

            base_name = os.path.splitext(file_name)[0]
            output_file_path = os.path.join(output_dir, f"{base_name}.md")

            with open(output_file_path, 'wb') as md_file:
                md_file.write(response_md.content)

            print(f"  保存成功: {output_file_path}")

            try:
                runingpb()
            except NameError:
                pass

        except Exception as e:
            print(f"  处理文件时发生错误: {str(e)}")
            continue

    showinfo('done', "所有文件处理完毕")

#优化代码，所有内容都在docofdpdf2mdfmanyun()里，要求当发现目录里多个文件,就以两个文件一组并发。保持原始过程基本不变。检查所有任务完成，如果没有完成，继续完成.
def docofdpdf2mdfmanyun():
    def docofdpdf2mdfmanyun_th():
        from threading import Thread
        from concurrent.futures import ThreadPoolExecutor, as_completed

        supported_formats = (
            '.pdf', '.jpg', '.jpeg', '.png', '.bmp', '.tif', '.tiff', '.ofd',
            '.doc', '.docx', '.txt', '.wps', '.ppt', '.pptx'
        )

        input_dir = askdirectory(title='请选择包含待处理文件的目录')
        if not input_dir:
            print("未选择输入目录, 程序退出")
            return

        output_dir = askdirectory(title='请选择Markdown文件的输出目录')
        if not output_dir:
            print("未选择输出目录, 程序退出")
            return

        files_to_process = []
        for root, dirs, files in os.walk(input_dir):
            for file in files:
                if file.lower().endswith(supported_formats):
                    files_to_process.append(os.path.join(root, file))

        if not files_to_process:
            print("所选目录中没有找到支持的文件格式")
            return

        total_files = len(files_to_process)
        print(f"共找到 {total_files} 个文件待处理")

        def process_single_file(file_path, out_dir):
            file_name = os.path.basename(file_path)
            print(f"正在处理: {file_name}")

            def get_token():
                host = plocrakskvar
                response_token = requests.get(host)
                return response_token.json()['access_token']

            try:
                with open(file_path, "rb") as f:
                    file_data = base64.b64encode(f.read()).decode('utf-8')

                data = {
                    "file_data": file_data,
                    "file_url": "",
                    "file_name": file_name
                }
                headers = {'Content-Type': 'application/x-www-form-urlencoded'}

                max_retries = 3
                markdown_url = None

                for retry_count in range(max_retries):
                    if retry_count > 0:
                        print(f"  获取链接失败或超时, 正在进行第 {retry_count + 1} 次重试")

                    token = get_token()
                    request_host = f"https://aip.baidubce.com/rest/2.0/brain/online/v2/unlimited-ocr-parser/task?access_token={token}"

                    try:
                        response = requests.post(request_host, headers=headers, data=data, timeout=30)
                        res_json = response.json()
                    except Exception as e:
                        print(f"  创建任务请求异常: {str(e)}")
                        continue

                    if 'result' not in res_json or 'task_id' not in res_json['result']:
                        print(f"  创建任务失败: {res_json}")
                        continue

                    task_id = res_json['result']['task_id']
                    print(f"  任务ID: {task_id}")

                    query_host = f"https://aip.baidubce.com/rest/2.0/brain/online/v2/unlimited-ocr-parser/task/query?access_token={token}"

                    for attempt in range(60):
                        time.sleep(15)
                        payload = {"task_id": task_id}
                        try:
                            r_query = requests.post(query_host, headers=headers, data=payload, timeout=30)
                            q_json = r_query.json()
                        except Exception as e:
                            print(f"  查询任务请求异常: {str(e)}")
                            continue

                        if 'result' in q_json and 'markdown_url' in q_json['result']:
                            markdown_url = q_json['result']['markdown_url']
                            break
                        elif 'result' in q_json and 'status' in q_json['result']:
                            status = q_json['result']['status']
                            if status in ['failed', 'error']:
                                print(f"  任务执行失败: {q_json}")
                                break
                        print(f"  等待服务器处理中...")

                    if markdown_url:
                        break

                if not markdown_url:
                    print(f"  获取Markdown链接超时或失败, 已重试{max_retries}次, 放弃该文件")
                    return False

                response_md = requests.get(markdown_url, timeout=60)

                base_name = os.path.splitext(file_name)[0]
                output_file_path = os.path.join(out_dir, f"{base_name}.md")

                with open(output_file_path, 'wb') as md_file:
                    md_file.write(response_md.content)

                print(f"  保存成功: {output_file_path}")

                try:
                    runingpb()
                except NameError:
                    pass

                return True

            except Exception as e:
                print(f"  处理文件时发生错误: {str(e)}")
                return False

        tasks = [(file_path, output_dir) for file_path in files_to_process]

        with ThreadPoolExecutor(max_workers=2) as executor:
            future_to_file = {executor.submit(process_single_file, task[0], task[1]): task[0] for task in tasks}

            failed_tasks = []

            for future in as_completed(future_to_file):
                file_path = future_to_file[future]
                try:
                    result = future.result()
                    if not result:
                        failed_tasks.append((file_path, output_dir))
                except Exception as e:
                    print(f"任务执行出错 {file_path}: {str(e)}")
                    failed_tasks.append((file_path, output_dir))

            if failed_tasks:
                print(f"有 {len(failed_tasks)} 个任务未完成, 进行重试...")
                with ThreadPoolExecutor(max_workers=2) as retry_executor:
                    retry_futures = {retry_executor.submit(process_single_file, task[0], task[1]): task[0] for task in
                                     failed_tasks}
                    for future in as_completed(retry_futures):
                        try:
                            future.result()
                        except Exception as e:
                            print(f"重试任务依然出错: {str(e)}")

        showinfo('done', "所有文件处理完毕")

    tunlocrmd = Thread(target=docofdpdf2mdfmanyun_th)
    tunlocrmd.start()

def hfxcc3():#文本的行反向存储
    def txt2revs(filename, output_filename):
        file1 = open(filename, 'r')
        list1 = []  # 用一个空列表用于存放每行的内容
        while True:
            line = file1.readline()
            # print('line count=', len(line))
            list1.append(line.strip())
            if len(line) == 0:
                break
            for l in list1[::-1]:  # 反向遍历，然后依次读取出来
                print (l)
                with open(output_filename, "a") as out_f:
                    out_f.write(l + "\n")
        file1.close()
        countold = 1
        for countold, lineold in enumerate(open(filename, 'r').readlines()):
            countold += 1
        print('行数countold:', countold)
        countnew =1
        for countnew, linenew in enumerate(open(output_filename, 'r').readlines()):
            countnew += 1
        print('行数countnew:', countnew)
        dellline = countnew - countold

        fileget = open(output_filename)
        lines = fileget.readlines()

        del lines[0:dellline]  # 删除第1行到第17行
        fileget.close()

        file_new = open(output_filename, 'w')
        file_new.writelines(lines)  # 将删除行后的数据写入文件
        file_new.close()

    path = askdirectory() + '/'
    dirname = path
    dirnameout = path
    filenames = os.listdir(dirname)
    for filename in filenames:
        if filename.endswith('txt')or filename.endswith('TXT') :
            base, ext = filename.split('.')
            new_name = base +'逆向后'+ '.txt'
            filename = dirname + '/' + filename
            output_filename = dirnameout + '/' + new_name
            txt2revs(filename, output_filename)
    start_directoryt2 = dirnameout.replace('/', '\\')
    print(dirnameout)
