def pdfimg2pdfstrzt2():
    import fitz
    import requests
    import time
    import urllib.request
    import shutil
    from tkinter.filedialog import askopenfilename, asksaveasfilename
    from tkinter.messagebox import showinfo
    API_KEYzt = '你的抠图API_KEY'
    image_path = askopenfilename(title='请选择一个PDF或图片文件')
    if not image_path:
        return

    def is_pdf(file_path):
        return file_path.lower().endswith('.pdf')

    def submit_and_get_pdf(image_file_path, output_pdf_path):
        headers = {'X-API-KEY': API_KEYzt}
        data = {'format': 'pdf'}
        url = 'https://techsz.aoscdn.com/api/tasks/document/ocr'

        task_id = None
        try:
            with open(image_file_path, 'rb') as f:
                files = {'image_file': f}
                response = requests.post(url, headers=headers, data=data, files=files)
            response_json = response.json()
            if response_json.get('status') == 200 and 'data' in response_json:
                task_id = response_json['data'].get('task_id')
        except Exception as e:
            print('创建任务失败')
            return False

        if not task_id:
            print('获取任务ID失败')
            return False

        poll_url = f'https://techsz.aoscdn.com/api/tasks/document/ocr/{task_id}'
        for i in range(120):
            time.sleep(1)
            try:
                resp = requests.get(poll_url, headers=headers)
                res_json = resp.json()
                if res_json.get('status') == 200 and 'data' in res_json:
                    state = res_json['data'].get('state')
                    if state == 1:
                        file_url = res_json['data'].get('file')
                        if file_url:
                            urllib.request.urlretrieve(file_url, output_pdf_path)
                            return True
                    elif state < 0:
                        print('任务处理失败')
                        return False
            except Exception as e:
                print('轮询失败')
                return False
        print('轮询超时')
        return False

    if is_pdf(image_path):
        pdf_dir = os.path.dirname(image_path)
        pdf_base_name = os.path.splitext(os.path.basename(image_path))[0]
        temp_dir = os.path.join(pdf_dir, pdf_base_name)

        if os.path.exists(temp_dir):
            shutil.rmtree(temp_dir)
        os.makedirs(temp_dir)

        try:
            doc = fitz.open(image_path)
            page_count = len(doc)
            temp_pdfs = []

            for pg in range(page_count):
                page = doc[pg]
                mat = fitz.Matrix(300 / 72, 300 / 72)
                pix = page.get_pixmap(matrix=mat)
                img_path = os.path.join(temp_dir, f'page_{pg}.png')
                pix.save(img_path)

                result_pdf_path = os.path.join(temp_dir, f'result_{pg}.pdf')
                print(f'正在识别第 {pg + 1} 页，共 {page_count} 页')
                success = submit_and_get_pdf(img_path, result_pdf_path)
                if success:
                    temp_pdfs.append(result_pdf_path)
                else:
                    print(f'第 {pg + 1} 页识别失败')
            doc.close()

            if temp_pdfs:
                merged_doc = fitz.open()
                for pdf_file in temp_pdfs:
                    src_doc = fitz.open(pdf_file)
                    merged_doc.insert_pdf(src_doc)
                    src_doc.close()

                save_path = asksaveasfilename(
                    initialfile=f'{pdf_base_name}_ocr.pdf',
                    defaultextension='.pdf',
                    filetypes=[('PDF files', '.pdf')]
                )
                if save_path:
                    merged_doc.save(save_path)
                    showinfo('提示', '合并完成并保存成功')
                merged_doc.close()
            else:
                showinfo('提示', '没有成功识别的页面')
        finally:
            if os.path.exists(temp_dir):
                shutil.rmtree(temp_dir)
    else:
        img_base_name = os.path.splitext(os.path.basename(image_path))[0]
        save_path = asksaveasfilename(
            initialfile=f'{img_base_name}_ocr.pdf',
            defaultextension='.pdf',
            filetypes=[('PDF files', '.pdf')]
        )
        if save_path:
            print('正在识别图片')
            success = submit_and_get_pdf(image_path, save_path)
            if success:
                showinfo('提示', '识别完成并保存成功')
            else:
                showinfo('提示', '识别失败')

