def pdfimg2pdfstrztppt():
    import fitz  # PyMuPDF
    from PIL import Image
    import io
    import tempfile
    import os
    import requests
    import time
    from tkinter.filedialog import askopenfilename, asksaveasfilename
    import urllib.request
    API_KEYzt = '你的抠图API_KEY'
    # IMAGE_FILE_PATH = 'YOUR_IMAGE_FILE_PATH'
    image_path = askopenfilename(title='选一个pdf or jpg文件')
    def create_task():
        assert os.path.exists(image_path), f'Error: File({image_path}) does not exist.'

        headers = {'X-API-KEY': API_KEYzt}
        data = {'format': 'pptx'}
        files = {'image_file': open(image_path, 'rb')}
        url = 'https://techsz.aoscdn.com/api/tasks/document/ocr'

        # Create a task
        response = requests.post(url, headers=headers, data=data, files=files)

        task_id = None
        response_json = response.json()
        if 'status' in response_json and response_json['status'] == 200:
            result_tag = 'failed'
            if 'data' in response_json:
                response_json_data = response_json['data']
                if 'task_id' in response_json_data:
                    result_tag = 'successful'
                    task_id = response_json_data['task_id']
            print(f'Result of created task({result_tag}): {response_json}')
        else:
            # request failed, log the details
            print(f'Error: Failed to create task,{response.text}')
        return task_id

    # get the task result
    # 1、"The polling interval is set to 1 second."
    # 2、"The polling time is around 120 seconds."
    def polling_task_result(task_id, time_out=120):
        headers = {'X-API-KEY': API_KEYzt}
        url = f'https://techsz.aoscdn.com/api/tasks/document/ocr/{task_id}'
        for i in range(time_out):
            if i != 0:
                time.sleep(1)
            response = requests.get(url, headers=headers)
            response_json = response.json()
            if 'status' in response_json and response_json['status'] == 200:
                if 'data' in response_json:
                    response_json_data = response_json['data']
                    if 'state' in response_json_data:
                        task_state = response_json_data['state']
                        if task_state == 1:
                            # task success
                            # print(f'Result(successful): {response_json}')
                            # print(f'Result(successful): {response_json}')
                            myzttu2 = response_json_data['file']

                            print(f' {myzttu2}')
                            outfilenamezttu2pdf = asksaveasfilename(initialfile='-strpdf.pptx',
                                                                    defaultextension='.pptx',
                                                                    filetypes=[('pptx files', '.pptx')])
                            urllib.request.urlretrieve(myzttu2, outfilenamezttu2pdf)

                            break
                        elif task_state < 0:
                            # Task exception, logging the error.
                            # You can choose to continue the loop with 'continue' or break the loop with 'break'
                            print(f'Result(failed): {response_json}')
                            break
                print(f'Result(polling): {response_json}')
                if i == time_out - 1:
                    # Timeout, log the details, and search for support from the picwish service.
                    print('Error: Timeout while polling.')
            else:
                # Task exception, logging the error.
                # You can choose to continue the loop with 'continue' or break the loop with 'break'
                print(f'Error: Failed to get the task\'s result,{response.text}')
                break

    def mainpp():
        task_id = create_task()
        if task_id is None:
            print('Error: Failed to create task,task id is None.')
            return
        polling_task_result(task_id)


    mainpp()


#longpics2wordsplui
def longpics2wordsplui():
    import os
    import re
    import time
    import queue
    import base64
    import threading
    import tkinter as tk
    from io import BytesIO
    from tkinter import ttk, messagebox
    from tkinter.filedialog import askdirectory
    from tkinter.scrolledtext import ScrolledText

    import requests
    from PIL import Image
    import docx
    from docx.oxml.ns import qn
    from docxcompose.composer import Composer

    APP_DIR = os.path.dirname(os.path.abspath(__file__))
    os.chdir(APP_DIR)

    IMAGE_EXTS = ('.png', '.jpg', '.jpeg', '.bmp', '.webp', '.tif', '.tiff')
    LANCZOS = getattr(Image, 'Resampling', Image).LANCZOS

    BAIDU_TOKEN_URL = 'https://aip.baidubce.com/oauth/2.0/token'
    DOC_CONVERT_REQ = 'https://aip.baidubce.com/rest/2.0/ocr/v1/doc_convert/request'
    DOC_CONVERT_GET = 'https://aip.baidubce.com/rest/2.0/ocr/v1/doc_convert/get_request_result'

    CONVERT_MAX_BYTES = int(7 * 1024 * 1024)  # image base64 后不超过 8M，留点余量
    CONVERT_MAX_SIDE = 8192  # 最长边超过这个值先等比缩小，免得接口直接拒
    JPEG_STEPS = (92, 80, 65, 50)  # PNG 还超体积时，JPEG 逐级降质量
    TOKEN_RETRY_CODES = (110, 111)  # token失效/过期：刷新后重试
    RATE_RETRY_CODES = (18, 19)  # QPS/总量超限：等一会儿重试
    # doc_convert 任务状态码，2026-09-09 拿真接口实测出来的（不是网上说的 1000/2000/3000）：
    # 1=未开始、2=进行中、3=成功（percent=100，result_data.word 给下载地址）
    RET_NOT_STARTED = 1
    RET_PROCESSING = 2
    RET_SUCCESS = 3
    RET_BUSY = (RET_NOT_STARTED, RET_PROCESSING)

    DEFAULT_LONG_H = 4000  # 高度达到这个值才算长图，才切段；不到的整张当一段
    DEFAULT_SEG_H = 3000  # 每段高度 px
    DEFAULT_OVERLAP = 150  # 相邻段重叠 px，找不到空白行时兜底，保证被切断的那行至少有一段是全的
    DEFAULT_CUT_SEARCH = 600  # 在理想切割点上下这么多px里找空白行下刀（0=不找，就按整seg_h切）
    BLANK_TOL = 24  # 一行里最亮最暗相差在这个值以内，算「空白行」（没有文字压着）
    DEFAULT_WAIT = 240  # 等一段转word结果的最长秒数
    DEFAULT_POLL = 4  # 轮询间隔秒数
    DEFAULT_DEDUPE = True  # 接缝处重复的内容自动去掉
    DEFAULT_DEDUPE_LINES = 10  # 接缝两侧各取几段来比对
    DEDUPE_MAX_CHARS = 2000  # 比对时上文最多取多少字
    DEDUPE_MIN_CHARS = 10  # 少于这么多个字的重复不删，怕是碰巧撞上（比如页码、章节号）
    DEFAULT_MERGE_ALL = True  # 全部处理完再按顺序合并成一个总word
    MERGE_ALL_NAME = '合并_全部word.docx'
    SEG_SUBDIR = '分段word'

    def read_cfg(name):
        """密钥文件只在程序同目录和自己的 goldtools 里找（同目录优先），不读 cankao"""
        for path in (os.path.join(APP_DIR, name),
                     os.path.join(APP_DIR, 'goldtools', name)):
            if os.path.isfile(path):
                with open(path, 'r', encoding='utf-8') as f:
                    return f.read().strip()
        return ''

    ocr_api_key = read_cfg('plocrak.cfg')  # 百度OCR AK
    ocr_secret_key = read_cfg('plocrsk.cfg')  # 百度OCR SK

    class ConvertError(Exception):
        """单段/单张图片处理失败"""

    class StopRequest(Exception):
        """用户点了停止"""

    # ---------- 文件收集与切段 ----------

    def natkey(path):
        """文件名里的数字按数值比，第2页 排在 第10页 前面"""
        name = os.path.basename(path)
        return [int(t) if t.isdigit() else t.lower() for t in re.split(r'(\d+)', name)]

    def collect_images(src_dir, out_dir, recursive):
        """收集待处理图片；输出目录自身要排除，避免把结果又当原图处理一遍"""
        out_abs = os.path.normcase(os.path.abspath(out_dir))

        def in_out(path):
            p = os.path.normcase(os.path.abspath(path))
            return p == out_abs or p.startswith(out_abs + os.sep)

        found = []
        if recursive:
            for root, dirs, files in os.walk(src_dir):
                dirs[:] = sorted(d for d in dirs if not in_out(os.path.join(root, d)))
                for name in files:
                    if os.path.splitext(name)[1].lower() in IMAGE_EXTS:
                        found.append(os.path.join(root, name))
        else:
            for name in os.listdir(src_dir):
                path = os.path.join(src_dir, name)
                if os.path.isfile(path) and os.path.splitext(name)[1].lower() in IMAGE_EXTS:
                    found.append(path)
        found.sort(key=natkey)
        return found

    def image_size(path):
        with Image.open(path) as img:
            return img.size

    def band_count(height, seg_h, overlap):
        """按「不找空白行」算出来的段数，用来在处理前估算要调多少次接口；
        开了空白行下刀之后实际段数可能差一两段"""
        step = max(1, seg_h - overlap)
        top = 0
        count = 0
        while True:
            count += 1
            if min(top + seg_h, height) >= height:
                return count
            top += step

    def blank_rows(img, y0, y1, tol=BLANK_TOL):
        """[y0,y1) 里每一行是不是「空白行」：整行灰度几乎一个色，说明没有文字压在这一行上"""
        width = img.size[0]
        band = img.crop((0, y0, width, y1))
        data = band.convert('L').tobytes()
        band.close()
        return [(max(data[i * width:(i + 1) * width]) - min(data[i * width:(i + 1) * width])) <= tol
                for i in range(y1 - y0)]

    def find_blank_cut(img, cut, search, tol=BLANK_TOL):
        """在 cut±search 里挑一条空白行当真正的下刀位置：取离 cut 最近的那条空白行带的中点
        （一样近就取更宽的那条）。切在空白处，就不会把一行字劈成两半——
        劈开了上下两段各识别出半截乱码，成品里就是一行鬼画符。找不到返回 None。"""
        height = img.size[1]
        lo = max(0, cut - search)
        hi = min(height, cut + search + 1)
        if hi - lo < 2:
            return None
        flags = blank_rows(img, lo, hi, tol)
        best = None
        i = 0
        total = len(flags)
        while i < total:
            if flags[i]:
                j = i
                while j < total and flags[j]:
                    j += 1
                mid = (lo + i + lo + j - 1) // 2
                key = (abs(mid - cut), -(j - i))
                if best is None or key < best[0]:
                    best = (key, mid)
                i = j
            else:
                i += 1
        return best[1] if best else None

    def split_bands(img, seg_h, overlap, search=0, log=None, tol=BLANK_TOL):
        """把长图横切成若干段，相邻段重叠 overlap px；返回 [(top, bottom, 片段图), ...]。
        search>0 时先在理想切割点上下 search px 内找空白行，把刀挪到空白处再切。"""
        width, height = img.size
        bands = []
        top = 0
        while True:
            bottom = min(top + seg_h, height)
            if bottom < height and search > 0:
                blank = find_blank_cut(img, bottom, search, tol)
                if blank is None:
                    if log:
                        log('    y=%d 上下 %dpx 内没找到空白行，这一刀按原位置切，可能切在文字上'
                            '（重叠 %dpx 会保证这行至少在下一段里是全的）' % (bottom, search, overlap))
                else:
                    # 别挪到重叠区下边去，否则两段之间会漏掉内容
                    bottom = max(blank, top + overlap + 1)
                    if log and bottom != min(top + seg_h, height):
                        log('    切割点从 y=%d 挪到空白行 y=%d' % (min(top + seg_h, height), bottom))
            bands.append((top, bottom, img.crop((0, top, width, bottom))))
            if bottom >= height:
                break
            top = max(top + 1, bottom - overlap)
        return bands

    def dst_docx_for(src, src_dir, out_dir):
        """一张图对应一个 word，子目录结构原样镜像"""
        rel = os.path.relpath(src, src_dir)
        return os.path.join(out_dir, os.path.splitext(rel)[0] + '.docx')

    def dst_seg_docx(src, src_dir, out_dir, index):
        """每一段自己的 word（缓存，断点续跑靠它）"""
        rel = os.path.relpath(src, src_dir)
        base = os.path.splitext(rel)[0]
        return os.path.join(out_dir, SEG_SUBDIR, base + '_段%02d.docx' % index)

    # ---------- 百度：取token / 图片转word ----------

    _token_cache = {'token': '', 'ts': 0.0}

    def baidu_token(force=False):
        """百度OCR的 access_token，本地缓存一天"""
        if not force and _token_cache['token'] and time.time() - _token_cache['ts'] < 86400:
            return _token_cache['token']
        if not ocr_api_key or not ocr_secret_key:
            raise ConvertError('缺少 goldtools/plocrak.cfg、plocrsk.cfg（百度OCR的AK/SK）')
        params = {'grant_type': 'client_credentials', 'client_id': ocr_api_key,
                  'client_secret': ocr_secret_key}
        resp = requests.post(BAIDU_TOKEN_URL, params=params, timeout=60).json()
        token = str(resp.get('access_token') or '')
        if not token:
            raise ConvertError('百度OCR取token失败：%s' % resp.get('error_description', resp))
        _token_cache['token'] = token
        _token_cache['ts'] = time.time()
        return token

    def _code_of(data, key='error_code'):
        try:
            return int(data.get(key))
        except (TypeError, ValueError):
            return -1

    def _post_baidu(api_url, payload, timeout=180):
        headers = {'Content-Type': 'application/x-www-form-urlencoded', 'Accept': 'application/json'}
        resp = requests.post(api_url + '?access_token=' + baidu_token(),
                             headers=headers, data=payload, timeout=timeout)
        try:
            return resp.json()
        except ValueError:
            raise ConvertError('百度接口返回的不是JSON（HTTP %s）：%s' % (resp.status_code, resp.text[:200]))

    def baidu_call(api_url, payload, timeout=180):
        """带 token 失效刷新 + QPS 限流重试的百度接口调用"""
        last = '百度接口调用失败'
        for attempt in range(4):
            data = _post_baidu(api_url, payload, timeout)
            code = _code_of(data)
            if code < 0:
                return data
            last = '%s - %s' % (code, data.get('error_msg'))
            if code in TOKEN_RETRY_CODES:
                baidu_token(force=True)
                continue
            if code in RATE_RETRY_CODES and attempt < 3:
                time.sleep(6 * (attempt + 1))
                continue
            break
        raise ConvertError(last)

    def flatten_alpha(img):
        """带透明通道的图先贴到白底上再送接口。直接 convert('RGB') 是把透明通道一丢了之，
        透明区域会变成一块黑，文档图上就是一大片黑疙瘩，OCR 全废。
        返回的是一张新图，不动原图（原图可能是 with Image.open 里的，关掉就不好使了）"""
        if img.mode in ('RGBA', 'LA') or (img.mode == 'P' and 'transparency' in img.info):
            rgba = img.convert('RGBA')
            bg = Image.new('RGB', rgba.size, (255, 255, 255))
            bg.paste(rgba, mask=rgba.split()[-1])
            return bg
        if img.mode in ('RGB', 'L'):
            return img.copy()
        return img.convert('RGB')

    def encode_for_convert(pil_img):
        """PIL图片 -> 百度图片转word要的 base64（接口只认 jpg/jpeg/png/bmp）"""
        img = pil_img if pil_img.mode in ('RGB', 'L') else flatten_alpha(pil_img)
        longest = max(img.size)
        if longest > CONVERT_MAX_SIDE:
            ratio = CONVERT_MAX_SIDE / float(longest)
            img = img.resize((max(1, int(img.size[0] * ratio)),
                              max(1, int(img.size[1] * ratio))), LANCZOS)
        plans = [('PNG', None)] + [('JPEG', q) for q in JPEG_STEPS]
        data = b''
        for fmt, quality in plans:
            buf = BytesIO()
            if fmt == 'PNG':
                img.save(buf, format='PNG')
            else:
                img.save(buf, format='JPEG', quality=quality)
            data = base64.b64encode(buf.getvalue())
            if len(data) <= CONVERT_MAX_BYTES:
                return data
        raise ConvertError('这一段压到最低质量仍有 %.1fMB，超过百度图片转word的 8M 上限'
                           % (len(data) / 1048576.0))

    def doc_convert_request(b64):
        data = baidu_call(DOC_CONVERT_REQ, {'image': b64})
        result = data.get('result') or {}
        task_id = result.get('task_id') or data.get('task_id')
        if not task_id:
            raise ConvertError('百度没返回task_id：%s' % data)
        return str(task_id)

    def doc_convert_word_url(task_id, wait_s=DEFAULT_WAIT, poll_s=DEFAULT_POLL,
                             log=None, stop_check=None):
        """轮询等转word任务做完，返回 docx 的下载地址。
        参考代码是 sleep 固定秒数只问一次，任务慢一点就白跑，这里改成轮询到出结果为止。
        状态码按实测的 1未开始 / 2进行中 / 3成功 判，只有明确的成功码却没给地址、
        或者出现别的码才算失败；状态码缺失（接口偶发返回空 result）时接着等，不冤枉它。"""
        deadline = time.time() + wait_s
        last_percent = None
        while True:
            data = baidu_call(DOC_CONVERT_GET, {'task_id': task_id})
            result = data.get('result') or {}
            word = (result.get('result_data') or {}).get('word')
            if word:
                return word
            ret_code = _code_of(result, 'ret_code')
            ret_msg = result.get('ret_msg') or ''
            percent = result.get('percent')
            if ret_code == RET_SUCCESS:
                raise ConvertError('百度说任务成功了（ret_code=3）却没给word下载地址：%s' % data)
            if ret_code >= 0 and ret_code not in RET_BUSY:
                raise ConvertError('百度转word任务失败（ret_code=%s %s）' % (ret_code, ret_msg or data))
            if time.time() >= deadline:
                raise ConvertError('等百度转word结果超时（%d秒还没做完，ret_code=%s %s %s%%）'
                                   % (wait_s, ret_code, ret_msg, percent))
            if log and percent != last_percent:
                log('    百度转word中（task_id=%s，%s，%s%%）...'
                    % (task_id, ret_msg or '排队中', percent if percent is not None else 0))
                last_percent = percent
            if stop_check and stop_check():
                raise StopRequest()
            time.sleep(poll_s)

    def pic2docx(pil_img, dst_docx, wait_s=DEFAULT_WAIT, poll_s=DEFAULT_POLL,
                 log=None, stop_check=None):
        """一段图片 -> 一个 docx（百度 doc_convert）"""
        task_id = doc_convert_request(encode_for_convert(pil_img))
        url = doc_convert_word_url(task_id, wait_s, poll_s, log=log, stop_check=stop_check)
        r = requests.get(url, timeout=300)
        r.raise_for_status()
        if len(r.content) < 200:
            raise ConvertError('下载的word只有 %d 字节，不是有效的docx' % len(r.content))
        folder = os.path.dirname(dst_docx)
        if folder and not os.path.isdir(folder):
            os.makedirs(folder, exist_ok=True)
        with open(dst_docx, 'wb') as f:
            f.write(r.content)

    def reusable_docx(path):
        """这个 docx 还在、还打得开，就能当缓存用"""
        if not os.path.isfile(path) or os.path.getsize(path) < 200:
            return False
        try:
            docx.Document(path)
        except Exception:
            return False
        return True

    # ---------- docx 段落 ----------

    def _has_image(par):
        el = par._element
        return bool(el.findall('.//' + qn('w:drawing'))) or bool(el.findall('.//' + qn('w:pict')))

    def rewritable(par):
        """这一段能不能安全删改：有文字、且不带图片（表格里的段落本来就不在 doc.paragraphs 里），
        这样去重绝不会碰到百度转出来的图片"""
        return bool(par.text.strip()) and not _has_image(par)

    def text_paragraphs(doc):
        """文档里可以安全删改的纯文本段落"""
        return [par for par in doc.paragraphs if rewritable(par)]

    def delete_par(par):
        el = par._element
        el.getparent().remove(el)

    def set_par_text(par, text):
        """改段落文字，字体格式保留：写进第一个run，其余run清空"""
        if par.runs:
            par.runs[0].text = text
            for run in par.runs[1:]:
                run.text = ''
        else:
            par.add_run(text)

    def norm_key(text):
        """去掉所有空白（OCR 常在字中间插空格），比对时按这个来"""
        return re.sub(r'\s+', '', text)

    def longest_prefix_in(needle, hay, min_len):
        """needle 最长的、且整块出现在 hay 里的前缀有多长；不到 min_len 就当没有。
        「在不在」这个判断对长度是单调的，所以二分找，不用从头试到尾"""
        if len(needle) < min_len or not hay:
            return 0
        lo, hi, best = min_len, len(needle), 0
        while lo <= hi:
            mid = (lo + hi) // 2
            if needle[:mid] in hay:
                best = mid
                lo = mid + 1
            else:
                hi = mid - 1
        return best

    # ---------- 合并 ----------

    def _clean_master(master):
        """python-docx 新建的空白文档自带一个空段，去掉它，免得合并出来的word开头多一空行"""
        pars = master.paragraphs
        if pars and not pars[0].text.strip() and not _has_image(pars[0]):
            delete_par(pars[0])

    def dedupe_joint(master, cur, lines, log=None):
        """接缝去重。
        不能按行比：百度转word时分几段是跟着图片走的，同一句话在上一段是3个段落、
        到了下一段可能被并成1个段落（2026-09-09 拿真图实测就是这样，按行比一个字都对不上）。
        所以按「字」比：把下一段开头这些段落连成一串，看它最长有多长的一块已经出现在上文
        末尾里，就把这一块从下一段开头削掉——整段削完就删段落，削到一半就把剩下的字留着。
        只削一字不差的部分（空白差异不算），带图片的段落碰都不碰。返回削掉多少个字。"""
        tail_pars = text_paragraphs(master)[-lines:]
        head_pars = text_paragraphs(cur)[:lines]
        if not tail_pars or not head_pars:
            return 0
        hay = norm_key(''.join(par.text for par in tail_pars))[-DEDUPE_MAX_CHARS:]
        head_raw = ''.join(par.text for par in head_pars)
        positions = [i for i, ch in enumerate(head_raw) if not ch.isspace()]
        needle = ''.join(head_raw[i] for i in positions)
        hit = longest_prefix_in(needle, hay, DEDUPE_MIN_CHARS)
        if not hit:
            return 0
        cut = positions[hit] if hit < len(positions) else len(head_raw)
        removed = ''
        remain = cut
        for par in head_pars:
            if remain <= 0:
                break
            text = par.text
            if len(text) <= remain:
                remain -= len(text)
                removed += text
                delete_par(par)
            else:
                removed += text[:remain]
                set_par_text(par, text[remain:])
                remain = 0
        if log:
            shown = removed.strip()
            log('    接缝去掉重复的 %d 个字：%s%s'
                % (hit, shown[:60], '...' if len(shown) > 60 else ''))
        return hit

    def merge_seg_docx(seg_paths, dst_docx, dedupe=True, lines=DEFAULT_DEDUPE_LINES,
                       log=None, stop_check=None):
        """按切割顺序把各段 docx 合并成一张图的 word。
        一段一段往主文档里拼，拼之前先做接缝去重：上文每次都从主文档现取，
        所以就算某一段整个被去重削空了，下一个接缝照样能往前找到真正重复的那部分。
        各段的 docx 原件不动，重跑一遍结果一样。
        返回 (削掉的重复字数, 接缝个数)"""
        if not seg_paths:
            raise ConvertError('没有可合并的段word')
        master = docx.Document()
        _clean_master(master)
        composer = Composer(master)
        composer.append(docx.Document(seg_paths[0]))
        removed = 0
        joints = len(seg_paths) - 1
        for index, path in enumerate(seg_paths[1:], 2):
            if stop_check and stop_check():
                raise StopRequest()
            cur = docx.Document(path)
            if dedupe:
                dup = dedupe_joint(master, cur, lines, log=log)
                removed += dup
                if log:
                    log('    接缝 %d/%d 去掉重复 %d 个字' % (index - 1, joints, dup))
            composer.append(cur)
        folder = os.path.dirname(dst_docx)
        if folder and not os.path.isdir(folder):
            os.makedirs(folder, exist_ok=True)
        composer.save(dst_docx)
        return removed, joints

    def merge_all_docx(docx_paths, dst_docx, sep_title=False, log=None):
        """把所有图片的 word 按顺序合并成一个总 word；sep_title=True 时每张图前面加一行
        文件名并另起一页"""
        paths = [p for p in docx_paths if os.path.isfile(p)]
        if not paths:
            raise ConvertError('没有一个word可合并')
        master = docx.Document()
        _clean_master(master)
        composer = Composer(master)
        for index, path in enumerate(paths):
            if sep_title:
                par = master.add_paragraph()
                if index:
                    par.paragraph_format.page_break_before = True
                par.add_run(os.path.splitext(os.path.basename(path))[0]).bold = True
            composer.append(docx.Document(path))
            if log:
                log('    合并 %d/%d：%s' % (index + 1, len(paths), os.path.basename(path)))
        composer.save(dst_docx)
        return len(paths)

    # ---------- 单张图片 ----------

    def convert_one_image(src, src_dir, out_dir, opts, log=None, stop_check=None):
        """一张图：切段 -> 每段转word -> 接缝去重 -> 合并成一个word。
        返回 (段数, 是不是长图, 削掉的重复字数)"""
        long_h = opts['long_h']
        seg_h = opts['seg_h']
        overlap = opts['overlap']
        width, height = image_size(src)
        need_split = height >= long_h or height > CONVERT_MAX_SIDE
        if need_split and height < long_h and log:
            log('    高度 %dpx 超过百度图片转word的最长边 %dpx，虽然没到长图判定值 %dpx 也得切段'
                % (height, CONVERT_MAX_SIDE, long_h))

        with Image.open(src) as img:
            # 透明区贴白底，也顺手把 CMYK/调色板这些接口不认的模式转成RGB；
            # 返回的是独立副本，with 出来原图关掉了也照样能用
            work = flatten_alpha(img)
        if need_split:
            bands = split_bands(work, seg_h, overlap, search=opts.get('cut_search', 0), log=log)
            work.close()  # 切出来的片段是独立副本，整图的内存可以先放掉（超长图能占几百MB）
            if log:
                log('    长图 %dx%d，切 %d 段（每段 %dpx 左右，重叠 %dpx，%s）'
                    % (width, height, len(bands), seg_h, overlap,
                       '切割点自动挪到空白行' if opts.get('cut_search') else '按整段高度切'))
        else:
            bands = [(0, height, work)]  # 不切段时整张图就是唯一的一段，不能提前close
            if log:
                log('    整张 %dx%d，不切段' % (width, height))

        seg_paths = []
        for index, (top, bottom, band) in enumerate(bands, 1):
            if stop_check and stop_check():
                for _, _, b in bands:
                    b.close()
                raise StopRequest()
            seg_path = dst_seg_docx(src, src_dir, out_dir, index)
            seg_paths.append(seg_path)
            if opts['skip_exist'] and reusable_docx(seg_path):
                if log:
                    log('    段 %d/%d (y=%d-%d) 已有word，跳过转换：%s'
                        % (index, len(bands), top, bottom, os.path.basename(seg_path)))
                band.close()
                continue
            if log:
                log('    段 %d/%d (y=%d-%d) 百度图片转word中...' % (index, len(bands), top, bottom))
            try:
                pic2docx(band, seg_path, wait_s=opts['wait'], poll_s=opts['poll'],
                         log=log, stop_check=stop_check)
            finally:
                band.close()
            time.sleep(1)  # 百度转word有QPS限制，段与段之间隔一下

        for _, _, band in bands:
            band.close()

        dst = dst_docx_for(src, src_dir, out_dir)
        dedupe = opts['dedupe'] and overlap > 0
        if opts['dedupe'] and not overlap and len(seg_paths) > 1 and log:
            log('    重叠填的是0，段与段之间本来就不会有重复内容，跳过接缝去重')
        removed, _ = merge_seg_docx(seg_paths, dst, dedupe=dedupe,
                                    lines=opts['dedupe_lines'], log=log, stop_check=stop_check)
        if not opts['keep_seg']:
            for path in seg_paths:
                try:
                    os.remove(path)
                except OSError:
                    pass
        return len(bands), need_split, removed

    # ---------- 界面 ----------

    class Applp2d(object):
        def __init__(self, root):
            self.root = root
            root.title('Rogabet 批量纵向长图转word -(自动切割，转化，合并) ')
            root.geometry('920x760')
            root.minsize(820, 620)

            self.msg_q = queue.Queue()
            self.stop_event = threading.Event()
            self.worker = None
            self.merged_all = ''

            self.var_dir = tk.StringVar()
            self.var_recursive = tk.BooleanVar(value=False)
            self.var_long_h = tk.StringVar(value=str(DEFAULT_LONG_H))
            self.var_seg_h = tk.StringVar(value=str(DEFAULT_SEG_H))
            self.var_overlap = tk.StringVar(value=str(DEFAULT_OVERLAP))
            self.var_cut_search = tk.StringVar(value=str(DEFAULT_CUT_SEARCH))
            self.var_wait = tk.StringVar(value=str(DEFAULT_WAIT))
            self.var_dedupe = tk.BooleanVar(value=DEFAULT_DEDUPE)
            self.var_dedupe_lines = tk.StringVar(value=str(DEFAULT_DEDUPE_LINES))
            self.var_out = tk.StringVar()
            self.var_skip_exist = tk.BooleanVar(value=True)
            self.var_keep_seg = tk.BooleanVar(value=True)
            self.var_merge_all = tk.BooleanVar(value=DEFAULT_MERGE_ALL)
            self.var_sep_title = tk.BooleanVar(value=False)
            self.var_current = tk.StringVar(value='未开始')
            self.var_status = tk.StringVar(value='就绪')

            self._build_ui()
            self._poll()

        def _build_ui(self):
            pad = {'padx': 6, 'pady': 4}

            frm_src = ttk.LabelFrame(self.root, text=' 1. 选择图片目录 ')
            frm_src.pack(fill='x', **pad)
            ttk.Entry(frm_src, textvariable=self.var_dir).pack(side='left', fill='x', expand=True, padx=6, pady=6)
            ttk.Button(frm_src, text='浏览...', width=10, command=self.pick_src).pack(side='left', padx=4)
            ttk.Checkbutton(frm_src, text='包含子目录', variable=self.var_recursive).pack(side='left', padx=4)

            frm_cut = ttk.LabelFrame(self.root, text=' 2. 长图切割 ')
            frm_cut.pack(fill='x', **pad)
            crow1 = ttk.Frame(frm_cut)
            crow1.pack(fill='x', padx=6, pady=4)
            ttk.Label(crow1, text='长图判定：高度达到').pack(side='left', padx=(2, 2))
            ttk.Entry(crow1, textvariable=self.var_long_h, width=7).pack(side='left', padx=2)
            ttk.Label(crow1, text='px 才切段；不到这个高度的图整张当一段直接转word').pack(side='left', padx=6)
            crow2 = ttk.Frame(frm_cut)
            crow2.pack(fill='x', padx=6, pady=(0, 2))
            ttk.Label(crow2, text='每段').pack(side='left', padx=(2, 2))
            ttk.Entry(crow2, textvariable=self.var_seg_h, width=7).pack(side='left', padx=2)
            ttk.Label(crow2, text='px，段间重叠').pack(side='left', padx=6)
            ttk.Entry(crow2, textvariable=self.var_overlap, width=6).pack(side='left', padx=2)
            ttk.Label(crow2, text='px（0=不重叠）；重叠是兜底：万一某一刀切在文字上，'
                                  '被切断的那行至少在下一段里是全的',
                      foreground='#666').pack(side='left', padx=4)
            crow3 = ttk.Frame(frm_cut)
            crow3.pack(fill='x', padx=6, pady=(0, 2))
            ttk.Label(crow3, text='切割点自动挪到空白行：在理想切割点上下').pack(side='left', padx=(2, 2))
            ttk.Entry(crow3, textvariable=self.var_cut_search, width=6).pack(side='left', padx=2)
            ttk.Label(crow3, text='px 内找一行完全空白的地方下刀（0=不挪，就按整段高度切）').pack(side='left', padx=4)
            crow4 = ttk.Frame(frm_cut)
            crow4.pack(fill='x', padx=6, pady=(0, 2))
            ttk.Label(crow4, text='切在文字行上，上下两段会各识别出半截乱码（比如「(中，这，步确生成描」这种），'
                                  '挪到空白行就没这问题；附近实在没有空白行时按原位置切，并在日志里提醒你',
                      foreground='#666').pack(side='left', padx=(4, 0))
            crow5 = ttk.Frame(frm_cut)
            crow5.pack(fill='x', padx=6, pady=(0, 2))
            ttk.Checkbutton(crow5, text='接缝处重复的内容自动去掉',
                            variable=self.var_dedupe).pack(side='left', padx=(2, 2))
            ttk.Label(crow5, text='两侧各比对').pack(side='left', padx=(10, 2))
            ttk.Entry(crow5, textvariable=self.var_dedupe_lines, width=4).pack(side='left', padx=2)
            ttk.Label(crow5, text='段').pack(side='left', padx=2)
            crow6 = ttk.Frame(frm_cut)
            crow6.pack(fill='x', padx=6, pady=(0, 2))
            ttk.Label(crow6, text='重叠区被上下两段各识别一遍，所以要去重。百度分几段是跟着图片走的，'
                                  '同一句话在上一段是3个段落、到下一段可能并成1个，所以按「字」比不按「行」比：'
                                  '下一段开头凡是已经出现在上文末尾的那一整块（至少 %d 个字）削掉，'
                                  '削掉哪些字都写在日志里；带图片的段落碰都不碰' % DEDUPE_MIN_CHARS,
                      foreground='#666').pack(side='left', padx=(4, 0))
            crow7 = ttk.Frame(frm_cut)
            crow7.pack(fill='x', padx=6, pady=(0, 6))
            ttk.Label(crow7, text='每段等百度转word结果最多').pack(side='left', padx=(2, 2))
            ttk.Entry(crow7, textvariable=self.var_wait, width=6).pack(side='left', padx=2)
            ttk.Label(crow7, text='秒（每 %d 秒问一次，没做完接着等；超时算这一段失败，'
                                  '不影响别的段）' % DEFAULT_POLL, foreground='#666').pack(side='left', padx=4)

            frm_out = ttk.LabelFrame(self.root, text=' 3. 输出 ')
            frm_out.pack(fill='x', **pad)
            orow1 = ttk.Frame(frm_out)
            orow1.pack(fill='x', padx=6, pady=4)
            ttk.Label(orow1, text='输出目录').pack(side='left')
            ttk.Entry(orow1, textvariable=self.var_out).pack(side='left', fill='x', expand=True, padx=6)
            ttk.Button(orow1, text='浏览...', width=10, command=self.pick_out).pack(side='left')
            orow2 = ttk.Frame(frm_out)
            orow2.pack(fill='x', padx=6, pady=(0, 2))
            ttk.Checkbutton(orow2, text='跳过已存在的结果（可断点续跑）',
                            variable=self.var_skip_exist).pack(side='left', padx=(2, 6))
            ttk.Checkbutton(orow2, text='保留每段自己的word（在 输出目录\\%s 里）' % SEG_SUBDIR,
                            variable=self.var_keep_seg).pack(side='left', padx=6)
            orow3 = ttk.Frame(frm_out)
            orow3.pack(fill='x', padx=6, pady=(0, 6))
            ttk.Checkbutton(orow3, text='全部处理完后按顺序合并成一个总word：%s' % MERGE_ALL_NAME,
                            variable=self.var_merge_all).pack(side='left', padx=(2, 6))
            ttk.Checkbutton(orow3, text='合并时每张图前面加一行文件名并另起一页',
                            variable=self.var_sep_title).pack(side='left', padx=6)

            frm_run = ttk.LabelFrame(self.root, text=' 4. 运行 ')
            frm_run.pack(fill='x', **pad)
            bar = ttk.Frame(frm_run)
            bar.pack(fill='x', padx=6, pady=4)
            self.btn_start = ttk.Button(bar, text='开始处理', width=12, command=self.start)
            self.btn_start.pack(side='left')
            self.btn_stop = ttk.Button(bar, text='停止', width=8, command=self.stop, state='disabled')
            self.btn_stop.pack(side='left', padx=6)
            ttk.Button(bar, text='打开输出目录', width=14, command=self.open_out).pack(side='left', padx=6)
            ttk.Button(bar, text='打开合并word', width=14, command=self.open_merged).pack(side='left', padx=6)
            ttk.Button(bar, text='清空日志', width=10, command=self.clear_log).pack(side='left', padx=6)
            self.pb = ttk.Progressbar(frm_run, mode='determinate', maximum=100)
            self.pb.pack(fill='x', padx=6, pady=(0, 2))
            ttk.Label(frm_run, textvariable=self.var_current, foreground='#0057b8').pack(anchor='w', padx=8)
            ttk.Label(frm_run, textvariable=self.var_status, foreground='#333').pack(anchor='w', padx=8, pady=(0, 4))

            frm_log = ttk.LabelFrame(self.root, text=' 日志 ')
            frm_log.pack(fill='both', expand=True, **pad)
            self.txt_log = ScrolledText(frm_log, height=16, state='disabled', wrap='none',
                                        font=('Consolas', 9))
            self.txt_log.pack(fill='both', expand=True, padx=6, pady=6)

        # ---------- 选择 ----------
        def pick_src(self):
            d = askdirectory(title='选择包含图片的目录')
            if not d:
                return
            self.var_dir.set(os.path.normpath(d))
            if not self.var_out.get():
                self.var_out.set(self.default_out())

        def pick_out(self):
            d = askdirectory(title='选择输出目录')
            if d:
                self.var_out.set(os.path.normpath(d))

        def default_out(self):
            src = self.var_dir.get().strip()
            return os.path.join(src, '长图转word输出') if src else ''

        def open_out(self):
            out = self.var_out.get().strip()
            if out and os.path.isdir(out):
                os.startfile(out)
            else:
                messagebox.showwarning('提示', '输出目录还不存在')

        def open_merged(self):
            if self.merged_all and os.path.isfile(self.merged_all):
                os.startfile(self.merged_all)
            else:
                messagebox.showwarning('提示', '还没有合并出总word（%s）' % MERGE_ALL_NAME)

        def clear_log(self):
            self.txt_log.configure(state='normal')
            self.txt_log.delete('1.0', 'end')
            self.txt_log.configure(state='disabled')

        # ---------- 参数校验 ----------
        def read_opts(self):
            """界面上的数字参数，不合法就弹提示并返回 None"""
            try:
                long_h = int(self.var_long_h.get().strip())
                seg_h = int(self.var_seg_h.get().strip())
                overlap = int(self.var_overlap.get().strip())
                cut_search = int(self.var_cut_search.get().strip())
                wait = int(self.var_wait.get().strip())
                dedupe_lines = int(self.var_dedupe_lines.get().strip())
            except ValueError:
                messagebox.showwarning('提示', '「长图判定」「每段高度」「段间重叠」「找空白行范围」'
                                               '「等待秒数」「比对段数」都要填整数')
                return None
            if long_h < 300:
                messagebox.showwarning('提示', '长图判定高度太小，请填 300 以上（推荐 %d）' % DEFAULT_LONG_H)
                return None
            if seg_h < 300:
                messagebox.showwarning('提示', '每段高度太小，请填 300 以上（推荐 %d）' % DEFAULT_SEG_H)
                return None
            if overlap < 0 or overlap * 2 >= seg_h:
                messagebox.showwarning('提示', '段间重叠要在 0 到每段高度的一半之间（推荐 %d）' % DEFAULT_OVERLAP)
                return None
            if cut_search < 0 or cut_search >= seg_h - overlap:
                messagebox.showwarning('提示', '找空白行的范围要填 0 到 %d 之间（推荐 %d）；'
                                               '填太大切割点会挪得太远，段高就不匀了'
                                       % (seg_h - overlap - 1, DEFAULT_CUT_SEARCH))
                return None
            if wait < 20 or wait > 3600:
                messagebox.showwarning('提示', '等待秒数要填 20 到 3600（推荐 %d）' % DEFAULT_WAIT)
                return None
            if dedupe_lines < 1 or dedupe_lines > 50:
                messagebox.showwarning('提示', '接缝比对段数要填 1 到 50（推荐 %d）' % DEFAULT_DEDUPE_LINES)
                return None
            return {'long_h': long_h, 'seg_h': seg_h, 'overlap': overlap, 'wait': wait,
                    'poll': DEFAULT_POLL, 'cut_search': cut_search,
                    'dedupe': bool(self.var_dedupe.get()),
                    'dedupe_lines': dedupe_lines,
                    'skip_exist': bool(self.var_skip_exist.get()),
                    'keep_seg': bool(self.var_keep_seg.get()),
                    'merge_all': bool(self.var_merge_all.get()),
                    'sep_title': bool(self.var_sep_title.get())}

        # ---------- 运行 ----------
        def start(self):
            src_dir = self.var_dir.get().strip()
            if not src_dir or not os.path.isdir(src_dir):
                messagebox.showwarning('提示', '请选择有效的图片目录')
                return
            if not ocr_api_key or not ocr_secret_key:
                messagebox.showerror('错误', '缺少 goldtools/plocrak.cfg、plocrsk.cfg（百度OCR的AK/SK），'
                                             '图片转word没法调')
                return
            opts = self.read_opts()
            if opts is None:
                return

            out_dir = self.var_out.get().strip() or self.default_out()
            self.var_out.set(out_dir)
            if os.path.normcase(os.path.abspath(out_dir)) == os.path.normcase(os.path.abspath(src_dir)):
                messagebox.showwarning('提示', '输出目录不能和图片目录相同，请另选一个')
                return

            files = collect_images(src_dir, out_dir, self.var_recursive.get())
            if not files:
                messagebox.showinfo('提示', '该目录下没有找到图片（%s）' % '、'.join(IMAGE_EXTS))
                return

            total_seg = 0
            long_pics = 0
            for path in files:
                try:
                    height = image_size(path)[1]
                except Exception:
                    total_seg += 1
                    continue
                if height >= opts['long_h'] or height > CONVERT_MAX_SIDE:
                    long_pics += 1
                    total_seg += band_count(height, opts['seg_h'], opts['overlap'])
                else:
                    total_seg += 1
            if opts['dedupe'] and opts['overlap'] > 0:
                dedupe_desc = ('接缝处重复的内容自动去掉（按字比对，两侧各取 %d 段，'
                               '至少 %d 个字才算重复，削掉的字都写进日志）'
                               % (opts['dedupe_lines'], DEDUPE_MIN_CHARS))
            elif opts['dedupe']:
                dedupe_desc = '重叠填的是0，段与段之间不会有重复内容，接缝去重用不上'
            else:
                dedupe_desc = '不做接缝去重，重叠部分的重复文字会原样留在word里'
            cut_desc = ('切割点在理想位置上下 %dpx 内自动挪到空白行下刀，不把一行字劈成两半'
                        % opts['cut_search']) if opts['cut_search'] else '切割点不挪，就按整段高度切'

            if not messagebox.askokcancel(
                    '确认', '共 %d 张图片（长图 %d 张），按每段 %dpx、重叠 %dpx 切，预计 %d 段。\n'
                            '%s。\n%s。\n\n'
                            '将调用百度图片转word约 %d 次（不调别的大模型）。\n'
                            '每张图输出一个 word 到：\n%s\n'
                            '%s\n\n确定开始？'
                            % (len(files), long_pics, opts['seg_h'], opts['overlap'], total_seg,
                               cut_desc, dedupe_desc, total_seg, out_dir,
                               '全部做完再按顺序合并成 %s' % MERGE_ALL_NAME if opts['merge_all']
                               else '不做最后的总合并')):
                return

            self.merged_all = ''
            self.stop_event.clear()
            self.btn_start.configure(state='disabled')
            self.btn_stop.configure(state='normal')
            self.pb.configure(maximum=len(files), value=0)
            self.var_status.set('处理中...')
            self.log('目录：%s' % src_dir)
            self.log('切割：高度达到 %dpx 切段，每段 %dpx，段间重叠 %dpx；每段最多等 %d 秒'
                     % (opts['long_h'], opts['seg_h'], opts['overlap'], opts['wait']))
            self.log('下刀位置：%s' % cut_desc)
            self.log('接缝去重：%s' % dedupe_desc)
            self.log('共 %d 张图片，预计 %d 段、%d 个接缝，输出到：%s'
                     % (len(files), total_seg, max(0, total_seg - len(files)), out_dir))

            self.worker = threading.Thread(target=self._run, args=(files, src_dir, out_dir, opts))
            self.worker.daemon = True
            self.worker.start()

        def stop(self):
            self.stop_event.set()
            self.log('已请求停止，正在等当前这一段结束...')

        def _run(self, files, src_dir, out_dir, opts):
            ok = fail = skip = long_pics = total_seg = removed = 0
            stopped = False
            made_docs = []
            t0 = time.time()
            total = len(files)
            try:
                os.makedirs(out_dir, exist_ok=True)
            except Exception as e:
                self.post('log', '创建输出目录失败：%s' % e)
                self.post('done', dict(ok=0, fail=0, skip=total, long_pics=0, total_seg=0, removed=0,
                                       merged=0, cost=time.time() - t0, fatal=True, stopped=False))
                return

            for idx, src in enumerate(files, 1):
                if self.stop_event.is_set():
                    self.post('log', '已停止，未处理 %d 张。' % (total - idx + 1))
                    stopped = True
                    break
                rel = os.path.relpath(src, src_dir)
                dst = dst_docx_for(src, src_dir, out_dir)
                self.post('current', '[%d/%d] %s' % (idx, total, rel))
                if opts['skip_exist'] and reusable_docx(dst):
                    skip += 1
                    made_docs.append(dst)
                    self.post('log', '跳过（已存在）：%s' % rel)
                    self.post('progress', idx)
                    continue
                try:
                    nseg, is_long, dup = convert_one_image(
                        src, src_dir, out_dir, opts,
                        log=lambda text: self.post('log', text),
                        stop_check=self.stop_event.is_set)
                    ok += 1
                    total_seg += nseg
                    if is_long:
                        long_pics += 1
                    removed += dup
                    made_docs.append(dst)
                    self.post('log', '成功：%s  ->  %s（%s，%d 段%s）'
                              % (rel, os.path.relpath(dst, out_dir),
                                 '长图' if is_long else '整张', nseg,
                                 '' if nseg < 2 else '，接缝削掉重复 %d 个字' % dup))
                except StopRequest:
                    self.post('log', '已停止：%s 中途停下，未输出。' % rel)
                    stopped = True
                    break
                except Exception as e:
                    fail += 1
                    self.post('log', '失败：%s  |  %s' % (rel, e))
                self.post('progress', idx)

            merged = 0
            if opts['merge_all'] and made_docs:
                merged_path = os.path.join(out_dir, MERGE_ALL_NAME)
                self.post('current', '按顺序合并 %d 个word...' % len(made_docs))
                try:
                    merged = merge_all_docx(made_docs, merged_path, sep_title=opts['sep_title'],
                                            log=lambda text: self.post('log', text))
                    self.merged_all = merged_path
                    self.post('log', '合并完成：%d 个word  ->  %s' % (merged, merged_path))
                except Exception as e:
                    self.post('log', '总合并失败：%s' % e)
            elif opts['merge_all']:
                self.post('log', '没有一个成功的word，跳过总合并。')

            self.post('done', dict(ok=ok, fail=fail, skip=skip, long_pics=long_pics,
                                   total_seg=total_seg, removed=removed, merged=merged,
                                   cost=time.time() - t0, fatal=False, stopped=stopped))

        # ---------- 线程 -> 界面 ----------
        def post(self, kind, *args):
            self.msg_q.put((kind,) + args)

        def _poll(self):
            try:
                while True:
                    msg = self.msg_q.get_nowait()
                    self._handle(msg)
            except queue.Empty:
                pass
            self.root.after(120, self._poll)

        def _handle(self, msg):
            kind = msg[0]
            if kind == 'log':
                self.log(msg[1])
            elif kind == 'current':
                self.var_current.set(msg[1])
            elif kind == 'progress':
                self.pb['value'] = msg[1]
            elif kind == 'done':
                self.btn_start.configure(state='normal')
                self.btn_stop.configure(state='disabled')
                self.var_current.set('已结束')
                st = msg[1]
                text = ('完成：成功 %d 张（长图 %d 张，共 %d 段），失败 %d，跳过 %d，'
                        '接缝削掉重复 %d 个字，合并 %d 个word，用时 %.1f 秒'
                        % (st['ok'], st['long_pics'], st['total_seg'], st['fail'], st['skip'],
                           st['removed'], st['merged'], st['cost']))
                if st['stopped']:
                    text = '已停止。' + text
                self.var_status.set(text)
                self.log(text)
                if st['fatal']:
                    messagebox.showerror('错误', '未能开始处理，请看日志')
                    return
                if not (st['ok'] or st['skip']):
                    return
                tip = text
                if st['removed'] == 0 and st['total_seg'] > st['ok'] + st['skip']:
                    tip += ('\n\n注意：切了段却一个字都没削掉。要么是重叠填了0（本来就没重复），'
                            '要么是重叠区两边识别得不完全一样，接缝处可能还留着重复内容，请人工再看一眼。')
                if self.merged_all:
                    if messagebox.askyesno('完成', tip + '\n\n打开合并出来的总word？'):
                        os.startfile(self.merged_all)
                elif messagebox.askyesno('完成', tip + '\n\n打开输出目录？'):
                    self.open_out()

        def log(self, text):
            self.txt_log.configure(state='normal')
            self.txt_log.insert('end', '[%s] %s\n' % (time.strftime('%H:%M:%S'), text))
            self.txt_log.see('end')
            self.txt_log.configure(state='disabled')


    root66 = Toplevel()
    Applp2d(root66)
    root66.mainloop()




