def replacedanyuanword():  # all xlsx all sheets
    file_path = e1workwhereth.get()
    old_word = e2oldword.get()
    new_word = e3newword.get()

    file_list = os.listdir(file_path)

    for file_name in file_list:
        # 跳过系统临时文件和非Excel格式文件
        if file_name.startswith('~$') or not file_name.endswith(('.xlsx', '.xlsm')):
            continue

        file_paths = os.path.join(file_path, file_name)

        try:
            workbook = openpyxl.load_workbook(file_paths)
        except Exception:
            # 忽略无法打开的损坏文件，保证程序继续运行
            continue

        # 遍历工作簿中的所有工作表
        for sheet in workbook.worksheets:
            for row in sheet.iter_rows():
                for cell in row:
                    # 仅处理字符串类型的单元格，避免将数字或日期误转为文本
                    if isinstance(cell.value, str):
                        if old_word in cell.value:
                            cell.value = cell.value.replace(old_word, new_word)

        # 所有工作表处理完毕后，统一保存并关闭文件
        workbook.save(file_paths)
        workbook.close()

    runingpb()
    showinfo('提示', '文件处理完毕')

from docx.shared import Inches
def insertimg2wordmanya():
    showinfo('提示', '老的关键词输入后，新关键词输入某个图片地址，然后选择很多word所在文件夹，最后输出那些文档都把老的关键词换成图片了.')

    # file_path = workwhere
    file_path =e1workwhereth.get()
    file_list = os.listdir(file_path)
    def doOne(doc):
        old_keyword = e2oldword.get()
        img = e3newword.get()

        def center_insert_img(doc):
            # # 在单元格中插入图片
            for table in doc.tables:  # 遍历表格中的每一行
                for row in table.rows:   # 遍历行中的每一个单元格
                    for cell in row.cells:
                        if old_keyword in cell.text:
                            cell.text = cell.text.replace('\n', '')   # 替换单元格中的内容
                            cell.text = cell.text.replace(old_keyword, '')
                            run=cell.paragraphs[0].add_run('')
                            run.add_break()
                            run.add_picture(img, width=Inches(1.1))
            for paragraph in doc.paragraphs:
                # 根据文档中的占位符定位图片插入的位置
                if old_keyword in paragraph.text:
                    # 把占位符去掉
                    paragraph.text = paragraph.text.replace(old_keyword, '')
                    run = paragraph.add_run('')
                    run.add_break()
                    # 添加图片并指定大小
                    run.add_picture(img, width=Inches(1.5))

        doc2 = docx.Document(doc)  # 插入图片居中
        center_insert_img(doc2)  # 保存结果文件
        doc2.save(doc)

    dir_path = file_path
    files = os.listdir(path=dir_path)
    for file in files:
        try:
            print(os.path.join(dir_path, file))
            if '.docx' in file:
                doOne(os.path.join(dir_path, file))
            # print(os.path.join(dir_path, file))
            print("{}已经修改成功".format(file))
        except ValueError as e:
            print("{}发生如下错误\n{}".format(file, e))
    runingpb()
    showinfo('提示', '文件处理完毕')

def replacedanyuanword_docx():             #docx
    import xlwings as xw
    # showinfo('notice','选择需要处理目录，填写老词语和新内容，进行替换.')
    # file_path =workwhere
    file_path = e1workwhereth.get()
    file_list = os.listdir(file_path)
    def replace_words(path, old, new):
        if path.endswith(".docx"):
            # 不支持读取doc格式的文件
            doc = docx.Document(path)

            #正文文字替换
            for paragraph in doc.paragraphs:
                for run in paragraph.runs:
                    if run.text:
                        run.text = run.text.replace(old, new)
                doc.save(path)

                time.sleep(0.2)
            try:#word里表格的文字替换
                for table in doc.tables:
                    # 遍历表格中的每一行
                    for row in table.rows:
                        # 遍历行中的每一个单元格
                        for cell in row.cells:
                            # 替换单元格中的内容
                            cell.text = cell.text.replace(old, new)
                doc.save(path)
            except:
                pass
                time.sleep(0.2)
            try:#word里页眉的文字替换
                header = doc.sections[0].header
                for paragraph in header.paragraphs:
                    for run in paragraph.runs:
                        # run.font.size = Pt(14)  # 设置字体大小
                        # 替换单元格中的内容
                        #     run.add_picture('logo.jpg')
                        run.text = run.text.replace(old, new)
                doc.save(path)
            except:
                pass
        else:
            raise ValueError("只支持docx文件格式!")

    dir_path = file_path
    old_keyword = e2oldword.get()
    new_keyword = e3newword.get()
    files = os.listdir(path=dir_path)
    for file in files:
        try:
            replace_words(os.path.join(dir_path, file), old_keyword, new_keyword)
            print("{}已经修改成功".format(file))
        except ValueError as e:
            print("{}发生如下错误\n{}".format(file, e))
    runingpb()
    showinfo('提示', '文件处理完毕')
