def data_match():
    import pandas as pd
    import xlrd
    try:
        path = os.getcwd()
        os.chdir(path)
        # global table_a_path
        # global table_b_path
        table_a_path = e1filename1.get()

        # 打开文件方式1：
        work_bookAA = xlrd.open_workbook(table_a_path)
        # 获取工做簿全部sheet表对象名称
        sheetNameAA01 = work_bookAA.sheet_names()[0]
        print(sheetNameAA01)
        e2sheetname1.delete(0, 'end')
        e2sheetname1.insert(0,sheetNameAA01)
        sheet_a_name = e2sheetname1.get()

        A_id = e3baselie1.get()  # A主要字段
        table_a = pd.read_excel(table_a_path,sheet_name = sheet_a_name,converters={A_id:str}).dropna(axis=1,how='all')

        table_b_path = e4filename2.get()
        # 打开文件方式1：
        work_bookBB = xlrd.open_workbook(table_b_path)
        # 获取工做簿全部sheet表对象名称
        sheetNameBB01 = work_bookBB.sheet_names()[0]
        print(sheetNameBB01)
        e5sheetnameb1.delete(0, 'end')
        e5sheetnameb1.insert(0, sheetNameBB01)

        sheet_b_name = e5sheetnameb1.get()
        B_id = e6base2lie.get()  # B 主要字段
        target_col = e7duibi.get()  #比较字段
        table_b = pd.read_excel(table_b_path, sheet_name=sheet_b_name, converters={B_id: str}).dropna(axis=1, how='all')
        table_b_2 = table_b.groupby(B_id)[target_col].sum().reset_index()
        table_c = table_a.merge(right=table_b_2,how='left',left_on=A_id,right_on=B_id)
        table_c.to_excel(os.getcwd()+'\\worktemp\\对比结果.xlsx',index=False)
        os.startfile(os.getcwd()+'\\worktemp\\对比结果.xlsx')
    except:
        showinfo('error','无法比较！')
def wordpdf_match3():
    matchwordpdffileA=e1filename1.get()
    matchwordpdffileB=e4filename2.get()
    def get_access_token():
        API_KEY =  plocrakvar
        SECRET_KEY = plocrskvar
        # APP_ID =plocridvar

        """ 使用 AK，SK 生成鉴权签名（Access Token）   :return: access_token，或是None(如果错误)    """
        url = "https://aip.baidubce.com/oauth/2.0/token"
        params = {"grant_type": "client_credentials", "client_id": API_KEY, "client_secret": SECRET_KEY}
        return str(requests.post(url, params=params).json().get("access_token"))
    def match3_2txt():
        request_url = "https://aip.baidubce.com/file/2.0/brain/online/v1/textdiff/create_task"
        # 二进制方式打开图片文件
        f1 = matchwordpdffileA
        f2 = matchwordpdffileB

        body = {
            "baseFile": (os.path.basename(f1), open(f1, 'rb'), "multipart/form-data"),
            "compareFile": (os.path.basename(f2), open(f2, 'rb'), "multipart/form-data"),
        }

        data = {
            "sealRecognition": False,
            "handWritingRecognition": False
        }
        access_token = get_access_token()
        request_url2 = f"{request_url}?access_token={access_token}"
        response = requests.post(request_url2, data=data, files=body)
        if response:
            global showmatch3taskid
            showmatch3taskid=response.json()['result']['taskId']
            print(showmatch3taskid)
            print(type(showmatch3taskid))

    match3_2txt()
    time.sleep(10)
    # try:
    #     os.remove("diffwhere.txt")
    # except:
    #     pass
    output_filenamebdbg = asksaveasfilename(title='选择比对报告PDF保存位置',initialfile='比对报告.pdf', defaultextension='.pdf',filetypes=[('pdf files', '.pdf'),('txt files', '.txt'),('pptx files', '.pptx')])
    def match3_2txt_next():
        request_host = "https://aip.baidubce.com/file/2.0/brain/online/v1/textdiff/query_task"
        params = {"taskId": showmatch3taskid}

        access_token = get_access_token()
        request_url = f"{request_host}?access_token={access_token}"
        response = requests.post(request_url, params=params, files=params)
        # if response:
        #     print(response.json()['result']['subTaskList'][0]['diffItemList'])
        # try:
        global mybiduibgget
        mybiduibgget = response.json()['result']['subTaskList'][0]['reportOssURL']
        print(mybiduibgget)

    match3_2txt_next()
    time.sleep(45)
    runingpb()
    match3_2txt_next()
    # urllib.request.urlretrieve(mybiduibgget, output_filenamebdbg)
    responsemyfile = requests.get(mybiduibgget)
    with open(output_filenamebdbg, 'wb') as file:
        # 将图片内容写入文件
        file.write(responsemyfile.content)
    time.sleep(3)
    runingpb()
    os.startfile(output_filenamebdbg)


def data_match4():
    import shutil
    import openpyxl as vb
    from openpyxl.styles import PatternFill, Font
    folder_path = askdirectory(title="请选择包含Excel文件的文件夹")
    if not folder_path:
        return

    all_files = [f for f in os.listdir(folder_path) if f.endswith('.xlsx') and not f.startswith('~$')]

    if len(all_files) > 12:
        showwarning("提示", "最多支持12个文件一起比对，将自动截取前12个文件。")
        all_files = all_files[:12]

    if len(all_files) < 2:
        showerror("错误", "文件夹内至少需要2个xlsx文件才能进行比对。")
        return

    yellow_fill = PatternFill("solid", fgColor="FFFF00")
    blue_font = Font(color="0000FF", bold=True)

    files_info = []
    for f in all_files:
        path = os.path.join(folder_path, f)
        try:
            wb_val = vb.load_workbook(path, data_only=True)
            wb_fmt = vb.load_workbook(path)
            files_info.append({
                'filename': f,
                'path': path,
                'wb_val': wb_val,
                'wb_fmt': wb_fmt
            })
        except Exception as e:
            showerror("错误", f"加载文件 {f} 失败: {str(e)}")
            return

    # 以第一个文件为标准
    base_info = files_info[0]
    base_wb_val = base_info['wb_val']

    # 遍历第一个文件的每一个sheet，按索引位置进行匹配
    for sheet_index in range(len(base_wb_val.worksheets)):
        base_ws_val = base_wb_val.worksheets[sheet_index]

        # 收集其他文件中对应索引位置的sheet
        compare_list = []
        max_row = base_ws_val.max_row or 0
        max_col = base_ws_val.max_column or 0

        for info in files_info[1:]:
            if sheet_index < len(info['wb_val'].worksheets):
                ws_val = info['wb_val'].worksheets[sheet_index]
                # 取所有参与比对文件的最大行列范围，确保不遗漏差异数据
                max_row = max(max_row, ws_val.max_row or 0)
                max_col = max(max_col, ws_val.max_column or 0)
                compare_list.append(info)

        # 如果没有其他文件包含该索引的sheet，则跳过该sheet的比对
        if not compare_list:
            continue

        # 逐单元格比对差异
        for r in range(1, max_row + 1):
            for c in range(1, max_col + 1):
                base_cell_val = base_ws_val.cell(r, c).value
                base_val_str = '' if base_cell_val is None else str(base_cell_val)

                has_diff = False
                for info in compare_list:
                    ws_val = info['wb_val'].worksheets[sheet_index]
                    cell_val = ws_val.cell(r, c).value
                    cmp_val_str = '' if cell_val is None else str(cell_val)
                    if cmp_val_str != base_val_str:
                        has_diff = True
                        break

                # 如果存在差异，则高亮基准文件及对比文件中的对应单元格
                if has_diff:
                    # 高亮基准文件
                    base_ws_fmt = base_info['wb_fmt'].worksheets[sheet_index]
                    base_ws_fmt.cell(r, c).fill = yellow_fill
                    base_ws_fmt.cell(r, c).font = blue_font

                    # 高亮对比文件中存在差异的单元格
                    for info in compare_list:
                        ws_val = info['wb_val'].worksheets[sheet_index]
                        cell_val = ws_val.cell(r, c).value
                        cmp_val_str = '' if cell_val is None else str(cell_val)
                        if cmp_val_str != base_val_str:
                            ws_fmt = info['wb_fmt'].worksheets[sheet_index]
                            ws_fmt.cell(r, c).fill = yellow_fill
                            ws_fmt.cell(r, c).font = blue_font

    # 保存结果文件
    for info in files_info:
        base_name, ext = os.path.splitext(info['filename'])
        new_filename = f"{base_name}_差异{ext}"
        dest_path = os.path.join(folder_path, new_filename)

        try:
            info['wb_fmt'].save(dest_path)
        except Exception as e:
            showerror("错误", f"保存文件 {new_filename} 失败: {str(e)}")
            return

    showinfo("完成", "比对完成，差异文件已生成在原目录下。")

def data_match2():# two files
    from openpyxl.styles import PatternFill
    from openpyxl.styles import colors
    from openpyxl.styles import Font
    import openpyxl as vb
    import xlrd
    workbook_a = vb.load_workbook(e1filename1.get(),data_only=True) #,data_only=True 读取数值，丢失公式

    workbook_b = vb.load_workbook(e4filename2.get(),data_only=True) #,data_only=True

    #A sheet
    work_bookAA = xlrd.open_workbook(e1filename1.get())
    # 获取工做簿全部sheet表对象名称
    sheetNameAA01 = work_bookAA.sheet_names()[0]
    print(sheetNameAA01)
    e2sheetname1.delete(0, 'end')
    e2sheetname1.insert(0, sheetNameAA01)
    sheet_a_name2 = e2sheetname1.get()
    #B sheet
    work_bookBB = xlrd.open_workbook(e4filename2.get())
    # 获取工做簿全部sheet表对象名称
    sheetNameBB01 = work_bookBB.sheet_names()[0]
    print(sheetNameBB01)
    e5sheetnameb1.delete(0, 'end')
    e5sheetnameb1.insert(0, sheetNameBB01)

    sheet_b_name2 = e5sheetnameb1.get()

    sheet_a = workbook_a[sheet_a_name2]
    sheet_b = workbook_b[sheet_b_name2]
    maxrow = sheet_a.max_row
    maxcolumn = sheet_b.max_column
    for i in range(1, maxrow+1):
        for j in range(1, maxcolumn+1):
            cell_a = sheet_a.cell(i, j)
            cell_b = sheet_b.cell(i, j)
            if cell_a.value != cell_b.value:
                cell_a.fill = PatternFill("solid", fgColor="FFFF00")
                cell_a.font = Font(color=colors.BLUE, bold=True)
                cell_b.fill = PatternFill("solid", fgColor="FFFF00")
                cell_b.font = Font(color=colors.BLUE, bold=True)
    workbook_a.save(os.getcwd()+'\\worktemp\\表A.xlsx')
    workbook_b.save(os.getcwd()+'\\worktemp\\表B.xlsx')
    # os.system("explorer.exe %s" % (os.getcwd()+'\\worktemp\\'))
    time.sleep(1)
    shutil.copy(os.getcwd() + '\\worktemp\\表A.xlsx', e1filename1.get().replace('.xlsx', '2A.xlsx'))
    shutil.copy(os.getcwd() + '\\worktemp\\表B.xlsx',e4filename2.get().replace('.xlsx', '2B.xlsx'))
    time.sleep(5)
    os.remove(os.getcwd() + '\\worktemp\\表A.xlsx')
    os.remove(os.getcwd() + '\\worktemp\\表B.xlsx')

