def comparemulutxt2026():
    import os
    import sys
    import filecmp
    import difflib
    import tkinter as tk
    from tkinter import ttk, filedialog, messagebox

    # 修复1: 使用 Toplevel 并传入 root 作为父窗口，避免产生多余的独立空白弹窗
    compare_window = tk.Toplevel(root)
    compare_window.title("综合比对工具")
    compare_window.geometry("1200x800")

    class TreeNode:
        def __init__(self, name, path, is_dir, side):
            self.name = name
            self.path = path
            self.is_dir = is_dir
            self.side = side
            self.children = []
            self.status = 'equal'
            self.is_expanded = False
            self.tag_name = ""
            self.child_elide_tag = ""
            self.indent = 0

    class DirTreeWidget(tk.Text):
        def __init__(self, master, **kwargs):
            super().__init__(master, wrap=tk.NONE, state=tk.DISABLED, cursor="arrow", **kwargs)
            self.nodes = {}
            self.tag_counter = 0
            self.bind("<Button-1>", self.on_click)

            self.tag_configure('only_left', background='#ffd2d2', foreground='#000000')
            self.tag_configure('only_right', background='#d2ffd2', foreground='#000000')
            self.tag_configure('diff', background='#ffffb4', foreground='#000000')
            self.tag_configure('equal', background='#ffffff', foreground='#000000')
            self.tag_configure('dir_equal', background='#f8f9fa', foreground='#000000')

        def clear_tree(self):
            self.config(state=tk.NORMAL)
            self.delete(1.0, tk.END)
            self.nodes.clear()
            self.tag_counter = 0
            self.config(state=tk.DISABLED)

        def build_tree(self, root_node):
            self.clear_tree()
            self.config(state=tk.NORMAL)
            self._insert_node(root_node, 0, [])
            self.config(state=tk.DISABLED)

        def _insert_node(self, node, indent, elide_tags):
            node.indent = indent
            tag_name = f"node_{self.tag_counter}"
            self.tag_counter += 1
            node.tag_name = tag_name
            self.nodes[tag_name] = node

            if node.is_dir:
                icon = "[-] " if node.is_expanded else "[+] "
            else:
                icon = "    "

            line_text = "  " * indent + icon + node.name

            if node.is_dir:
                bg_tag = 'dir_equal'
                if node.status == 'diff':
                    bg_tag = 'diff'
                elif node.status == 'only_left':
                    bg_tag = 'only_left'
                elif node.status == 'only_right':
                    bg_tag = 'only_right'
            else:
                bg_tag = node.status if node.status in ['only_left', 'only_right', 'diff', 'equal'] else 'equal'

            tags_to_apply = [tag_name, bg_tag] + elide_tags
            self.insert(tk.END, line_text + "\n", tuple(tags_to_apply))

            if node.is_dir and node.is_expanded:
                child_elide_tag = f"elide_{self.tag_counter}"
                self.tag_counter += 1
                self.tag_configure(child_elide_tag, elide=False)
                node.child_elide_tag = child_elide_tag

                new_elide_tags = elide_tags + [child_elide_tag]
                for child in node.children:
                    self._insert_node(child, indent + 1, new_elide_tags)

        def on_click(self, event):
            index = self.index(f"@{event.x},{event.y}")
            tags = self.tag_names(index)
            for tag in tags:
                if tag.startswith("node_"):
                    node = self.nodes.get(tag)
                    if node and node.is_dir:
                        node.is_expanded = not node.is_expanded
                        if hasattr(node, 'child_elide_tag'):
                            self.tag_configure(node.child_elide_tag, elide=not node.is_expanded)

                        icon = "[-] " if node.is_expanded else "[+] "
                        new_line_text = "  " * node.indent + icon + node.name

                        line_start = f"{tag}.first linestart"
                        line_end = f"{tag}.first lineend"
                        current_tags = self.tag_names(f"{tag}.first")

                        self.config(state=tk.NORMAL)
                        self.delete(line_start, line_end)
                        self.insert(line_start, new_line_text, current_tags)
                        self.config(state=tk.DISABLED)
                    break

    class TextDiffWidget(tk.Frame):
        def __init__(self, master):
            super().__init__(master)
            self.file1_path = ""
            self.file2_path = ""
            self.syncing_scroll = False
            self.init_ui()

        def init_ui(self):
            btn_frame = tk.Frame(self)
            btn_frame.pack(fill=tk.X, padx=5, pady=5)

            self.btn_select1 = tk.Button(btn_frame, text="选择文本1", command=self.select_file1)
            self.btn_select1.pack(side=tk.LEFT, padx=5)

            self.btn_select2 = tk.Button(btn_frame, text="选择文本2", command=self.select_file2)
            self.btn_select2.pack(side=tk.LEFT, padx=5)

            self.btn_compare = tk.Button(btn_frame, text="开始比对", command=self.compare_texts,
                                         bg="#4CAF50", fg="white", font=("Arial", 10, "bold"))
            self.btn_compare.pack(side=tk.LEFT, padx=5)

            self.label_status = tk.Label(btn_frame, text="请选择两个文本文件", fg="#666666")
            self.label_status.pack(side=tk.LEFT, padx=15)

            paned = tk.PanedWindow(self, orient=tk.HORIZONTAL)
            paned.pack(fill=tk.BOTH, expand=True, padx=5, pady=5)

            left_frame = tk.Frame(paned)
            paned.add(left_frame, width=500)

            self.text1 = tk.Text(left_frame, wrap=tk.CHAR, font=("Consolas", 11), state=tk.DISABLED)
            self.scroll1 = tk.Scrollbar(left_frame, orient=tk.VERTICAL, command=self.text1.yview)
            self.text1.config(yscrollcommand=self.on_scroll_text1)
            self.scroll1.pack(side=tk.RIGHT, fill=tk.Y)
            self.text1.pack(fill=tk.BOTH, expand=True)

            right_frame = tk.Frame(paned)
            paned.add(right_frame, width=500)

            self.text2 = tk.Text(right_frame, wrap=tk.CHAR, font=("Consolas", 11), state=tk.DISABLED)
            self.scroll2 = tk.Scrollbar(right_frame, orient=tk.VERTICAL, command=self.text2.yview)
            self.text2.config(yscrollcommand=self.on_scroll_text2)
            self.scroll2.pack(side=tk.RIGHT, fill=tk.Y)
            self.text2.pack(fill=tk.BOTH, expand=True)

            self.text1.tag_configure('line_equal', background='#ffffff', foreground='#000000')
            self.text1.tag_configure('line_delete', background='#ffeef0', foreground='#000000')
            self.text1.tag_configure('line_replace', background='#fff3cd', foreground='#000000')
            self.text1.tag_configure('inline_del', background='#fdb8c0', foreground='#000000')

            self.text2.tag_configure('line_equal', background='#ffffff', foreground='#000000')
            self.text2.tag_configure('line_insert', background='#e6ffed', foreground='#000000')
            self.text2.tag_configure('line_replace', background='#fff3cd', foreground='#000000')
            self.text2.tag_configure('inline_ins', background='#acf2bd', foreground='#000000')

        def select_file1(self):
            file_path = filedialog.askopenfilename(
                filetypes=[("Text Files", "*.txt *.py *.md *.csv"), ("All Files", "*.*")])
            if file_path:
                self.file1_path = file_path
                self.update_status()

        def select_file2(self):
            file_path = filedialog.askopenfilename(
                filetypes=[("Text Files", "*.txt *.py *.md *.csv"), ("All Files", "*.*")])
            if file_path:
                self.file2_path = file_path
                self.update_status()

        def update_status(self):
            name1 = os.path.basename(self.file1_path) if self.file1_path else "未选择"
            name2 = os.path.basename(self.file2_path) if self.file2_path else "未选择"
            self.label_status.config(text=f"文本1: {name1} | 文本2: {name2}")

        def on_scroll_text1(self, *args):
            if self.syncing_scroll: return
            self.syncing_scroll = True
            first, last = self.text1.yview()
            self.text2.yview_moveto(first)
            self.scroll2.set(first, last)
            self.syncing_scroll = False

        def on_scroll_text2(self, *args):
            if self.syncing_scroll: return
            self.syncing_scroll = True
            first, last = self.text2.yview()
            self.text1.yview_moveto(first)
            self.scroll1.set(first, last)
            self.syncing_scroll = False

        def read_file(self, file_path):
            for encoding in ["utf-8", "gbk", "latin-1"]:
                try:
                    with open(file_path, "r", encoding=encoding) as f:
                        return f.read()
                except UnicodeDecodeError:
                    continue
            raise ValueError("无法识别的文件编码")

        def compare_texts(self):
            if not self.file1_path or not self.file2_path:
                messagebox.showwarning("提示", "请先选择两个文本文件")
                return

            try:
                text1 = self.read_file(self.file1_path)
                text2 = self.read_file(self.file2_path)
            except Exception as e:
                messagebox.showerror("错误", f"读取文件失败: {str(e)}")
                return

            self.text1.config(state=tk.NORMAL)
            self.text2.config(state=tk.NORMAL)
            self.text1.delete(1.0, tk.END)
            self.text2.delete(1.0, tk.END)

            lines1 = text1.splitlines()
            lines2 = text2.splitlines()
            sm = difflib.SequenceMatcher(None, lines1, lines2)

            for tag, i1, i2, j1, j2 in sm.get_opcodes():
                if tag == 'equal':
                    for idx in range(i2 - i1):
                        line = lines1[i1 + idx] + '\n'
                        self.text1.insert(tk.END, line, 'line_equal')
                        self.text2.insert(tk.END, line, 'line_equal')
                elif tag == 'delete':
                    for idx in range(i2 - i1):
                        line = lines1[i1 + idx] + '\n'
                        self.text1.insert(tk.END, line, 'line_delete')
                        self.text2.insert(tk.END, '\n', 'line_equal')
                elif tag == 'insert':
                    for idx in range(j2 - j1):
                        line = lines2[j1 + idx] + '\n'
                        self.text1.insert(tk.END, '\n', 'line_equal')
                        self.text2.insert(tk.END, line, 'line_insert')
                elif tag == 'replace':
                    max_len = max(i2 - i1, j2 - j1)
                    for idx in range(max_len):
                        if idx < (i2 - i1) and idx < (j2 - j1):
                            self.insert_inline_diff(lines1[i1 + idx], lines2[j1 + idx])
                        elif idx < (i2 - i1):
                            line = lines1[i1 + idx] + '\n'
                            self.text1.insert(tk.END, line, 'line_delete')
                            self.text2.insert(tk.END, '\n', 'line_equal')
                        else:
                            line = lines2[j1 + idx] + '\n'
                            self.text1.insert(tk.END, '\n', 'line_equal')
                            self.text2.insert(tk.END, line, 'line_insert')

            self.text1.config(state=tk.DISABLED)
            self.text2.config(state=tk.DISABLED)
            self.text1.yview_moveto(0)
            self.text2.yview_moveto(0)

        def insert_inline_diff(self, line1, line2):
            sm = difflib.SequenceMatcher(None, line1, line2)
            for tag, i1, i2, j1, j2 in sm.get_opcodes():
                if tag == 'equal':
                    text = line1[i1:i2]
                    self.text1.insert(tk.END, text, 'line_replace')
                    self.text2.insert(tk.END, text, 'line_replace')
                elif tag == 'delete':
                    self.text1.insert(tk.END, line1[i1:i2], 'inline_del')
                elif tag == 'insert':
                    self.text2.insert(tk.END, line2[j1:j2], 'inline_ins')
                elif tag == 'replace':
                    self.text1.insert(tk.END, line1[i1:i2], 'inline_del')
                    self.text2.insert(tk.END, line2[j1:j2], 'inline_ins')
            self.text1.insert(tk.END, '\n', 'line_replace')
            self.text2.insert(tk.END, '\n', 'line_replace')

    class DirCompareWidget(tk.Frame):
        def __init__(self, master):
            super().__init__(master)
            self.init_ui()

        def init_ui(self):
            bottom_frame = tk.Frame(self)
            bottom_frame.pack(fill=tk.X, side=tk.BOTTOM, padx=5, pady=5)

            self.btn_compare_dir = tk.Button(bottom_frame, text="开始比对", command=self.compare_directories, height=2)
            self.btn_compare_dir.pack(side=tk.LEFT, fill=tk.X, expand=True, padx=5)

            self.status_entry = tk.Entry(bottom_frame, state="readonly")
            self.status_entry.pack(side=tk.LEFT, fill=tk.X, expand=True, padx=5)
            self.status_entry.insert(0, "请选择左右目录后点击比对")

            paned = tk.PanedWindow(self, orient=tk.HORIZONTAL)
            paned.pack(fill=tk.BOTH, expand=True, padx=5, pady=5)

            self.left_panel = self.create_panel(paned, "left")
            paned.add(self.left_panel["frame"], width=500)

            self.right_panel = self.create_panel(paned, "right")
            paned.add(self.right_panel["frame"], width=500)

        def create_panel(self, master, side):
            frame = tk.Frame(master)

            path_frame = tk.Frame(frame)
            path_frame.pack(fill=tk.X, padx=5, pady=5)

            line_edit = tk.Entry(path_frame)
            line_edit.pack(side=tk.LEFT, fill=tk.X, expand=True, padx=5)

            btn_browse = tk.Button(path_frame, text="浏览", width=8,
                                   command=lambda: self.browse_directory(line_edit, side))
            btn_browse.pack(side=tk.RIGHT, padx=5)

            tree_frame = tk.Frame(frame)
            tree_frame.pack(fill=tk.BOTH, expand=True, padx=5, pady=5)

            tree = DirTreeWidget(tree_frame)
            scroll = tk.Scrollbar(tree_frame, orient=tk.VERTICAL, command=tree.yview)

            if side == "left":
                tree.config(yscrollcommand=lambda f, l: self.sync_scroll(self.left_panel, self.right_panel, f, l))
            else:
                tree.config(yscrollcommand=lambda f, l: self.sync_scroll(self.right_panel, self.left_panel, f, l))

            scroll.pack(side=tk.RIGHT, fill=tk.Y)
            tree.pack(fill=tk.BOTH, expand=True)

            return {
                "frame": frame,
                "line_edit": line_edit,
                "tree": tree,
                "scroll": scroll
            }

        def sync_scroll(self, source_panel, target_panel, first, last):
            source_panel["scroll"].set(first, last)
            target_panel["tree"].yview_moveto(first)
            target_panel["scroll"].set(first, last)

        def browse_directory(self, line_edit, side):
            dir_path = filedialog.askdirectory()
            if dir_path:
                line_edit.delete(0, tk.END)
                line_edit.insert(0, dir_path)

        def compare_directories(self):
            left_path = self.left_panel["line_edit"].get()
            right_path = self.right_panel["line_edit"].get()

            if not os.path.isdir(left_path) or not os.path.isdir(right_path):
                messagebox.showwarning("提示", "请选择有效的左右目录")
                return

            self.status_entry.config(state=tk.NORMAL)
            self.status_entry.delete(0, tk.END)
            self.status_entry.insert(0, "正在比对，请稍候...")
            self.status_entry.config(state="readonly")
            self.update_idletasks()

            left_files = self.get_all_files(left_path)
            right_files = self.get_all_files(right_path)

            left_set = set(left_files.keys())
            right_set = set(right_files.keys())

            diff_files = set()
            common = left_set & right_set
            for rel_path in common:
                l_path = left_files[rel_path]
                r_path = right_files[rel_path]
                if os.path.isfile(l_path) and os.path.isfile(r_path):
                    if not self.is_file_same(l_path, r_path):
                        diff_files.add(rel_path)

            left_tree = self.build_compare_tree(left_path, "left", right_set, diff_files)
            right_tree = self.build_compare_tree(right_path, "right", left_set, diff_files)

            self.left_panel["tree"].build_tree(left_tree)
            self.right_panel["tree"].build_tree(right_tree)

            only_left_count = sum(1 for f in left_set if f not in right_set)
            only_right_count = sum(1 for f in right_set if f not in left_set)

            msg = f"比对完成。左侧独有: {only_left_count}, 右侧独有: {only_right_count}, 内容不同: {len(diff_files)}"
            self.status_entry.config(state=tk.NORMAL)
            self.status_entry.delete(0, tk.END)
            self.status_entry.insert(0, msg)
            self.status_entry.config(state="readonly")

        def get_all_files(self, root_dir):
            result = {}
            for dirpath, dirnames, filenames in os.walk(root_dir):
                rel_dir = os.path.relpath(dirpath, root_dir)
                if rel_dir == ".":
                    rel_dir = ""

                for d in dirnames:
                    rel_path = os.path.join(rel_dir, d) if rel_dir else d
                    result[rel_path] = os.path.join(dirpath, d)

                for f in filenames:
                    rel_path = os.path.join(rel_dir, f) if rel_dir else f
                    result[rel_path] = os.path.join(dirpath, f)
            return result

        def is_file_same(self, file1, file2):
            try:
                return filecmp.cmp(file1, file2, shallow=False)
            except Exception:
                return False

        def build_compare_tree(self, root_path, side, other_files_set, diff_files_set):
            root_name = os.path.basename(root_path) or root_path
            root_node = TreeNode(root_name, root_path, True, side)

            def traverse(current_path, parent_node, rel_prefix):
                try:
                    entries = os.listdir(current_path)
                except PermissionError:
                    return

                dirs = sorted([e for e in entries if os.path.isdir(os.path.join(current_path, e))])
                files = sorted([e for e in entries if os.path.isfile(os.path.join(current_path, e))])

                for d in dirs:
                    full_path = os.path.join(current_path, d)
                    rel_path = os.path.join(rel_prefix, d) if rel_prefix else d

                    node = TreeNode(d, full_path, True, side)
                    parent_node.children.append(node)

                    if rel_path not in other_files_set:
                        node.status = f"only_{side}"
                        self._mark_all_children(node, f"only_{side}")
                    else:
                        traverse(full_path, node, rel_path)
                        has_diff = any(c.status != 'equal' for c in node.children)
                        if has_diff:
                            node.status = 'diff'
                        else:
                            node.status = 'equal'

                    if node.status != 'equal':
                        node.is_expanded = True

                for f in files:
                    full_path = os.path.join(current_path, f)
                    rel_path = os.path.join(rel_prefix, f) if rel_prefix else f

                    node = TreeNode(f, full_path, False, side)
                    parent_node.children.append(node)

                    if rel_path not in other_files_set:
                        node.status = f"only_{side}"
                    elif rel_path in diff_files_set:
                        node.status = 'diff'
                    else:
                        node.status = 'equal'

            traverse(root_path, root_node, "")

            has_diff = any(c.status != 'equal' for c in root_node.children)
            if has_diff:
                root_node.status = 'diff'
                root_node.is_expanded = True

            return root_node

        def _mark_all_children(self, node, status):
            node.status = status
            if node.is_dir:
                try:
                    entries = os.listdir(node.path)
                except PermissionError:
                    return
                for e in sorted(entries):
                    full_path = os.path.join(node.path, e)
                    is_dir = os.path.isdir(full_path)
                    child = TreeNode(e, full_path, is_dir, node.side)
                    node.children.append(child)
                    self._mark_all_children(child, status)

    # 修复2: 移除错误的 MainCompareWindow 类，直接将 Notebook 放入 compare_window
    notebook = ttk.Notebook(compare_window)
    notebook.pack(fill=tk.BOTH, expand=True, padx=5, pady=5)

    text_tab = TextDiffWidget(notebook)
    dir_tab = DirCompareWidget(notebook)

    notebook.add(text_tab, text="文本比对")
    notebook.add(dir_tab, text="目录比对")

