import math
import sympy
import numpy as np
import matplotlib.pyplot as plt
import mpl_toolkits.axisartist as axisartist
import re
from decimal import Decimal



leftframe2calc = ttk.LabelFrame(frame7gupiaork, text='科学计算器', width=620, height=900)
leftframe2calc.grid(row=0, column=0, rowspan=16, padx=10, pady=10)

