calc_display.grid(row=0, column=0, columnspan=5, padx=5, pady=10)


def clean_number(n):
    """清理浮点数精度偏差，确保如 sin(30) 输出 0.5 而非 0.49999999999999994"""
    if isinstance(n, float):
        # 四舍五入到10位小数，消除大部分浮点运算产生的尾部误差
        rounded = round(n, 10)
        # 如果非常接近整数，直接转为整型
        if abs(rounded - round(rounded)) < 1e-9:
            return int(round(rounded))
        # 如果非常接近 .5 等常见分数，保留一位小数
        if abs(rounded * 2 - round(rounded * 2)) < 1e-9:
            return round(rounded, 1)
        return rounded
    return n


def sin_deg(x):
    return clean_number(math.sin(math.radians(x)))


def cos_deg(x):
    return clean_number(math.cos(math.radians(x)))


def tan_deg(x):
    return clean_number(math.tan(math.radians(x)))


def cot_deg(x):
    # 余切 cot(x) = 1 / tan(x)
    tan_val = math.tan(math.radians(x))
    if abs(tan_val) < 1e-10:
        raise ValueError("Math domain error")
    return clean_number(1.0 / tan_val)


def calc_btn_click(char):
    if char == 'C':
        calc_display.delete('1.0', 'end')
    elif char == 'Del':
        calc_display.delete('end-2c')
    elif char == '=':
        try:
            expr = calc_display.get('1.0', 'end').replace('\n', '')
            expr = expr.replace('^', '**')
            expr = expr.replace('pi', str(math.pi))
            expr = expr.replace('e', str(math.e))

            # 替换三角函数为角度制计算函数，底层自动转弧度并修正浮点偏差
            expr = re.sub(r'(?<!\w)sin\(', 'sin_deg(', expr)
            expr = re.sub(r'(?<!\w)cos\(', 'cos_deg(', expr)
            expr = re.sub(r'(?<!\w)tan\(', 'tan_deg(', expr)
            expr = re.sub(r'(?<!\w)cot\(', 'cot_deg(', expr)
            expr = re.sub(r'(?<!\w)ctan\(', 'cot_deg(', expr)  # 兼容ctan写法

            expr = re.sub(r'(?<!\w)log\(', 'math.log10(', expr)
            expr = re.sub(r'(?<!\w)ln\(', 'math.log(', expr)
            expr = re.sub(r'(?<!\w)sqrt\(', 'math.sqrt(', expr)

            ans = eval(expr)
            calc_display.delete('1.0', 'end')
            calc_display.insert('end', str(ans))
        except Exception:
            calc_display.delete('1.0', 'end')
            calc_display.insert('end', 'Error')
    else:
        calc_display.insert('end', char)


