# ---------------- 简单四则计算 ----------------
def eq_format(eq):
    format_list = re.findall('[\d\.]+|\(|\+|\-|\*|\/|\)', eq)
    return format_list

def change(eq, count):
    if eq[count] == '-':
        if eq[count-1] == '-':
            eq[count-1] = '+'
            del eq[count]
        elif eq[count-1] == '+':
            eq[count-1] = '-'
            del eq[count]
    return eq

def deal_multiplication_division(eq):
    from decimal import Decimal
    count = 0
    for i in eq:
        if i == '*':
            if eq[count+1] != '-':
                eq[count - 1] = Decimal(eq[count - 1]) * Decimal(eq[count + 1])
                del(eq[count])
                del(eq[count])
            elif eq[count+1] == '-':
                eq[count] = Decimal(eq[count - 1]) * Decimal(eq[count + 2])
                eq[count - 1] = '-'
                del(eq[count+1])
                del(eq[count+1])
            eq = change(eq, count-1)
            return deal_multiplication_division(eq)
        elif i == '/':
            if eq[count+1] != '-':
                eq[count - 1] = Decimal(eq[count - 1]) / Decimal(eq[count + 1])
                del(eq[count])
                del(eq[count])
            elif eq[count+1] == '-':
                eq[count] = Decimal(eq[count-1]) / Decimal(eq[count+2])
                eq[count-1] = '-'
                del(eq[count+1])
                del(eq[count+1])
            eq = change(eq, count-1)
            return deal_multiplication_division(eq)
        count = count + 1
    return eq

def deal_plus_minus(eq):
    from decimal import Decimal
    count = 0
    if eq[0] != '-':
        sum_val = Decimal(eq[0])
    else:
        sum_val = Decimal('0.0')
    for i in eq:
        if i == '-':
            sum_val = sum_val - Decimal(eq[count+1])
        elif i == '+':
            sum_val = sum_val + Decimal(eq[count+1])
        count = count + 1
    if sum_val >= 0:
        eq = [str(sum_val)]
    else:
        eq = ['-', str(-sum_val)]
    return eq

def calculate(s_eq):
    if '*' in s_eq or '/' in s_eq:
        s_eq = deal_multiplication_division(s_eq)
    if '+' in s_eq or '-' in s_eq:
        s_eq = deal_plus_minus(s_eq)
    return s_eq

def simplify(format_list):
    bracket = 0
    count = 0
    for i in format_list:
        if i == '(':
            bracket = count
        elif i == ')':
            temp = format_list[bracket + 1 : count]
            new_temp = calculate(temp)
            format_list = format_list[:bracket] + new_temp + format_list[count+1:]
            format_list = change(format_list, bracket)
            return simplify(format_list)
        count = count + 1
    return format_list

def calculator(eq):
    format_list = eq_format(eq)
    s_eq = simplify(format_list)
    ans = calculate(s_eq)
    if len(ans) == 2:
        ans = -float(ans[1])
    else:
        ans = float(ans[0])
    return ans

