def update_units(event=None):
    cat = cmb_cat.get()
    units = unit_data[cat]['units']
    cmb_from['values'] = units
    cmb_to['values'] = units
    cmb_from.current(0)
    if len(units) > 1:
        cmb_to.current(1)
    else:
        cmb_to.current(0)


cmb_cat.bind('<<ComboboxSelected>>', update_units)
update_units()


def do_convert():
    try:
        val = float(ent_val.get())
        cat = cmb_cat.get()
        from_u = cmb_from.get()
        to_u = cmb_to.get()

        if cat == '温度':
            # 统一转换为摄氏度
            if from_u == '摄氏度':
                c = val
            elif from_u == '华氏度':
                c = (val - 32) * 5.0 / 9.0
            elif from_u == '开尔文':
                c = val - 273.15
            elif from_u == '兰氏度':
                c = (val * 5.0 / 9.0) - 273.15
            elif from_u == '列氏度':
                c = val * 5.0 / 4.0
            else:
                c = 0

            # 从摄氏度转换为目标单位
            if to_u == '摄氏度':
                res = c
            elif to_u == '华氏度':
                res = c * 9.0 / 5.0 + 32
            elif to_u == '开尔文':
                res = c + 273.15
            elif to_u == '兰氏度':
                res = (c + 273.15) * 9.0 / 5.0
            elif to_u == '列氏度':
                res = c * 4.0 / 5.0
            else:
                res = 0
        else:
            base_val = val * unit_data[cat]['to_base'][from_u]
            res = base_val / unit_data[cat]['to_base'][to_u]

        lbl_res.config(text='结果: ' + str(round(res, 6)))
    except ValueError:
        lbl_res.config(text='结果: 输入无效')
    except Exception:
        lbl_res.config(text='结果: 错误')


btn_conv.config(command=do_convert)

