# 计算相差天数逻辑
def calc_date_diff():
    try:
        start_str = ent_start.get().strip()
        end_str = ent_end.get().strip()
        start_date = datetime.strptime(start_str, "%Y-%m-%d")
        end_date = datetime.strptime(end_str, "%Y-%m-%d")
        delta = (end_date - start_date).days
        lbl_diff_res.config(text='结果: 相差 ' + str(delta) + ' 天')
    except ValueError:
        lbl_diff_res.config(text='结果: 日期格式错误或无效')
    except Exception:
        lbl_diff_res.config(text='结果: 计算错误')

# 推算目标日期逻辑
def calc_target_date():
    try:
        base_str = ent_base.get().strip()
        days_str = ent_days.get().strip()
        base_date = datetime.strptime(base_str, "%Y-%m-%d")
        days = int(days_str)
        target_date = base_date + timedelta(days=days)
        res_str = target_date.strftime("%Y-%m-%d")
        lbl_calc_res.config(text='结果: ' + res_str)
    except ValueError:
        lbl_calc_res.config(text='结果: 输入格式错误或无效')
    except Exception:
        lbl_calc_res.config(text='结果: 计算错误')

# 绑定按钮事件
btn_calc.config(command=calc_target_date)
btn_diff.config(command=calc_date_diff)




