def printpage():
    # from docx import Document
    from docx.shared import Inches
    shutil.copy('template.docx', 'toprint2.docx')
    doc = docx.Document('toprint2.docx')

    # word里表格里替换文字
    def replace_table_content():
        # 加载Word文档 # doc = Document(file_path)  # 遍历文档中的所有表格
        for table in doc.tables:  # 遍历表格中的每一行
            for row in table.rows:  # 遍历行中的每一个单元格
                for cell in row.cells:  # 替换单元格中的内容

                    cell.text = cell.text.replace('input_plan_date', input_plan_date.get())
                    cell.text = cell.text.replace('input_plan_time', input_plan_time.get())
                    cell.text = cell.text.replace('input_plan_plan', input_plan_plan.get())

        doc.save('toprint2.docx')  # 保存到一个新文件

    replace_table_content()  # 替换文字结束
    time.sleep(1)
    def center_insert_img(doc):
        # 在单元格中插入图片
        for table in doc.tables:  # 遍历表格中的每一行
            for row in table.rows:   # 遍历行中的每一个单元格
                for cell in row.cells:

                    if 'input_showpic01' in cell.text:
                        cell.text = cell.text.replace('\n', '')   # 替换单元格中的内容

                        cell.text = cell.text.replace('input_showpic01', '')

                        run=cell.paragraphs[0].add_run('')
                        run.add_break()
                        # print('\nhaha'+input_plan_plan.get())
                        mysmallpic = input_plan_plan.get().split('[+]')[-1]
                        if ':' not in mysmallpic:
                            getplanpicpathr3 = os.getcwd() + mysmallpic
                            mysmallpic2 = getplanpicpathr3.replace('./', '\\').replace('/', '\\')
                        # image_file_path2 = image_file_path.replace('./zsssimages\\.\\\\\\\\zsssimages\\\\\\\\', './zsssimages/')
                        else:
                            mysmallpic2 = mysmallpic


                        run.add_picture(mysmallpic2, width=Inches(1.1))

                    if '[+]' in cell.text:
                        gansita = input_plan_plan.get()
                        cell.text = cell.text.replace(gansita, gansita.split('[+]')[-2])

    tpl_doc = 'toprint2.docx'  # res_doc = 'toprint2.docx'
    global res_doc
    res_doc = asksaveasfilename(initialfile='任务计划.docx' ,
                                defaultextension='.docx',filetypes=[('docx files', '.docx')])  # 打开模板文件

    document = docx.Document(tpl_doc)  # 插入图片居中
    try:
        center_insert_img(document)
    except:
        pass
    document.save(res_doc)

    os.startfile(res_doc)
    os.remove('toprint2.docx')
