        def yearInfo2yearDay(yearInfo):
            yearInfo = int(yearInfo)
            res = 29 * 12
            leap = False
            if yearInfo % 16 != 0:
                leap = True
                res += 29
            yearInfo //= 16
            for i in range(12 + leap):
                if yearInfo % 2 == 1:
                    res += 1
                yearInfo //= 2
            return res

        def yearDays():
            yearDays = [Info.yearInfo2yearDay(x) for x in Info.yearInfos]
            return yearDays

        def day2LunarDate(offset):
            offset = int(offset)
            res = LunarDate()
            for idx, yearDay in enumerate(yearDays()):
                if offset < yearDay:
                    break
                offset -= yearDay
            res.year = 1900 + idx

