def csv2mtb():
    showinfo('提示', '选择一个utf8-csv文件(如rogabet-note\stock里csv表).')
    csvstPath = askopenfilename(defaultextension='.csv')
    import csv
    filename = csvstPath
    with open(filename, 'r',encoding='utf8')as file:
        # 1.创建阅读器对象
        reader = csv.reader(file)
        # 2.读取文件头信息
        header_row = next(reader)
        print(header_row)
    from datetime import datetime
    from matplotlib import pyplot as plt
    plt.rcParams['font.sans-serif'] = ['SimHei']
    # 指定默认字体
    plt.rcParams['axes.unicode_minus'] = False
    # 解决保存图像是负号'-'显示为方块的问题
    filename = csvstPath
    with open(filename, 'r',encoding='utf8')as file:
        # 1.创建阅读器对象
        reader = csv.reader(file)
        # 2.读取文件头信息
        header_row = next(reader)
        # 3.保存最高气温数据
        dates, hights = [], []
        for row in reader:
            dates.append(row[0])
            hights.append(eval(row[1]))
        # 5.根据数据绘制图形
        fig = plt.figure(dpi=128, figsize=(10, 6))
        # 6.将列表hights传个plot()方法
        plt.plot(dates, hights, c='red')

        # 7.设置图形的格式
        boyandgirl = title_all_chart.get(0.0, 'end')
        plt.title(boyandgirl, fontsize=24)
        plt.xlabel('', fontsize=6)
        # 8.绘制斜线日期标签
        #fig.autofmt_xdate()
        plt.ylabel('', fontsize=6)
        plt.tick_params(axis='both', which='major', labelsize=6,rotation=90)
        plt.show()
