def change_liedeshunxu():
    import xlwings as xw
    import pandas as pd

    # 获取用户输入的列顺序并清理空白字符
    raw_text = liedeshunxutxt.get(1.0, 'end')
    new_liedeshunxu = raw_text.replace('\n', '').replace('\t', ' ')
    target_columns = [col.strip() for col in new_liedeshunxu.split(' ') if col.strip()]

    if not target_columns:
        print("未检测到有效的列名顺序，请重新输入。")
        return

    filenamepath = askopenfilename()
    if not filenamepath:
        return

    # 启动 Excel 程序并关闭屏幕更新与警告，大幅提升运行速度并防止弹窗打断
    app = xw.App(visible=False, add_book=False)
    app.screen_updating = False
    app.display_alerts = False

    try:
        workbook = app.books.open(filenamepath)

        # 遍历所有工作表
        for sheet in workbook.sheets:
            # 获取当前工作表的第一行表头
            header_range = sheet.range('A1').expand('right')
            headers = header_range.value

            # 兼容单列和多列表头的数据类型
            if isinstance(headers, str):
                headers = [headers]
            elif headers is None:
                continue

                # 筛选出当前工作表中实际存在的目标列
            current_target_cols = [col for col in target_columns if col in headers]
            if not current_target_cols:
                continue

            curr_cols = list(headers)

            # 核心逻辑：通过底层 COM API 进行列的剪切与插入
            for i, col_name in enumerate(current_target_cols):
                if col_name in curr_cols:
                    j = curr_cols.index(col_name)
                    # 如果当前列已经在目标位置，则跳过
                    if i != j:
                        # 使用 Excel 原生 API 剪切第 j+1 列，并插入到第 i+1 列之前
                        # 此操作会100%保留格式、颜色，并自动更新所有相关公式的引用
                        sheet.api.Columns(j + 1).Cut()
                        sheet.api.Columns(i + 1).Insert()

                        # 同步更新内存中的列名顺序列表，以便下一次循环匹配
                        curr_cols.insert(i, curr_cols.pop(j))

        # 弹出另存为对话框
        outtiqushunxu = asksaveasfilename(
            initialfile='未命名-表.xlsx',
            defaultextension='.xlsx',
            filetypes=[('xlsx files', '.xlsx')]
        )

        if outtiqushunxu:
            workbook.save(outtiqushunxu)
            workbook.close()
            os.startfile(outtiqushunxu)
        else:
            workbook.close()

    except Exception as e:
        print(f"处理过程中发生错误: {e}")
    finally:
        # 恢复 Excel 设置并退出
        app.screen_updating = True
        app.display_alerts = True
        app.quit()

