class BaiduDocTranslatorWd3:
    def __init__(self, appid, seckey):
        self.appid = appid
        self.seckey = seckey

    def _create_sign(self, timestamp, json_str):
        sign_str = f"{self.appid}{timestamp}{json_str}"
        sign_bytes = hmac.new(self.seckey.encode('utf-8'), sign_str.encode('utf-8'), digestmod=hashlib.sha256).digest()
        return base64.b64encode(sign_bytes).decode('utf-8')

    def _create_headers(self, timestamp, sign):
        return {
            'Content-Type': 'application/json',
            'X-Appid': self.appid,
            'X-Sign': sign,
            'X-Timestamp': str(timestamp)
        }

    def create_trans_job(self, from_lang, to_lang, file_path):
        url = 'https://fanyi-api.baidu.com/transapi/doctrans/createjob/trans'
        with open(file_path, 'rb') as f:
            content_base64 = base64.b64encode(f.read()).decode('utf-8')

        file_name = os.path.basename(file_path)
        file_ext = os.path.splitext(file_name)[1][1:].lower()

        input_data = {
            'from': from_lang,
            'to': to_lang,
            'input': {
                'content': content_base64,
                'format': file_ext,
                'filename': file_name
            },
            'output': {
                'format': file_ext
            }
        }

        json_str = json.dumps(input_data, ensure_ascii=False)
        timestamp = int(time.time())
        sign = self._create_sign(timestamp, json_str)
        headers = self._create_headers(timestamp, sign)

        response = requests.post(url, headers=headers, data=json_str.encode('utf-8'))
        return response.json()

    def query_trans(self, request_id):
        url = 'https://fanyi-api.baidu.com/transapi/doctrans/query/trans'
        input_data = {'requestId': request_id}
        json_str = json.dumps(input_data, ensure_ascii=False)
        timestamp = int(time.time())
        sign = self._create_sign(timestamp, json_str)
        headers = self._create_headers(timestamp, sign)

        response = requests.post(url, headers=headers, data=json_str.encode('utf-8'))
        return response.json()


def gaoji2renheeyubdpil2zdwd3():
    def gaoji2renheeyubdpil2zdwd3_th():
        showinfo('提示', '选择文件夹-把里边所有docx pptx xlsx pdf txt html xml格式文档翻译为已选语言。')
