def tpzjfyksjp2cnpl(): #jp to cn tp wcpl
    showinfo('提示', '选择文件夹-把里边所有日语 bmp jpg jpeg png格式图片日语翻译为中文。')
    pilfanyiwhere = askdirectory() + '/'  # 批量翻译文档来源
