    print(piliangfanyitaskwhere)
    # 批量翻译输出位置
    dirname = piliangfanyitaskwhere
    dirnameout = piliangfanyitaskwhere
    filenames = os.listdir(dirname)

    def gaoji2renhetpjpbd_pl2(filename, output_filename): #jp to cn tp

        try:
            filefanyi = filename
            print(filefanyi)
            filetype = filefanyi.split('.')[-1]
            filetype2 = filetype.lower()
            filefrontname = filefanyi.split('.')[-2]
            filefanyi2url = filefrontname.split('/')[-1]
            print(filetype)
            print(filefanyi2url)
            time.sleep(2)
            host3tp = jpgpngtransvalue2
            response_token = requests.get(host3tp)
            token = response_token.json()['access_token']
            print(token)
            filefanyiname = filefanyi
            url = 'https://aip.baidubce.com/file/2.0/mt/pictrans/v1?access_token=' + token

            from_lang = 'jp'
            to_lang = 'zh'

            # Build request
            payload = {'from': from_lang, 'to': to_lang, 'v': '3', 'paste': '1'}
            # image = {'image': (os.path.basename(filefanyi2url), open(filefanyiname, 'rb'), "multipart/form-data")}
            image = {'image': ('myfile', open(filefanyiname, 'rb'), "multipart/form-data")}
            # Send request
            response = requests.post(url, params=payload, files=image)
            result = response.json()
            # time.sleep(2)
            result2 = response.json()['data']['sumDst']
            # ['output']['files']['url']
            # print(json.dumps(result2, indent=4, ensure_ascii=False))
            print(result2)
            tpfyneirong = result2
            tpfytxtpath = filefrontname + '.txt'
            tpfytxtpath=output_filename
            fftpzjfy = open(tpfytxtpath, "wt").write(tpfyneirong)
            # 附送图片
            result3img64code = response.json()['data']['pasteImg']
            tpfytxtpathoutpng = filefrontname + '_jp2cn.png'
            fp_64codeimg = open(tpfytxtpathoutpng, 'wb')
            img64content = base64.b64decode(result3img64code)

            fp_64codeimg.write(img64content)
            fp_64codeimg.close()

            runingpb()

        except:
            showinfo('注意', '图片太大超过4兆或没有字-先等这批跑完后去编辑没有翻译出的部分图-先别关闭本软件-等进度条和最后的全部完成提示..')
        # webbrowser.open(play_url)

    for filename in filenames:
        if filename.endswith('jpg') or filename.endswith('jpeg') or filename.endswith('png') or filename.endswith(
                'bmp') or filename.endswith('JPG') or filename.endswith('JPEG') or filename.endswith(
            'webp') or filename.endswith('tiff'):

            base, ext = filename.split('.')
            new_name =  base + '_jp2cn' +'.txt'
            filename = dirname + '/' + filename
            output_filename = dirnameout + '/' + new_name
            try:
                gaoji2renhetpjpbd_pl2(filename, output_filename)
                print(filename)
            except:
                pass
    showinfo('提示', '所有bmp jpg jpeg png格式图片翻译完成。')

