def get_from_lang():
    dialog = tk.Toplevel()
    dialog.title("选择图片原始语言")
    dialog.geometry("250x150")
    dialog.resizable(False, False)

    tk.Label(dialog, text="请选择图片原始语言:").pack(pady=15)

    combo = ttk.Combobox(dialog, values=list(LANG_OPTIONS.keys()), state="readonly", width=20)
    combo.set("自动检测")
    combo.pack(pady=5)

    result = {"lang": "auto"}

    def on_confirm():
        result["lang"] = LANG_OPTIONS.get(combo.get(), "auto")
        dialog.destroy()

    tk.Button(dialog, text="确定", command=on_confirm, width=10).pack(pady=15)

    dialog.transient()
    dialog.grab_set()
    dialog.wait_window()

    return result["lang"]


