    def fix_base64_padding(b64_str):
        b64_str = re.sub(r'[^A-Za-z0-9+/=]', '', b64_str)
        missing_padding = len(b64_str) % 4
        if missing_padding:
            b64_str += '=' * (4 - missing_padding)
        return b64_str

