def gaoji2rentpbdpil2zdybf():
    from threading import Thread
    from tkinter import messagebox, filedialog
    from concurrent.futures import ThreadPoolExecutor, as_completed
    def gaoji2rentpbdpil2zdy_th():
        messagebox.showinfo('提示', '选择文件夹-把里边所有 bmp jpg jpeg png格式图片翻译为选定的x语言。')
        pilfanyiwhere = filedialog.askdirectory() + '/'

        t1yibdleftxlsxframe.delete(0.0, 'end')
        t1yibdleftxlsxframe.insert(0.0, pilfanyiwhere)
        piliangfanyitaskwhere = t1yibdleftxlsxframe.get(0.0, 'end').replace('\n', '')
        print(piliangfanyitaskwhere)

        dirname = piliangfanyitaskwhere
        dirnameout = piliangfanyitaskwhere
        filenames = os.listdir(dirname)

        def gaoji2renhetpautozdybd_pl2(filefanyi, output_filename):
            filefrontname = filefanyi.rsplit('.', 1)[0]
            filefanyi2url = os.path.basename(filefrontname)

            host3tp = jpgpngtransvalue2
            response_token = requests.get(host3tp)
            token = response_token.json()['access_token']

            url = 'https://aip.baidubce.com/file/2.0/mt/pictrans/v1?access_token=' + token
            from_lang = 'auto'
            to_lang = cutwanteditityylang_PL

            payload = {'from': from_lang, 'to': to_lang, 'v': '3', 'paste': '1'}

            with open(filefanyi, 'rb') as f:
                image = {'image': ('myfile', f, "multipart/form-data")}
                response = requests.post(url, params=payload, files=image)

            result = response.json()
            result2 = result['data']['sumDst']

            with open(output_filename, "wt", encoding='utf-8') as f:
                f.write(result2)

            result3img64code = result['data']['pasteImg']
            tpfytxtpathoutpng = filefrontname + '_auto2%s.png' % cutwanteditityylang_PL
            img64content = base64.b64decode(result3img64code)

            with open(tpfytxtpathoutpng, 'wb') as fp:
                fp.write(img64content)

            runingpb()

        task_list = []
        for filename in filenames:
            lower_name = filename.lower()
            if lower_name.endswith(('.jpg', '.jpeg', '.png', '.bmp', '.webp', '.tiff')):
                base = filename.rsplit('.', 1)[0]
                new_name = base + '_auto2%s.txt' % cutwanteditityylang_PL
                full_path = os.path.join(dirname, filename)
                output_path = os.path.join(dirnameout, new_name)
                task_list.append((full_path, output_path, filename))

        pending_tasks = list(task_list)
        max_retries = 3
        retry_count = 0

        while pending_tasks and retry_count < max_retries:
            with ThreadPoolExecutor(max_workers=2) as executor:
                futures = {executor.submit(gaoji2renhetpautozdybd_pl2, task[0], task[1]): task for task in
                           pending_tasks}

                next_pending = []
                for future in as_completed(futures):
                    task = futures[future]
                    try:
                        future.result()
                    except Exception as e:
                        next_pending.append(task)
                        print(f"任务失败，等待重试: {task[2]}")

                pending_tasks = next_pending
            retry_count += 1
            if pending_tasks:
                time.sleep(2)

        if pending_tasks:
            error_files = [task[2] for task in pending_tasks]
            messagebox.showinfo('注意',
                                '不支持的翻译语言或图片太大超过4兆或没有字，以下文件未完成: ' + ', '.join(error_files))

        messagebox.showinfo('提示', '所有bmp jpg jpeg png格式图片翻译完成。')

    th17rhyyrhtpfypl = Thread(target=gaoji2rentpbdpil2zdy_th)
    th17rhyyrhtpfypl.start()

